import Foundation
import SwiftData

/// Canonical request envelope for the Agent Kernel migration.
///
/// All user-visible, voice, AppIntent, trigger, diagnostic, and benchmark turns
/// should eventually enter the assistant through `AssistantKernel.run(...)` using
/// this request. Runtime-specific and legacy service options should be adapted
/// before the kernel boundary, not threaded around it.
nonisolated struct AgentKernelRequest: Sendable, Equatable, Identifiable {
    let id: UUID
    let conversationID: UUID?
    let turnID: UUID?
    let userMessage: String
    let history: [AgentKernelMessage]
    let systemPrompt: String
    let relevantMemories: [MemoryContextItem]
    let attachments: [ChatAttachment]
    let task: AssistantTaskKind
    let source: AgentKernelSource
    let options: AgentKernelOptions

    init(
        id: UUID = UUID(),
        conversationID: UUID? = nil,
        turnID: UUID? = nil,
        userMessage: String,
        history: [AgentKernelMessage] = [],
        systemPrompt: String = "",
        relevantMemories: [MemoryContextItem] = [],
        attachments: [ChatAttachment] = [],
        task: AssistantTaskKind = .chat,
        source: AgentKernelSource = .chat,
        options: AgentKernelOptions = .chat
    ) {
        self.id = id
        self.conversationID = conversationID
        self.turnID = turnID
        self.userMessage = userMessage
        self.history = history
        self.systemPrompt = systemPrompt
        self.relevantMemories = relevantMemories
        self.attachments = attachments
        self.task = task
        self.source = source
        self.options = options
    }
}

nonisolated struct AgentKernelMessage: Codable, Sendable, Equatable, Hashable {
    enum Role: String, Codable, Sendable {
        case system
        case user
        case assistant
        case tool

        init(messageRole: MessageRole) {
            switch messageRole {
            case .system: self = .system
            case .user: self = .user
            case .assistant: self = .assistant
            case .tool: self = .tool
            }
        }

        var messageRole: MessageRole {
            switch self {
            case .system: return .system
            case .user: return .user
            case .assistant: return .assistant
            case .tool: return .tool
            }
        }
    }

        self.stage = stage
        self.message = message
        self.metadata = metadata
    }
}

nonisolated enum AgentKernelEvent: Sendable {
    case step(AgentStep)
    case stepDelta(id: UUID, text: String)
    case token(String)
    case finalDelta(String)
    case toolInvocation(ToolInvocation)
    case toolResult(ToolResult)
    case diagnostic(AgentKernelDiagnosticEvent)
    case final(String)
    case done(finalText: String, steps: [AgentStep])
    case error(String)
}

@MainActor
protocol AgentKernelRunning: AnyObject {
    func run(_ request: AgentKernelRequest, modelContext: ModelContext?) -> AsyncStream<AgentKernelEvent>
}

extension AgentKernelEvent {
    /// Temporary compatibility shim while ChatView/Voice/Headless entrypoints
    /// are migrated from `AgentEvent` to kernel-native events.
    nonisolated var legacyAgentEvent: AgentEvent? {
        switch self {
        case .step(let step):
            return .step(step)
        case .stepDelta(let id, let text):
            return .stepDelta(id: id, text: text)
        case .token(let text), .finalDelta(let text):
            return .finalDelta(text)
        case .final:
            return nil
        case .done(let finalText, let steps):
            return .done(finalText: finalText, steps: steps)
        case .error(let message):
            return .error(message)
        case .toolInvocation, .toolResult, .diagnostic:
            return nil
        }
    }
}

extension AgentKernelSource {
    var toolInvocationSource: ToolInvocationSource {
        switch self {
        case .chat, .voice, .diagnostics, .benchmark:
            return .modelProposed
        case .appIntent:
            return .appIntent
        case .trigger:
            return .backgroundTrigger
        }
    }

    var isForeground: Bool {
        switch self {
        case .chat, .voice, .appIntent, .diagnostics, .benchmark:
            return true
        case .trigger:
            return false
        }
    }
}

import Foundation
import SwiftData

nonisolated struct AgentKernelRunOptions: @unchecked Sendable {
    nonisolated enum GroundingMode: Sendable, Equatable {
        case foregroundChat
        case headlessTrigger
        case slotAgent
        case rolePipeline
    }

    let modelContext: ModelContext?
    let conversationID: UUID?
    let turnID: UUID?
    let groundingMode: GroundingMode
    let allowDegradedGrounding: Bool
    let preventDoubleGrounding: Bool
    let diagnosticsEnabled: Bool

    static var `default`: AgentKernelRunOptions {
        .init(
            modelContext: nil,
            conversationID: nil,
            turnID: nil,
            groundingMode: .foregroundChat,
            allowDegradedGrounding: true,
            preventDoubleGrounding: true,
            diagnosticsEnabled: false
        )
    }
}

extension AgentKernelRunOptions {
    init(_ legacy: LegacyAgentRunOptions) {
        self.init(
            modelContext: legacy.modelContext,
            conversationID: legacy.conversationID,
            turnID: legacy.turnID,
            groundingMode: .init(legacy.groundingMode),
            allowDegradedGrounding: legacy.allowDegradedGrounding,
            preventDoubleGrounding: legacy.preventDoubleGrounding,
            diagnosticsEnabled: legacy.diagnosticsEnabled
        )
    }
}

extension AgentKernelRunOptions.GroundingMode {
    init(_ legacy: LegacyAgentRunOptions.GroundingMode) {
        switch legacy {
        case .foregroundChat: self = .foregroundChat
        case .headlessTrigger: self = .headlessTrigger
        case .slotAgent: self = .slotAgent
        case .rolePipeline: self = .rolePipeline
        }
    }

    var legacyGroundingMode: LegacyAgentRunOptions.GroundingMode {
        switch self {
        case .foregroundChat: return .foregroundChat
        case .headlessTrigger: return .headlessTrigger
        case .slotAgent: return .slotAgent
        case .rolePipeline: return .rolePipeline
        }
    }
}

extension LegacyAgentRunOptions {
    init(_ kernel: AgentKernelRunOptions) {
        self.init(
            modelContext: kernel.modelContext,
            conversationID: kernel.conversationID,
            turnID: kernel.turnID,
            groundingMode: kernel.groundingMode.legacyGroundingMode,
            allowDegradedGrounding: kernel.allowDegradedGrounding,

            preventDoubleGrounding: kernel.preventDoubleGrounding,
            diagnosticsEnabled: kernel.diagnosticsEnabled
        )
    }
}

import Foundation
import SwiftData

extension AssistantKernel: AgentKernelRunning {
    func run(_ request: AgentKernelRequest, modelContext: ModelContext? = nil) -> AsyncStream<AgentKernelEvent> {
        AsyncStream { continuation in
            let task = Task { @MainActor in
                let start = Date()
                var emittedSteps: [AgentStep] = []

                func emitStep(_ kind: AgentStep.Kind, _ content: String, toolID: String? = nil, toolArgs: [String: String]? = nil) {
                    let step = AgentStep(kind: kind, content: content, toolID: toolID, toolArgs: toolArgs)
                    emittedSteps.append(step)
                    continuation.yield(.step(step))
                }

                emitStep(.thought, "Agent Kernel accepted \(request.source.rawValue) turn for \(String(describing: request.task)).")
                let historyTuples = request.history.map { (role: $0.role.messageRole, content: $0.content) }
                let referenceResolution = ReferenceResolver.resolve(
                    prompt: request.userMessage,
                    history: historyTuples,
                    relevantMemories: request.relevantMemories
                )
                let effectiveUserMessage = referenceResolution.rewrittenPrompt

                if request.supportsDeterministicToolBridge {
                    let routing = IntentRouter.classify(effectiveUserMessage)
                    if IntentRouter.intentRequiresTool(routing) {
                        let backgroundAssessment: BackgroundToolBridgeAssessment?
                        let availableTools: [ToolDefinition]
                        if request.requiresBackgroundSafeToolBridge {
                            let assessment = await BackgroundToolBridgePolicy.assess(
                                prompt: effectiveUserMessage,
                                routing: routing,
                                modelContext: modelContext,
                                toolRegistry: toolRegistry,
                                metricsStore: metricsStore
                            )
                            backgroundAssessment = assessment
                            availableTools = assessment.availableTools
                        } else {
                            backgroundAssessment = nil

    availableTools = await toolBridgeAvailableTools(
        for: request,
        userMessage: effectiveUserMessage,
        routing: routing,
        modelContext: modelContext
    )
}

if let backgroundAssessment, !backgroundAssessment.canRunWithoutLoadedTextRuntime {
    if request.options.diagnosticsEnabled {
        continuation.yield(.diagnostic(.init(
            stage: "background-tool-bridge",
            message: backgroundAssessment.skipMessage,
            metadata: backgroundAssessment.diagnosticMetadata.merging([
                "source": request.source.rawValue,
                "task": String(describing: request.task)
            ], uniquingKeysWith: { current, _ in current })
        )))
    }
    emitStep(.observation, backgroundAssessment.skipMessage)
    continuation.yield(.final(backgroundAssessment.skipMessage))
    continuation.yield(.done(finalText: backgroundAssessment.skipMessage, steps: emittedSteps))
    continuation.finish()
    return
}

if request.options.diagnosticsEnabled {
    continuation.yield(.diagnostic(.init(
        stage: "tool-routing-bridge",
        message: "Routing tool-backed \(String(describing: request.task)) turn through deterministic legacy bridge",
        metadata: [
            "intent": routing.intent.rawValue,
            "allowedToolIDs": routing.allowedToolIDs.sorted().joined(separator: ","),
            "availableToolIDs": availableTools.map(\.id).sorted().joined(separator: ","),
            "mode": request.requiresBackgroundSafeToolBridge ? "background-safe" : "foreground",

            "thermalState": "\(thermalState.rawValue)",
            "maxTokens": String(min(request.options.maxTokens, computeDecision.maxTokens))
        ]
    )))
}

if let modelContext, request.options.diagnosticsEnabled {
    let grounding = await buildGroundingContext(turn: turn, modelContext: modelContext)
    continuation.yield(.diagnostic(.init(
        stage: "grounding",
        message: "Grounding context prepared",
        metadata: [
            "memoryCount": String(grounding.memoryCount),
            "ragCount": String(grounding.ragCount),
            "toolCount": String(grounding.toolCount),
            "estimatedChars": String(grounding.estimatedChars),
            "estimatedTokens": String(grounding.estimatedTokens),
            "contextProfile": grounding.contextProfile ?? "unknown",
            "maxInputTokens": grounding.maxInputTokens.map(String.init) ?? "unknown",
            "ragConfidence": grounding.ragConfidence.map { String(format: "%.3f", $0) } ?? "unknown",
            "selfModelIncluded": String(grounding.selfModelIncluded ?? false),
            "selfModelSchemaVersion": grounding.selfModelSchemaVersion ?? "unknown",
            "selfModelMode": grounding.selfModelMode ?? "unknown",
            "selfModelEstimatedChars": grounding.selfModelEstimatedChars.map(String.init) ?? "unknown"
        ]
    )))
}

do {
    let output = try await runTextTurn(turn)
    let finalText = request.options.requireUserVisibleFinal
        ? FinalOutputSanitizer.sanitizeUserVisibleText(output).text
        : output
    if !finalText.isEmpty {
        continuation.yield(.finalDelta(finalText))
        continuation.yield(.final(finalText))
    }
    let elapsed = Int(Date().timeIntervalSince(start) * 1000)
    if request.options.diagnosticsEnabled {

                        continuation.yield(.diagnostic(.init(
                            stage: "complete",
                            message: "Agent Kernel turn completed",
                            metadata: [
                                "latencyMs": String(elapsed),
                                "runtime": selectedRuntime.rawValue
                            ]
                        )))
                    }
                    continuation.yield(.done(finalText: finalText, steps: emittedSteps))
                } catch {
                    let message = RuntimeMetricErrorSanitizer.code(for: error)
                    emitStep(.observation, "Agent Kernel failed: \(message)")
                    continuation.yield(.error(message))
                }

                continuation.finish()
            }

            continuation.onTermination = { @Sendable _ in
                task.cancel()
            }
        }
    }

    func runLegacyAgentBridge(_ request: AgentRequest, options: LegacyAgentRunOptions) -> AsyncStream<AgentKernelEvent> {
        LegacyAgentCompatibilityBridge.runLegacyAgentService(request, options: options)
    }

    private func toolBridgeAvailableTools(
        for request: AgentKernelRequest,
        userMessage: String,
        routing: IntentRoutingDecision,
        modelContext: ModelContext?
    ) async -> [ToolDefinition] {
        let routedIDs = Set(routing.allowedToolIDs.map { ToolRouteGuard.canonicalToolID($0) })
        guard request.requiresBackgroundSafeToolBridge else {
            return ToolRegistry.all.filter { routedIDs.contains(ToolRouteGuard.canonicalToolID($0.id)) }
        }

        return await BackgroundToolBridgePolicy.availableTools(
            for: userMessage,
            routing: routing,
            modelContext: modelContext,
            toolRegistry: toolRegistry,
            metricsStore: metricsStore
        )
    }
}

private extension AgentKernelRequest {
    var supportsDeterministicToolBridge: Bool {
        task == .chat || task == .backgroundTrigger
    }

    var requiresBackgroundSafeToolBridge: Bool {
        task == .backgroundTrigger || source == .trigger
    }
}

