struct EntitlementAuditWarning: Sendable, Equatable {
    let code: String
    let message: String
}

enum BackgroundEntitlementValidator {
    static let requiredTaskIDs: Set<String> = [
        TriggerScheduler.refreshIdentifier,
        TriggerScheduler.processIdentifier,
        TriggerScheduler.continuedProcessingIdentifierPattern
    ]

    static func validate(infoDictionary: [String: Any]) -> [EntitlementAuditWarning] {
        var warnings: [EntitlementAuditWarning] = []
        let permitted: Set<String>
        if let values = infoDictionary["BGTaskSchedulerPermittedIdentifiers"] as? [String] {
            permitted = Set(values)
        } else if let value = infoDictionary["BGTaskSchedulerPermittedIdentifiers"] as? String {
            permitted = Set(value.split { $0 == " " || $0 == ";" || $0 == "," }.map(String.init))
        } else {
            permitted = []
        }
        for required in requiredTaskIDs where !permitted.contains(required) {
            warnings.append(.init(code: "missing_bg_task_id", message: "Missing BG task identifier: \(required)"))
        }

        let keyChecks: [[String]] = [
            ["NSMicrophoneUsageDescription"],
            ["NSSpeechRecognitionUsageDescription"],
            ["NSLocationAlwaysAndWhenInUseUsageDescription", "NSLocationAlwaysUsageDescription"],
            ["NSCalendarsUsageDescription", "NSCalendarsFullAccessUsageDescription", "NSCalendarsWriteOnlyAccessUsageDescription"],
            ["NSContactsUsageDescription"]
        ]
        for alternatives in keyChecks where !alternatives.contains(where: { (infoDictionary[$0] as? String)?.isEmpty == false }) {
            warnings.append(.init(code: "missing_usage_description", message: "Missing usage description: \(alternatives.joined(separator: " or "))"))
        }

        let backgroundModes: Set<String>
        if let values = infoDictionary["UIBackgroundModes"] as? [String] {
            backgroundModes = Set(values)
        } else if let value = infoDictionary["UIBackgroundModes"] as? String {
            backgroundModes = Set(value.split { $0 == " " || $0 == ";" || $0 == "," }.map(String.init))
        } else {
            backgroundModes = []
        }
        for required in ["audio", "fetch", "location", "processing"] where !backgroundModes.contains(required) {

            warnings.append(.init(code: "missing_background_mode", message: "Missing background mode: \(required)"))
        }
        return warnings
    }
}

import Foundation

actor BackgroundExecutionLease {
    struct Lease: Sendable, Equatable {
        let category: String
        let reason: String
        let acquiredAt: Date
        let expiresAt: Date
    }

    private var leases: [String: Lease] = [:]

    func acquire(category: String, reason: String, ttl: TimeInterval = 300, now: Date = Date()) -> Bool {
        cleanupExpired(now: now)
        guard leases[category] == nil else { return false }
        leases[category] = Lease(category: category, reason: reason, acquiredAt: now, expiresAt: now.addingTimeInterval(ttl))
        return true
    }

    func release(category: String) {
        leases.removeValue(forKey: category)
    }

    func activeLease(category: String, now: Date = Date()) -> Lease? {
        cleanupExpired(now: now)
        return leases[category]
    }

    private func cleanupExpired(now: Date) {
        leases = leases.filter { $0.value.expiresAt > now }
    }
}

