func runProcessingMaintenance(until deadline: Date) async {
    guard await continueProcessing(before: .memoryConsolidation, deadline: deadline) else { return }
    await runMemoryConsolidationIfAllowed()

    guard await continueProcessing(before: .ragMaintenance, deadline: deadline) else { return }
    await runRAGMaintenanceIfAllowed()

    guard await continueProcessing(before: .modelHousekeeping, deadline: deadline) else { return }
    await runModelHousekeepingIfAllowed()
}

private func handleBackgroundTask(_ task: BGTask, runProcessingWork: Bool) async {
    schedule()
    task.expirationHandler = { task.setTaskCompleted(success: false) }
    guard let container = SharedContainer.shared else {
        await appendSharedContainerUnavailable(taskKind: .triggerScan)

        task.setTaskCompleted(success: true)
        return
    }
    let deadline = Date().addingTimeInterval(4.5)
    let context = ModelContext(container)
    await runTriggerScan(context: context)
    if runProcessingWork, Date() < deadline {
        await runProcessingMaintenance(until: deadline)
    }
    task.setTaskCompleted(success: true)
}

private func triggerScanDecision() -> BackgroundTaskDecision {
    let snapshot = ResourceBudgetGate.diagnosticSnapshot()
    return BackgroundTaskPolicy.decide(.init(
        taskKind: .triggerScan,
        lowPowerMode: snapshot.lowPowerModeEnabled ?? ProcessInfo.processInfo.isLowPowerModeEnabled,
        thermalState: snapshot.thermalState ?? .unknown,
        isForeground: snapshot.scenePhase == .active,
        backgroundAgentsEnabled: true,
        requiresNetwork: false,
        estimatedCost: 1
    ))
}

private func maintenanceDecision(
    taskKind: BackgroundTaskKind,
    requiresNetwork: Bool = false,
    estimatedCost: Int
) -> BackgroundTaskDecision {
    guard ResourceBudgetGate.allowsMaintenance(reason: ModelLoadIntent.background.rawValue) else {
        return .init(
            allow: false,
            denyReason: "resource budget denied maintenance",
            maxSteps: 0,
            maxTokens: 0,
            allowModelLoading: false,
            allowNetwork: false
        )
    }
    let snapshot = ResourceBudgetGate.diagnosticSnapshot()
    return BackgroundTaskPolicy.decide(.init(
        taskKind: taskKind,
        lowPowerMode: snapshot.lowPowerModeEnabled ?? ProcessInfo.processInfo.isLowPowerModeEnabled,
        thermalState: snapshot.thermalState ?? .unknown,
        isForeground: snapshot.scenePhase == .active,
        backgroundAgentsEnabled: true,
        requiresNetwork: requiresNetwork,
        estimatedCost: estimatedCost
    ))
}

private func appendMetric(
    taskKind: BackgroundTaskKind,
    policySummary: String,
    success: Bool,
    errorCode: String? = nil,
    latencyMs: Int? = nil
) async {
    try? await metrics.appendMetric(RuntimeMetric(
        timestamp: Date(),
        runtimeName: "background",

            taskKind: taskKind.rawValue,
            modelIDHash: nil,
            policySummary: policySummary,
            latencyMs: latencyMs,
            success: success,
            errorCode: errorCode,
            thermalState: .from(processThermalState: ProcessInfo.processInfo.thermalState),
            lowPowerMode: ProcessInfo.processInfo.isLowPowerModeEnabled,
            memoryWarningCount: MemoryPressureMonitor.shared.warningCount
        ))
    }

    private func appendSharedContainerUnavailable(taskKind: BackgroundTaskKind) async {
        await appendMetric(
            taskKind: taskKind,
            policySummary: "skipped: shared container unavailable",
            success: false,
            errorCode: "shared_container_unavailable"
        )
    }

    private func continueProcessing(before taskKind: BackgroundTaskKind, deadline: Date) async -> Bool {
        guard Date() < deadline else {
            await appendMetric(
                taskKind: taskKind,
                policySummary: "skipped: background processing deadline expired",
                success: true,
                errorCode: "background_deadline_expired"
            )
            return false
        }
        return true
    }
}

import UIKit

@MainActor
final class BackgroundRuntimeContinuation {
    private var identifier: UIBackgroundTaskIdentifier = .invalid
    private var continuedProcessingLease: BackgroundContinuedProcessingLease?
    private var ended = false

    private init(identifier: UIBackgroundTaskIdentifier, continuedProcessingLease: BackgroundContinuedProcessingLease?) {
        self.identifier = identifier
        self.continuedProcessingLease = continuedProcessingLease
    }

    static func begin(name: String, allowsContinuedProcessing: Bool = false) -> BackgroundRuntimeContinuation? {
        let continuedLease = allowsContinuedProcessing
            ? BackgroundContinuedProcessingCoordinator.shared.begin(
                title: "Lumen",
                subtitle: name,
                prefersGPU: true
            )
            : nil

        let runtimeContinuation = BackgroundRuntimeContinuation(identifier: .invalid, continuedProcessingLease: continuedLease)
        let taskID = UIApplication.shared.beginBackgroundTask(withName: name) { [runtimeContinuation] in
            MainActor.assumeIsolated {
                runtimeContinuation.finish(success: false)
            }
        }
        guard taskID != .invalid else {
            continuedLease?.complete(success: false)
            return nil
        }
        runtimeContinuation.identifier = taskID
        return runtimeContinuation
    }

    func end(success: Bool = true) {
        finish(success: success)
    }

    private func finish(success: Bool) {
        guard !ended, identifier != .invalid else { return }
        ended = true
        continuedProcessingLease?.complete(success: success)
        continuedProcessingLease = nil
        UIApplication.shared.endBackgroundTask(identifier)
        identifier = .invalid
    }
}

import Foundation

enum BackgroundTaskKind: String, Sendable {
    case triggerScan
    case memoryConsolidation
    case ragMaintenance
    case modelHousekeeping
}

struct BackgroundTaskPolicyInput: Sendable, Equatable {
    let taskKind: BackgroundTaskKind
    let lowPowerMode: Bool
    let thermalState: DeviceThermalState
    let isForeground: Bool
    let backgroundAgentsEnabled: Bool
    let requiresNetwork: Bool
    let estimatedCost: Int
}

struct BackgroundTaskDecision: Sendable, Equatable {
    let allow: Bool
    let denyReason: String?
    let maxSteps: Int
    let maxTokens: Int
    let allowModelLoading: Bool
    let allowNetwork: Bool
}

enum BackgroundTaskPolicy {
    static func decide(_ input: BackgroundTaskPolicyInput) -> BackgroundTaskDecision {
        guard input.backgroundAgentsEnabled else {
            return .init(allow: false, denyReason: "background agents disabled", maxSteps: 0, maxTokens: 0, allowModelLoading: false, allowNetwork: false)
        }
        if input.thermalState == .serious || input.thermalState == .critical {
            return .init(allow: false, denyReason: "thermal state disallows background work", maxSteps: 0, maxTokens: 0, allowModelLoading: false, allowNetwork: false)
        }
        let isLowPowerBackground = input.lowPowerMode && !input.isForeground
        if isLowPowerBackground && input.taskKind != .triggerScan && input.taskKind != .modelHousekeeping {
            return .init(allow: false, denyReason: "low power background mode", maxSteps: 0, maxTokens: 0, allowModelLoading: false, allowNetwork: false)
        }

        let allowModelLoading = input.isForeground && input.estimatedCost <= 5
        let allowNetwork = input.requiresNetwork && !isLowPowerBackground
        if input.requiresNetwork && !allowNetwork {
            return .init(allow: false, denyReason: "network unavailable for required background task", maxSteps: 0, maxTokens: 0, allowModelLoading: false, allowNetwork: false)
        }
        return .init(allow: true, denyReason: nil, maxSteps: input.taskKind == .triggerScan ? 2 : 1, maxTokens: 256, allowModelLoading: allowModelLoading, allowNetwork: allowNetwork)
    }
}

