import Foundation

actor AgentRunCoordinator {
    static let shared = AgentRunCoordinator()

    private var activeTask: Task<PersistentDiagnosticRunRecord, Never>?
    private var activeTaskID: UUID?
    private let store: PersistentRuntimeDiagnosticsStore

    init(store: PersistentRuntimeDiagnosticsStore = .shared) {
        self.store = store
    }

    func cancelActive(reason: String) async {
        AppCancellationBus.shared.markCancellationRequested(reason)
        AppCancellationBus.shared.cancel(.chatGeneration)
        activeTask?.cancel()
        activeTask = nil
        activeTaskID = nil
    }

    func run(
        record: PersistentDiagnosticRunRecord,
        cancellationReason: String,
        operation: @escaping @Sendable (PersistentDiagnosticRunRecord) async throws -> PersistentDiagnosticRunRecord
    ) async -> PersistentDiagnosticRunRecord {
        await cancelActive(reason: "diagnostics-replaced-by-new-agent-run")
        var startingRecord = record
        startingRecord.status = .running
        let taskID = UUID()
        let task = Task { () -> PersistentDiagnosticRunRecord in
            await withTaskCancellationHandler {
                do {
                    try Task.checkCancellation()
                    var completed = try await operation(startingRecord)
                    try Task.checkCancellation()
                    if completed.status == .running {
                        completed.status = .passed
                        completed.finishedAt = Date()
                        completed.events.append(PersistentDiagnosticEvent(code: "agent_run_passed", message: "Agent run completed"))
                    }
                    await store.appendRunUpdate(completed)
                    return completed
                } catch is CancellationError {
                    var cancelled = startingRecord
                    cancelled.status = .cancelled
                    cancelled.finishedAt = Date()
                    cancelled.metrics.didCancel = true
                    cancelled.metrics.cancellationReason = cancellationReason
                    cancelled.events.append(PersistentDiagnosticEvent(code: "agent_run_cancelled", message: "Agent run cancelled", values: ["reason": cancellationReason]))
                    await store.appendRunUpdate(cancelled)
                    return cancelled
                } catch {

                    var failed = startingRecord
                    failed.status = .failed
                    failed.finishedAt = Date()
                    let code = RuntimeMetricErrorSanitizer.code(for: error)
                    failed.metrics.errorCodes.append(code)
                    failed.failureSummary = code
                    failed.events.append(PersistentDiagnosticEvent(code: "agent_run_failed", message: "Agent run failed", values: ["errorCode": code]))
                    await store.appendRunUpdate(failed)
                    return failed
                }
            } onCancel: {
                AppCancellationBus.shared.markCancellationRequested(cancellationReason)
                AppCancellationBus.shared.cancel(.chatGeneration)
            }
        }
        activeTask = task
        activeTaskID = taskID
        let result = await task.value
        if activeTaskID == taskID {
            activeTask = nil
            activeTaskID = nil
        }
        return result
    }
}

import Foundation

nonisolated enum AgentWorkflowSlot: String, Codable, Sendable, CaseIterable, Identifiable {
    case cortex
    case executor
    case mouth
    case mimicry
    case rem
    case fleet
    case embedding
    case runtime
    case unknown

    var id: String { rawValue }

    static func normalized(_ value: String?) -> AgentWorkflowSlot? {
        guard let raw = value?.trimmingCharacters(in: .whitespacesAndNewlines), !raw.isEmpty else { return nil }
        let lowered = raw.lowercased()
        if let slot = AgentWorkflowSlot(rawValue: lowered) { return slot }
        if lowered.contains("cortex") { return .cortex }
        if lowered.contains("executor") { return .executor }
        if lowered.contains("mouth") || lowered.contains("bouche") { return .mouth }
        if lowered.contains("mimicry") { return .mimicry }
        if lowered.contains("rem") { return .rem }
        if lowered.contains("fleet") { return .fleet }
        if lowered.contains("embedding") { return .embedding }
        return nil
    }

    static func infer(kind: PersistentRuntimeDiagnosticSignalKind, phase: String, values: [String: String]) -> AgentWorkflowSlot {
        if let explicit = normalized(Self.value("activeAdapterSlot", in: values) ?? Self.value("adapterSlot", in: values) ?? Self.value("slot", in: values)) {
            return explicit
        }

        let normalizedPhase = phase.lowercased()
        switch kind {
        case .fallbackUsed:
            return .mouth
        case .llamaPromptBudget, .llamaFirstToken, .llamaEmptyOutput, .llamaComplete, .llamaCancel, .llamaFailure:
            return .fleet
        case .groundingCost:
            return .rem
        case .chatRuntimeTrace:
            if normalizedPhase.contains("routing") || normalizedPhase.contains("planned") || normalizedPhase.contains("budget") {
                return .cortex
            }
            if normalizedPhase.contains("action") || normalizedPhase.contains("observation") || normalizedPhase.contains("approval") {
                return .executor
            }
            if normalizedPhase.contains("final") || normalizedPhase.contains("clarification") {
                return .mouth
            }
            if normalizedPhase.contains("ground") {
                return .rem
            }
            return .runtime
        default:
            return .runtime
        }

