enum MemoryCaptureQueueError: LocalizedError, Equatable {
    case diskWriteDeferred

    var errorDescription: String? {
        switch self {
        case .diskWriteDeferred:
            return "memory capture queue write deferred by disk budget"
        }
    }
}

@MainActor
enum MemoryCaptureQueue {
    nonisolated static let maxPendingCaptures = 200
    nonisolated static let defaultDrainLimit = 8

    private static let fileName = "pending-memory-captures.json"

    static func enqueue(
        content: String,
        kind: MemoryKind = .fact,
        source: String = "app-intent-pending",
        topic: String? = nil,
        createdAt: Date = Date(),
        fileURL: URL? = nil
    ) throws -> PendingMemoryCapture {
        let trimmed = content.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw CocoaError(.fileWriteUnknown)
        }

        let url = try resolvedFileURL(fileURL)
        var captures = try loadPending(fileURL: url)
        let dedupeKey = trimmed.lowercased()

        if let existing = captures.first(where: { $0.content.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() == dedupeKey }) {
            return existing
        }

        let capture = PendingMemoryCapture(
            content: trimmed,
            kind: kind,
            source: source,
            topic: topic,
            createdAt: createdAt
        )
        captures.append(capture)
        if captures.count > maxPendingCaptures {
            captures.removeFirst(captures.count - maxPendingCaptures)
        }
        try savePending(captures, fileURL: url)
        return capture
    }

    static func pendingCount(fileURL: URL? = nil) throws -> Int {
        try loadPending(fileURL: resolvedFileURL(fileURL)).count
    }

    static func diagnosticsSnapshot(fileURL: URL? = nil) throws -> MemoryCaptureQueueDiagnostics {
        let captures = try loadPending(fileURL: resolvedFileURL(fileURL))
        return MemoryCaptureQueueDiagnostics(
            pendingCount: captures.count,
            oldestCreatedAt: captures.map(\.createdAt).min(),
            maxRetryCount: captures.map(\.retryCount).max() ?? 0,
            lastError: captures.first(where: { ($0.lastError?.isEmpty == false) })?.lastError
        )
    }

static func loadPending(fileURL: URL? = nil) throws -> [PendingMemoryCapture] {
    let url = try resolvedFileURL(fileURL)
    let path = url.path(percentEncoded: false)
    guard FileManager.default.fileExists(atPath: path) else { return [] }
    let data = try Data(contentsOf: url)
    guard !data.isEmpty else { return [] }
    let decoder = JSONDecoder()
    decoder.dateDecodingStrategy = .iso8601
    return try decoder.decode([PendingMemoryCapture].self, from: data)
}

static func drain(
    context: ModelContext,
    maxItems: Int = defaultDrainLimit,
    allowPromotion: Bool,
    fileURL: URL? = nil
) async -> MemoryCaptureDrainResult {
    guard allowPromotion else {
        let remaining = (try? pendingCount(fileURL: fileURL)) ?? 0
        return .skipped(remaining: remaining, reason: "promotion_not_allowed")
    }

    let hasEmbeddingRuntime = await AppLlamaService.shared.hasSemanticEmbeddingRuntime
    guard hasEmbeddingRuntime else {
        let remaining = (try? pendingCount(fileURL: fileURL)) ?? 0
        return .skipped(remaining: remaining, reason: "embedding_runtime_unavailable")
    }

    return await drain(maxItems: maxItems, fileURL: fileURL) { capture in
        try await MemoryStore.remember(
            capture.content,
            kind: capture.kind,
            source: capture.source,
            topic: capture.topic,
            context: context
        )
    }
}

static func drain(
    maxItems: Int = defaultDrainLimit,
    fileURL: URL? = nil,
    promote: (PendingMemoryCapture) async throws -> Void
) async -> MemoryCaptureDrainResult {
    let boundedLimit = max(0, maxItems)
    guard boundedLimit > 0 else {
        let remaining = (try? pendingCount(fileURL: fileURL)) ?? 0
        return .skipped(remaining: remaining, reason: "empty_drain_limit")
    }

    do {
        let url = try resolvedFileURL(fileURL)
        let captures = try loadPending(fileURL: url)
        guard !captures.isEmpty else {
            return MemoryCaptureDrainResult(attempted: 0, promoted: 0, remaining: 0, skippedReason: nil, lastError: nil)
        }

        let candidates = Array(captures.prefix(boundedLimit))

        var remainder = Array(captures.dropFirst(candidates.count))
        var promoted = 0
        var attempted = 0
        var lastError: String?

        for capture in candidates {
            attempted += 1
            do {
                try await promote(capture)
                promoted += 1
            } catch {
                let failed = capture.recordingFailure(error)
                lastError = failed.lastError
                remainder.insert(failed, at: 0)
                let unattempted = candidates.dropFirst(attempted)
                remainder.insert(contentsOf: unattempted, at: 1)
                break
            }
        }

        try savePending(remainder, fileURL: url)
        return MemoryCaptureDrainResult(
            attempted: attempted,
            promoted: promoted,
            remaining: remainder.count,
            skippedReason: nil,
            lastError: lastError
        )
    } catch {
        let remaining = (try? pendingCount(fileURL: fileURL)) ?? 0
        return MemoryCaptureDrainResult(
            attempted: 0,
            promoted: 0,
            remaining: remaining,
            skippedReason: "queue_io_failed",
            lastError: sanitizedErrorCode(for: error)
        )
    }
}

nonisolated static func sanitizedErrorCode(for error: Error) -> String {
    let raw = String(describing: error)
        .lowercased()
        .replacingOccurrences(of: #"[^a-z0-9_.-]+"#, with: "_", options: .regularExpression)
        .trimmingCharacters(in: CharacterSet(charactersIn: "_"))
    return raw.isEmpty ? "unknown" : String(raw.prefix(80))
}

private static func resolvedFileURL(_ fileURL: URL?) throws -> URL {
    if let fileURL { return fileURL }
    let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first
        ?? FileManager.default.temporaryDirectory
    let directory = base
        .appendingPathComponent("Lumen", isDirectory: true)
        .appendingPathComponent("Memory", isDirectory: true)
    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    return directory.appendingPathComponent(fileName, isDirectory: false)

    }

    private static func savePending(_ captures: [PendingMemoryCapture], fileURL: URL) throws {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.sortedKeys]
        let data = try encoder.encode(captures)
        guard DiskWriteBudget.shared.canWrite(bytes: data.count, category: .memory) else {
            throw MemoryCaptureQueueError.diskWriteDeferred
        }
        try FileManager.default.createDirectory(at: fileURL.deletingLastPathComponent(), withIntermediateDirectories: true)
        try data.write(to: fileURL, options: [.atomic])
        DiskWriteBudget.shared.recordWrite(bytes: data.count, category: .memory)
    }
}

import Foundation
import SwiftData

@MainActor
enum MemoryConsolidator {
    static func consolidate(
        context: ModelContext,
        metricsStore: RuntimeMetricsStore = .shared,
        promoteQueuedCaptures: Bool = false
    ) async {
        let drain = promoteQueuedCaptures
            ? await MemoryCaptureQueue.drain(context: context, allowPromotion: true)
            : nil
        let all = (try? context.fetch(FetchDescriptor<MemoryItem>())) ?? []
        var seen = Set<String>()
        var deleted = 0
        for item in all.sorted(by: { $0.createdAt > $1.createdAt }) {
            let key = item.content.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            if seen.contains(key), !item.isPinned { context.delete(item); deleted += 1 } else { seen.insert(key) }
        }
        do {
            try context.save()
            try? await metricsStore.appendMetric(.init(timestamp: Date(), runtimeName: "memory", taskKind: "consolidation", modelIDHash: nil, policySummary: policySummary(deleted: deleted, drain: drain), latencyMs: nil, success: true, errorCode: nil, thermalState: .from(processThermalState: ProcessInfo.processInfo.thermalState), lowPowerMode: ProcessInfo.processInfo.isLowPowerModeEnabled, memoryWarningCount: MemoryPressureMonitor.shared.warningCount))
        } catch {
            try? await metricsStore.appendMetric(.init(timestamp: Date(), runtimeName: "memory", taskKind: "consolidation", modelIDHash: nil, policySummary: policySummary(deleted: deleted, drain: drain), latencyMs: nil, success: false, errorCode: RuntimeMetricErrorSanitizer.code(for: error), thermalState: .from(processThermalState: ProcessInfo.processInfo.thermalState), lowPowerMode: ProcessInfo.processInfo.isLowPowerModeEnabled, memoryWarningCount: MemoryPressureMonitor.shared.warningCount))
        }
    }

    private static func policySummary(deleted: Int, drain: MemoryCaptureDrainResult?) -> String {
        var parts = ["dedupe deleted=\(deleted)"]
        if let drain {
            if let skippedReason = drain.skippedReason {
                parts.append("queued skipped=\(skippedReason) remaining=\(drain.remaining)")
            } else {
                parts.append("queued attempted=\(drain.attempted) promoted=\(drain.promoted) remaining=\(drain.remaining)")
            }
        }
        return parts.joined(separator: "; ")
    }
}

import Foundation
import SwiftData

struct MemoryContextResult {
    let selected: [MemoryItem]
    let totalChars: Int
    let totalTokens: Int
    let candidateCount: Int
    let reasons: [UUID: String]
    let sourceIDs: [UUID]
    let tierCounts: [String: Int]
    let hierarchyPassApplied: Bool

    init(
        selected: [MemoryItem],
        totalChars: Int,
        totalTokens: Int? = nil,
        candidateCount: Int? = nil,
        reasons: [UUID: String],
        sourceIDs: [UUID],
        tierCounts: [String: Int] = [:],
        hierarchyPassApplied: Bool = false
    ) {
        self.selected = selected
        self.totalChars = max(0, totalChars)
        self.totalTokens = totalTokens ?? ContextBudgetAllocator.estimateTokens(forCharacterCount: max(0, totalChars))
        self.candidateCount = candidateCount ?? selected.count
        self.reasons = reasons
        self.sourceIDs = sourceIDs
        self.tierCounts = tierCounts
        self.hierarchyPassApplied = hierarchyPassApplied
    }
}

enum MemoryContextBuilder {
    enum Tier: String, CaseIterable {
        case pinned
        case working
        case episodic
        case semantic

        var primaryLimit: Int {
            switch self {
            case .pinned: Int.max
            case .working: 2
            case .episodic: 2
            case .semantic: 4
            }
        }
    }

    @MainActor
    static func build(query: String, budgetChars: Int, context: ModelContext) -> MemoryContextResult {
        let budgetChars = max(0, budgetChars)
        let all = (try? context.fetch(FetchDescriptor<MemoryItem>())) ?? []
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let hasQuery = !q.isEmpty
        let terms = queryTerms(q)
        let now = Date()
        let ranked = all
            .filter { !MemoryStore.isExpired($0, now: now) }
            .map { item in
                RankedMemory(item: item, tier: tier(for: item, now: now), score: score(item, q, terms: terms, hasQuery: hasQuery, now: now))
            }
            .sorted(by: rank)

        var picked: [RankedMemory] = []
        var chars = 0
        var tierCounts: [Tier: Int] = [:]
        var pickedIDs = Set<UUID>()

        func canFit(_ ranked: RankedMemory) -> Bool {
            chars + contextChars(for: ranked.item) <= budgetChars
        }

    func pick(_ ranked: RankedMemory) {
        picked.append(ranked)
        chars += contextChars(for: ranked.item)
        tierCounts[ranked.tier, default: 0] += 1
        pickedIDs.insert(ranked.item.id)
    }

    for m in ranked {
        guard canFit(m) else { continue }
        guard tierCounts[m.tier, default: 0] < m.tier.primaryLimit else { continue }
        pick(m)
    }

    if picked.count < ranked.count {
        for m in ranked where !pickedIDs.contains(m.item.id) {
            guard canFit(m) else { continue }
            pick(m)
        }
    }

    let selected = picked.map(\.item)
    var reasons: [UUID: String] = [:]
    for m in picked {
        let queryMatched = queryMatches(m.item, q: q, terms: terms, hasQuery: hasQuery)
        let base = m.item.isPinned ? "pinned" : (queryMatched ? "query-match" : "recency")
        reasons[m.item.id] = "\(m.tier.rawValue):\(base)"
    }

    return .init(
        selected: selected,
        totalChars: chars,
        candidateCount: all.count,
        reasons: reasons,
        sourceIDs: selected.map(\.id),
        tierCounts: Dictionary(uniqueKeysWithValues: Tier.allCases.map { ($0.rawValue, tierCounts[$0, default: 0]) }),
        hierarchyPassApplied: Set(picked.map(\.tier)).count > 1
    )
}

private static func score(_ m: MemoryItem, _ q: String, terms: [String], hasQuery: Bool, now: Date) -> Double {
    var s = 0.0
    if m.isPinned { s += 1.8 }
    if hasQuery && m.content.lowercased().contains(q) { s += 1.0 }
    if hasQuery && m.topic?.lowercased().contains(q) == true { s += 0.7 }
    s += termCoverage(item: m, terms: terms) * 0.9
    switch m.memoryKind {
    case .preference, .person, .project: s += 0.35
    case .conversation: s += 0.15
    case .fact: break
    }
    s += max(0, 0.3 - now.timeIntervalSince(m.createdAt)/(60*60*24*365))
    return s
}

private struct RankedMemory {
    let item: MemoryItem
    let tier: Tier
    let score: Double
}

private static func rank(_ lhs: RankedMemory, _ rhs: RankedMemory) -> Bool {
    if lhs.score != rhs.score { return lhs.score > rhs.score }

        if lhs.tier != rhs.tier { return tierPriority(lhs.tier) > tierPriority(rhs.tier) }
        return lhs.item.createdAt > rhs.item.createdAt
    }

    private static func tierPriority(_ tier: Tier) -> Int {
        switch tier {
        case .pinned: 4
        case .semantic: 3
        case .episodic: 2
        case .working: 1
        }
    }

    private static func tier(for item: MemoryItem, now: Date) -> Tier {
        if item.isPinned { return .pinned }
        if item.memoryKind == .conversation {
            return now.timeIntervalSince(item.createdAt) < 60 * 60 * 24 * 2 ? .working : .episodic
        }
        if item.freshnessClass == MemoryFreshnessClass.volatile.rawValue || item.freshnessClass == MemoryFreshnessClass.shortLived.rawValue {
            return .episodic
        }
        return .semantic
    }

    private static func contextChars(for item: MemoryItem) -> Int {
        min(220, item.content.count)
    }

    private static func queryMatches(_ item: MemoryItem, q: String, terms: [String], hasQuery: Bool) -> Bool {
        guard hasQuery else { return false }
        if item.content.lowercased().contains(q) || item.topic?.lowercased().contains(q) == true { return true }
        return termCoverage(item: item, terms: terms) > 0
    }

    private static func termCoverage(item: MemoryItem, terms: [String]) -> Double {
        guard !terms.isEmpty else { return 0 }
        let content = item.content.lowercased()
        let topic = item.topic?.lowercased() ?? ""
        let matches = terms.filter { content.contains($0) || topic.contains($0) }
        return Double(matches.count) / Double(terms.count)
    }

    private static func queryTerms(_ query: String) -> [String] {
        let stopwords: Set<String> = [
            "about", "after", "again", "avec", "been", "dans", "does", "from", "have", "into",
            "pour", "that", "this", "what", "when", "where", "with", "your",
            "alors", "avoir", "comme", "elle", "fait", "mais", "nous", "plus", "quoi",
            "sans", "sont", "tout", "vous"
        ]
        var seen = Set<String>()
        return query
            .components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { $0.count >= 3 && !stopwords.contains($0) }
            .filter { seen.insert($0).inserted }
    }
}

import Foundation
import SwiftData

@MainActor
final class MemoryEngine {
    func search(query: String, limit: Int, context: ModelContext) async -> [MemoryItem] {
        await MemoryStore.recall(query: query, context: context, limit: limit)
    }

    func buildContext(query: String, budget: Int, context: ModelContext) -> MemoryContextResult {
        MemoryContextBuilder.build(query: query, budgetChars: budget, context: context)
    }

    func extractCandidates(from messages: [ChatMessage], conversationID: UUID?) -> [MemoryCandidate] {
        messages.compactMap { message in
            guard message.messageRole == .user else { return nil }
            let t = message.content.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !t.isEmpty else { return nil }
            let lower = t.lowercased()
            let explicit: MemoryUserExplicitness
            let reason: String
            if lower.contains("remember that") { explicit = .explicitPreference; reason = "remember directive" }
            else if lower.hasPrefix("actually") { explicit = .correction; reason = "user correction" }
            else if lower.contains("i prefer") { explicit = .explicitPreference; reason = "stated preference" }
            else if lower.contains("for lumen") { explicit = .projectFact; reason = "project declaration" }
            else { explicit = .inferred; reason = "pattern match" }
            return MemoryCandidate(text: String(t.prefix(220)), kind: "fact", topics: [], conversationID: conversationID, messageID: message.id, createdAt: message.createdAt, confidence: 0.6, extractionReason: reason, userExplicitness: explicit, sensitivity: .normal)
        }
    }

    func saveCandidateIfAllowed(_ candidate: MemoryCandidate, context: ModelContext) async throws {
        let result = MemoryScorer.score(candidate: candidate)
        guard result.decision == .save else { return }
        try await MemoryStore.remember(candidate.text, kind: .fact, source: "memory-engine", topic: candidate.topics.first, context: context)
    }

    func consolidateDueMemories(context: ModelContext) async {
        await MemoryConsolidator.consolidate(context: context, promoteQueuedCaptures: true)
    }
    func deleteMemory(id: UUID, context: ModelContext) throws {
        var descriptor = FetchDescriptor<MemoryItem>(predicate: #Predicate { $0.id == id })

        descriptor.fetchLimit = 1
        if let item = try context.fetch(descriptor).first {
            context.delete(item)
            try context.save()
        }
    }
    func pinMemory(id: UUID, context: ModelContext) throws {
        var descriptor = FetchDescriptor<MemoryItem>(predicate: #Predicate { $0.id == id })
        descriptor.fetchLimit = 1
        if let item = try context.fetch(descriptor).first {
            item.isPinned = true
            try context.save()
        }
    }
}

import Foundation

enum MemoryExtractionTrigger { case assistantTurn, userCorrection, explicitRemember, backgroundConsolidation }

enum MemoryExtractionPolicy {
    static func shouldExtract(trigger: MemoryExtractionTrigger, lowPower: Bool, isBackground: Bool, containsSensitiveToolOutput: Bool) -> Bool {
        if containsSensitiveToolOutput { return false }
        if trigger == .explicitRemember || trigger == .userCorrection { return true }
        if isBackground && lowPower { return false }
        return true
    }
}

import Foundation

enum MemorySaveDecision: String, Sendable { case save, ignore, askUser, rejectSensitive }
struct MemoryScoreResult: Sendable { let score: Double; let decision: MemorySaveDecision; let reasons: [String] }

enum MemoryScorer {
    static func score(candidate: MemoryCandidate, now: Date = Date()) -> MemoryScoreResult {
        if candidate.sensitivity == .credentialLike { return .init(score: -1, decision: .rejectSensitive, reasons: ["credentialLike"]) }
        var s = candidate.confidence
        var reasons: [String] = []
        switch candidate.userExplicitness {
        case .explicitPreference: s += 2; reasons.append("explicitPreference")
        case .correction: s += 1.8; reasons.append("correction")
        case .repeatedFact: s += 1.2; reasons.append("repeatedFact")
        case .projectFact: s += 1.0; reasons.append("projectFact")
        case .inferred: s += 0.2
        case .transient: s -= 1.2; reasons.append("transientPenalty")
        }
        if candidate.sensitivity == .healthOrLegal || candidate.sensitivity == .financial { return .init(score: s, decision: .askUser, reasons: reasons + ["sensitiveDomain"]) }
        let age = now.timeIntervalSince(candidate.createdAt)
        s += max(-0.6, 0.4 - age / (60*60*24*30*6))
        let d: MemorySaveDecision = s >= 1.1 ? .save : .ignore
        return .init(score: s, decision: d, reasons: reasons)
    }
}

import Foundation

nonisolated enum AgentJSONValue: Sendable, Hashable, Codable {
    case string(String)
    case number(Double)
    case bool(Bool)
    case array([AgentJSONValue])
    case object([String: AgentJSONValue])
    case null

    static func parse(_ value: Any) -> AgentJSONValue? {
        if value is NSNull { return .null }
        if let str = value as? String { return .string(str) }
        if let bool = value as? Bool { return .bool(bool) }
        if let num = value as? NSNumber {
            if CFGetTypeID(num) == CFBooleanGetTypeID() {
                return .bool(num.boolValue)
            }
            return .number(num.doubleValue)
        }
        if let arr = value as? [Any] {
            let parsed = arr.compactMap(AgentJSONValue.parse)
            return parsed.count == arr.count ? .array(parsed) : nil
        }
        if let obj = value as? [String: Any] {
            var parsed: [String: AgentJSONValue] = [:]
            for (key, innerValue) in obj {
                guard let inner = AgentJSONValue.parse(innerValue) else { return nil }
                parsed[key] = inner
            }
            return .object(parsed)
        }
        return nil
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if container.decodeNil() {
            self = .null
        } else if let value = try? container.decode(Bool.self) {
            self = .bool(value)
        } else if let value = try? container.decode(Double.self) {
            self = .number(value)
        } else if let value = try? container.decode(String.self) {
            self = .string(value)
        } else if let value = try? container.decode([AgentJSONValue].self) {
            self = .array(value)
        } else {
            self = .object(try container.decode([String: AgentJSONValue].self))
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .string(let value):
            try container.encode(value)
        case .number(let value):
            try container.encode(value)
        case .bool(let value):
            try container.encode(value)
        case .array(let values):
            try container.encode(values)
        case .object(let values):
            try container.encode(values)
        case .null:

            try container.encodeNil()
        }
    }

    var stringValue: String {
        switch self {
        case .string(let value):
            return value
        case .number(let value):
            if let intValue = Int(exactly: value) { return String(intValue) }
            return String(value)
        case .bool(let value):
            return value ? "true" : "false"
        case .array(let values):
            return values.jsonRenderedString ?? "[" + values.map(\.stringValue).joined(separator: ",") + "]"
        case .object(let values):
            if let rendered = values.jsonRenderedString { return rendered }
            let fallback = values.keys.sorted().map { key in
                let value = values[key]?.stringValue ?? "null"
                return "\"\(key)\":\(value)"
            }.joined(separator: ",")
            return "{\(fallback)}"
        case .null:
            return "null"
        }
    }

    var intValue: Int? {
        switch self {
        case .number(let value):
            return Int(exactly: value)
        case .string(let value):
            return Int(value)
        case .bool(let value):
            return value ? 1 : 0
        default:
            return nil
        }
    }

    var boolValue: Bool? {
        switch self {
        case .bool(let value):
            return value
        case .string(let value):
            let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            if normalized == "true" { return true }
            if normalized == "false" { return false }
            return nil
        case .number(let value):
            return value != 0
        default:
            return nil
        }
    }
}

typealias AgentJSONArguments = [String: AgentJSONValue]

extension Dictionary where Key == String, Value == AgentJSONValue {
    init(stringDictionary: [String: String]) {
        self = stringDictionary.reduce(into: [:]) { partialResult, element in
            partialResult[element.key] = .string(element.value)
        }
    }

    nonisolated var stringCoerced: [String: String] {
        reduce(into: [String: String]()) { partialResult, element in
            partialResult[element.key] = element.value.stringValue
        }
    }

    nonisolated fileprivate var jsonRenderedString: String? {

        let foundationObject = reduce(into: [String: Any]()) { partialResult, element in
            partialResult[element.key] = element.value.foundationObject
        }
        guard JSONSerialization.isValidJSONObject(foundationObject),
              let data = try? JSONSerialization.data(withJSONObject: foundationObject, options: [.sortedKeys]),
              let json = String(data: data, encoding: .utf8) else {
            return nil
        }
        return json
    }
}

extension Array where Element == AgentJSONValue {
    nonisolated fileprivate var jsonRenderedString: String? {
        let foundationObject = map(\.foundationObject)
        guard JSONSerialization.isValidJSONObject(foundationObject),
              let data = try? JSONSerialization.data(withJSONObject: foundationObject, options: []),
              let json = String(data: data, encoding: .utf8) else {
            return nil
        }
        return json
    }
}

private extension AgentJSONValue {
    nonisolated var foundationObject: Any {
        switch self {
        case .string(let value):
            return value
        case .number(let value):
            return NSNumber(value: value)
        case .bool(let value):
            return NSNumber(value: value)
        case .array(let values):
            return values.map(\.foundationObject)
        case .object(let value):
            return value.reduce(into: [String: Any]()) { partialResult, element in
                partialResult[element.key] = element.value.foundationObject
            }
        case .null:
            return NSNull()
        }
    }
}

