@Model
final class Trigger {
    var id: UUID = UUID()
    var title: String = ""
    var prompt: String = ""
    var scheduleType: String = "once"
    var fireDate: Date?
    var timeOfDayMinutes: Int?
    var intervalSeconds: TimeInterval?
    var weekdayMask: Int = 0
    var beforeNextEventMinutes: Int?
    var isPaused: Bool = false
    var createdAt: Date = Date()
    var lastRunAt: Date?
    var lastResult: String?
    var nextFireAt: Date?
    var conversationID: UUID?

    init(title: String, prompt: String, scheduleType: TriggerScheduleType, fireDate: Date? = nil, timeOfDayMinutes: Int? = nil, intervalSeconds: TimeInterval? = nil, weekdayMask: Int = 0, beforeNextEventMinutes: Int? = nil) {
        self.title = title
        self.prompt = prompt
        self.scheduleType = scheduleType.rawValue
        self.fireDate = fireDate
        self.timeOfDayMinutes = timeOfDayMinutes
        self.intervalSeconds = intervalSeconds
        self.weekdayMask = weekdayMask
        self.beforeNextEventMinutes = beforeNextEventMinutes
    }

    var kind: TriggerScheduleType { TriggerScheduleType(rawValue: scheduleType) ?? .once }

    func computeNextFire(from now: Date = Date()) -> Date? {
        let cal = Calendar.current
        switch kind {
        case .once:
            return (fireDate ?? now) > now ? fireDate : nil
        case .daily:
            guard let m = timeOfDayMinutes else { return nil }
            var comps = cal.dateComponents([.year, .month, .day], from: now)
            comps.hour = m / 60
            comps.minute = m % 60
            var candidate = cal.date(from: comps) ?? now
            if candidate <= now { candidate = cal.date(byAdding: .day, value: 1, to: candidate) ?? candidate }
            if weekdayMask != 0 {
                for _ in 0..<8 {
                    let wd = cal.component(.weekday, from: candidate)
                    if (weekdayMask & (1 << (wd - 1))) != 0 { return candidate }
                    candidate = cal.date(byAdding: .day, value: 1, to: candidate) ?? candidate
                }
            }
            return candidate
        case .interval:
            guard let s = intervalSeconds, s > 60 else { return nil }
            let base = lastRunAt ?? createdAt
            var t = base.addingTimeInterval(s)
            if t < now { t = now.addingTimeInterval(min(s, 3600)) }

            return t
        case .beforeNextEvent:
            return nil
        }
    }
}

enum TriggerScheduleType: String, Codable, CaseIterable, Sendable {
    case once, daily, interval, beforeNextEvent

    var label: String {
        switch self {
        case .once: "One-time"
        case .daily: "Daily"
        case .interval: "Interval"
        case .beforeNextEvent: "Before next event"
        }
    }

    var icon: String {
        switch self {
        case .once: "clock"
        case .daily: "sun.max"
        case .interval: "arrow.triangle.2.circlepath"
        case .beforeNextEvent: "calendar.badge.clock"
        }
    }
}

import Foundation

nonisolated struct WebRichContentPayload: Codable, Hashable {
    enum Kind: String, Codable {
        case searchResults
        case fetchedPage
    }

    static let startMarker = "<lumen_web_payload>"
    static let endMarker = "</lumen_web_payload>"

    let kind: Kind
    let query: String?
    let page: WebFetchedPagePayload?
    let results: [WebSearchResultPayload]
    let media: [WebMediaPayload]
    let generatedAt: Date

    init(
        kind: Kind,
        query: String? = nil,
        page: WebFetchedPagePayload? = nil,
        results: [WebSearchResultPayload] = [],
        media: [WebMediaPayload] = [],
        generatedAt: Date = Date()
    ) {
        self.kind = kind
        self.query = query
        self.page = page
        self.results = results
        self.media = media
        self.generatedAt = generatedAt
    }

    func encodedMarker() -> String {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        guard let data = try? encoder.encode(self),
              let json = String(data: data, encoding: .utf8) else {
            return ""
        }
        return "\n\n\(Self.startMarker)\(json)\(Self.endMarker)"
    }

    static func decodeAll(from text: String) -> [WebRichContentPayload] {
        var payloads: [WebRichContentPayload] = []
        var searchRange = text.startIndex..<text.endIndex
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601

        while let start = text.range(of: startMarker, range: searchRange),
              let end = text.range(of: endMarker, range: start.upperBound..<text.endIndex) {
            let json = String(text[start.upperBound..<end.lowerBound])
            if let data = json.data(using: .utf8),
               let payload = try? decoder.decode(WebRichContentPayload.self, from: data) {
                payloads.append(payload)
            }
            searchRange = end.upperBound..<text.endIndex
        }
        return payloads
    }

    static func removingMarkers(from text: String) -> String {
        var output = text
        while let start = output.range(of: startMarker) {
            guard let end = output.range(of: endMarker, range: start.upperBound..<output.endIndex) else {
                output.removeSubrange(start.lowerBound..<output.endIndex)
                break
            }

            output.removeSubrange(start.lowerBound..<end.upperBound)
        }
        return output
            .replacingOccurrences(of: #"\n{3,}"#, with: "\n\n", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

