import Foundation

struct PermissionDiagnostics: Sendable {
    let statuses: [PermissionDomain: AssistantPermissionState]
    let entitlementWarnings: [EntitlementAuditWarning]

    /// Collects current permission diagnostics and entitlement warnings.
    /// - Parameters:
    ///   - registry: The permission registry to use. If `nil`, resolves to `PermissionRegistry.shared`.
    ///   - infoDictionary: A dictionary used for entitlement validation.
    /// - Returns: A `PermissionDiagnostics` instance containing permission statuses and entitlement warnings.
    static func collect(registry: PermissionRegistry? = nil, infoDictionary: [String: Any] = Bundle.main.infoDictionary ?? [:]) async -> PermissionDiagnostics {
        let resolvedRegistry: PermissionRegistry
        if let providedRegistry = registry {
            resolvedRegistry = providedRegistry
        } else {
            resolvedRegistry = await MainActor.run { PermissionRegistry.shared }
        }
        let statuses = await resolvedRegistry.diagnostics()
        let warnings = BackgroundEntitlementValidator.validate(infoDictionary: infoDictionary)
        return PermissionDiagnostics(statuses: statuses, entitlementWarnings: warnings)
    }
}

import Foundation

enum PermissionDomain: String, CaseIterable, Codable, Sendable {
    case microphone, speechRecognition, camera, photoLibrary, locationWhenInUse, calendars, reminders, contacts, notifications, localNetwork, motion, appIntents, filesUserSelected, networkAccess
}

import Foundation

struct PermissionGateDecision: Sendable, Equatable { let allowed: Bool; let reason: String? }

enum PermissionGate {
    static func evaluate(domain: PermissionDomain, state: AssistantPermissionState, isForeground: Bool) -> PermissionGateDecision {
        if !isForeground && state == .notDetermined { return .init(allowed: false, reason: "Permission requests are blocked in background") }
        switch state {
        case .granted: return .init(allowed: true, reason: nil)
        case .notDetermined: return .init(allowed: false, reason: "Permission not granted yet")
        case .limited: return .init(allowed: false, reason: "Permission limited")
        case .denied: return .init(allowed: false, reason: "Permission denied")
        case .restricted: return .init(allowed: false, reason: "Permission restricted")
        case .unavailable: return .init(allowed: false, reason: "Capability unavailable")
        case .unknown: return .init(allowed: false, reason: "Permission state unknown")
        }
    }
}

