/// Determines whether a message likely intends to interact with Outlook or mail services.
/// - Returns: `true` if the text indicates an Outlook or mail intent, `false` otherwise.
private static func isLikelyOutlookIntent(_ text: String) -> Bool {
    let outlookMarkers = ["outlook", "hotmail", "live mail", "msn mail", "microsoft mail", "microsoft graph", "graph mail"]
    let mailActions = [
        "inbox", "email", "emails", "mail", "message", "messages", "unread", "new", "latest", "recent", "folders", "attachments",
        "search", "find", "read", "open", "check", "show", "list", "draft", "send", "reply", "reply all", "forward", "archive", "delete", "trash", "mark read", "mark unread", "move",
        "signed in", "sign in", "logged in", "login", "connected", "status", "auth", "authenticated", "reconnect", "account"
    ]
    if matchesAny(text, outlookMarkers) && matchesAny(text, mailActions) { return true }
    let genericReadMailCommands = [
        "read new emails", "read new email", "read unread emails", "read unread email", "read latest email", "read the latest email",
        "read recent emails", "read recent email", "check new emails", "check new email", "check unread emails", "check unread email",
        "check my unread email", "check my unread emails", "check my inbox", "show my unread email", "show my unread emails",
        "show new emails", "show latest emails", "show recent emails", "list new emails", "list unread emails", "open latest email", "open the latest email"
    ]
    if matchesAny(text, genericReadMailCommands) { return true }
    let hasReadVerb = matchesAny(text, ["read", "check", "show", "list", "open"])
    let hasMailboxObject = matchesAny(text, ["email", "emails", "mail", "inbox"])

        let hasNonComposeQualifier = matchesAny(text, ["new", "unread", "latest", "recent", "inbox"])
        return hasReadVerb && hasMailboxObject && hasNonComposeQualifier
    }

    private static func isLikelyWebSearchIntent(_ text: String) -> Bool {
        let explicitWebCommands = [
            "search web", "search the web", "search on web", "web search", "internet search",
            "look online", "find online", "fetch url", "open url", "read this url", "read this website"
        ]
        if matchesAny(text, explicitWebCommands) { return true }

        let hasWebChannel = matchesAny(text, ["web", "internet", "online"])
        let hasDiscoveryVerb = matchesAny(
            text,
            [
                "search", "find", "look up", "research", "fetch information", "fetch info",
                "how to", "how do i", "tutorial", "guide", "diy", "steps to", "instructions"
            ]
        )
        return hasWebChannel && hasDiscoveryVerb
    }

    private static func inferredRecipient(_ text: String) -> Bool {
        text.contains(" to ")
            || text.contains("@")
            || text.contains("recipient")
            || text.rangeOfCharacter(from: .decimalDigits) != nil
            || text.range(of: #"(?i)\b(email|mail|message|text|sms|imessage)\s+[a-z0-9@._+\-]{2,}\b"#, options: .regularExpression) != nil
    }

    private static func inferredContent(_ text: String) -> Bool {
        text.contains(" about ")
            || text.contains(" saying ")
            || text.contains(" body ")
            || text.contains(" that says ")
            || text.contains(" that ")
            || text.split(separator: " ").count >= 8
    }
}

import SwiftUI
import UIKit

/// Prevents the device from auto-locking while one or more "reasons" are active.
///
/// Uses a reason-counted approach so multiple subsystems (e.g. voice mode + a long
/// model download) can independently request the screen to stay awake without
/// stomping on each other. The idle timer is only re-enabled when *all* reasons
/// are released.
@MainActor
@Observable
final class KeepAwakeService {
    static let shared = KeepAwakeService()

    private(set) var activeReasons: Set<String> = []

    var isActive: Bool { !activeReasons.isEmpty }

    private init() {}

    /// Activate keep-awake for a given reason. Idempotent per reason.
    func activate(reason: String) {
        let inserted = activeReasons.insert(reason).inserted
        guard inserted else { return }
        applyIdleTimerState()
    }

    /// Deactivate keep-awake for a given reason. No-op if not active.
    func deactivate(reason: String) {
        guard activeReasons.remove(reason) != nil else { return }
        applyIdleTimerState()
    }

    /// Release every reason and allow the device to auto-lock again.
    func deactivateAll() {
        guard !activeReasons.isEmpty else { return }
        activeReasons.removeAll()
        applyIdleTimerState()
    }

    /// Run an async block while the screen is kept awake.
    func withKeepAwake<T>(reason: String, _ operation: () async throws -> T) async rethrows -> T {
        activate(reason: reason)
        defer { deactivate(reason: reason) }
        return try await operation()
    }

    private func applyIdleTimerState() {
        UIApplication.shared.isIdleTimerDisabled = isActive
    }
}

// MARK: - SwiftUI helper

extension View {
    /// Keeps the device awake while this view is on screen and `isActive` is true.
    func keepScreenAwake(_ isActive: Bool, reason: String) -> some View {
        modifier(KeepAwakeModifier(isActive: isActive, reason: reason))
    }
}

private struct KeepAwakeModifier: ViewModifier {
    let isActive: Bool
    let reason: String

    func body(content: Content) -> some View {
        content
            .onAppear { sync() }
            .onDisappear { KeepAwakeService.shared.deactivate(reason: reason) }
            .onChange(of: isActive) { _, _ in sync() }
    }

    private func sync() {
        if isActive {
            KeepAwakeService.shared.activate(reason: reason)

        } else {
            KeepAwakeService.shared.deactivate(reason: reason)
        }
    }
}

import Foundation

actor GGUFEngine: LLMEngine {
    nonisolated let id = "gguf"
    nonisolated let displayName = "GGUF Local Engine"
    nonisolated let capabilities = LLMEngineCapabilities.localGGUF

    private let nativeBridge: any GGUFNativeBridge
    private var loadedModel: LocalLLMModel?
    private var loadedProfile: InferenceProfile?
    private var activeRequestID: UUID?
    private var cancelledRequestIDs: Set<UUID> = []
    private var lifecycleTransitionInProgress = false
    private var generationInProgress = false
    private var generationInProgressWaiters: [CheckedContinuation<Void, Never>] = []

    init(nativeBridge: any GGUFNativeBridge = UnavailableGGUFNativeBridge()) {
        self.nativeBridge = nativeBridge
    }

    func load(model: LocalLLMModel, profile: InferenceProfile) async throws {
        guard model.backend == .gguf else {
            throw LLMEngineError.backendUnavailable(model.backend.rawValue)
        }

        await cancelActiveGenerationAndWait()
        lifecycleTransitionInProgress = true
        defer { lifecycleTransitionInProgress = false }

        guard let modelURL = model.localURL else {
            throw LLMEngineError.modelNotFound
        }

        do {
            try ModelFileValidator.validateReadableFile(modelURL)
            try ModelFileValidator.validateExtension(for: modelURL, backend: model.backend)
        } catch {
            throw GGUFEngineErrorMapper.map(error)
        }

        let config = GGUFBridgeLoadConfig(
            modelPath: modelURL.path,
            contextTokens: profile.contextTokens,
            batchSize: profile.batchSize,
            threadCount: profile.threadCount,
            gpuLayerCount: profile.gpuLayerCount,
            useMetal: profile.useMetal,
            useMemoryMapping: profile.useMemoryMapping
        )

        do {
            _ = try await nativeBridge.load(config: config)
            loadedModel = model
            loadedProfile = profile
            cancelledRequestIDs.removeAll(keepingCapacity: true)
        } catch {
            throw GGUFEngineErrorMapper.map(error)
        }
    }

    func unload() async {
        await cancelActiveGenerationAndWait()
        lifecycleTransitionInProgress = true
        defer { lifecycleTransitionInProgress = false }

        await nativeBridge.unload()
        loadedModel = nil
        loadedProfile = nil

    activeRequestID = nil
}

func isLoaded(modelID: String?) async -> Bool {
    guard let loadedModel else { return false }
    guard let modelID else { return true }
    return loadedModel.id == modelID
}

nonisolated func generate(_ request: LLMRequest) -> AsyncThrowingStream<LLMTokenEvent, Error> {
    AsyncThrowingStream { continuation in
        let task = Task {
            await self.runGeneration(request, continuation: continuation)
        }
        continuation.onTermination = { @Sendable termination in
            if case .cancelled = termination {
                task.cancel()
                Task {
                    await self.cancelCurrentGeneration()
                }
            }
        }
    }
}

func cancelCurrentGeneration() async {
    guard let activeRequestID else { return }
    cancelledRequestIDs.insert(activeRequestID)
    await nativeBridge.cancel()
}

private func runGeneration(
    _ request: LLMRequest,
    continuation: AsyncThrowingStream<LLMTokenEvent, Error>.Continuation
) async {
    let startedAt = Date()

    guard lifecycleTransitionInProgress == false else {
        continuation.finish(throwing: LLMEngineError.generationAlreadyRunning)
        return
    }

    guard let loadedModel, let loadedProfile else {
        continuation.finish(throwing: LLMEngineError.modelNotLoaded)
        return
    }

    guard activeRequestID == nil else {
        continuation.finish(throwing: LLMEngineError.generationAlreadyRunning)
        return
    }

    do {
        try validateSupportedFeatures(for: request)
        let prompt = try GGUFPromptBuilder.buildPrompt(from: request)
        let promptTokens = approximateTokenCount(for: prompt)
        let remainingCompletionTokens = remainingCompletionTokens(
            promptTokens: promptTokens,
            profile: loadedProfile
        )

        activeRequestID = request.id
        generationInProgress = true
        defer {
            finishGeneration(requestID: request.id)
        }

        let generationConfig = GGUFBridgeGenerateConfig(
            prompt: prompt,
            sampling: makeSamplingConfig(

        from: request.sampling,
        budget: request.budget,
        maximumTokens: remainingCompletionTokens
    )
)

continuation.yield(.started(requestID: request.id))

var runningCompletionCharacters = 0
var completionTokens = 0
var parser = ReasoningAwareStreamParser(
    config: ReasoningAwareStreamParserConfig(
        captureReasoning: request.metadata.booleanValue(forAnyKey: [
            "reasoningCaptureEnabled",
            "developerReasoningCaptureEnabled",
            "allowThinking"
        ]),
        reasoningTraceBudgetCharacters: request.metadata.intValue(forAnyKey: [
            "reasoningTraceBudgetCharacters",
            "reasoning_trace_budget_characters"
        ]) ?? 16_384
    )
)

do {
    for try await token in nativeBridge.generate(config: generationConfig) {
        guard !Task.isCancelled, cancelledRequestIDs.contains(request.id) == false else {
            await nativeBridge.cancel()
            continuation.yield(.cancelled)
            continuation.finish()
            return
        }

        runningCompletionCharacters += token.count
        completionTokens = approximateTokenCount(forCharacterCount: runningCompletionCharacters)
        let parsedDelta = parser.ingest(token)
        if parsedDelta.visibleDelta.isEmpty == false {
            continuation.yield(.token(parsedDelta.visibleDelta))
        }
    }
} catch {
    let mapped = GGUFEngineErrorMapper.map(error)
    if let engineError = mapped as? LLMEngineError, engineError == .generationCancelled {
        continuation.yield(.cancelled)
        continuation.finish()
    } else {
        continuation.finish(throwing: mapped)
    }
    return
}

let parserFinalDelta = parser.finish()
if parserFinalDelta.visibleDelta.isEmpty == false {

            continuation.yield(.token(parserFinalDelta.visibleDelta))
        }

        guard !Task.isCancelled, cancelledRequestIDs.contains(request.id) == false else {
            await nativeBridge.cancel()
            continuation.yield(.cancelled)
            continuation.finish()
            return
        }

        continuation.yield(.completed(LLMCompletionSummary(
            requestID: request.id,
            modelID: loadedModel.id,
            promptTokens: promptTokens,
            completionTokens: completionTokens,
            totalTokens: promptTokens + completionTokens,
            durationSeconds: max(0, Date().timeIntervalSince(startedAt)),
            finishReason: .stop
        )))
        continuation.finish()
    } catch {
        continuation.finish(throwing: GGUFEngineErrorMapper.map(error))
    }
}

private func validateSupportedFeatures(for request: LLMRequest) throws {
    if request.metadata.booleanValue(forAnyKey: ["requiresEmbeddings", "requires_embeddings"]) {
        throw LLMEngineError.unsupportedFeature("embeddings")
    }

    if request.metadata.booleanValue(forAnyKey: ["requiresVision", "requires_vision"]) {
        throw LLMEngineError.unsupportedFeature("vision")
    }
}

private func makeSamplingConfig(
    from sampling: LLMSamplingConfig,
    budget: InferenceBudget,
    maximumTokens: Int
) -> GGUFBridgeSamplingConfig {
    let requestedMaxTokens = min(
        sampling.maxTokens,
        budget.maxCompletionTokens,
        capabilities.maximumOutputTokens
    )

    return GGUFBridgeSamplingConfig(
        temperature: sampling.temperature,
        topP: sampling.topP,
        topK: sampling.topK,
        repeatPenalty: sampling.repeatPenalty,
        seed: sampling.seed,
        maxTokens: min(requestedMaxTokens, max(0, maximumTokens)),
        stopSequences: sampling.stopSequences
    )
}

private func remainingCompletionTokens(promptTokens: Int, profile: InferenceProfile) -> Int {
    let contextLimit = min(profile.contextTokens, capabilities.maximumContextTokens)
    return max(0, contextLimit - promptTokens)
}

private func approximateTokenCount(for text: String) -> Int {

        approximateTokenCount(forCharacterCount: text.count)
    }

    private func approximateTokenCount(forCharacterCount characterCount: Int) -> Int {
        Int(ceil(Double(characterCount) / 4.0))
    }

    private func cancelActiveGenerationAndWait() async {
        guard generationInProgress else { return }
        if let activeRequestID {
            cancelledRequestIDs.insert(activeRequestID)
        }
        await nativeBridge.cancel()
        await waitForActiveGenerationToFinish()
    }

    private func waitForActiveGenerationToFinish() async {
        guard generationInProgress else { return }
        await withCheckedContinuation { continuation in
            generationInProgressWaiters.append(continuation)
        }
    }

    private func finishGeneration(requestID: UUID) {
        activeRequestID = nil
        generationInProgress = false
        cancelledRequestIDs.remove(requestID)
        let waiters = generationInProgressWaiters
        generationInProgressWaiters.removeAll(keepingCapacity: true)
        for waiter in waiters {
            waiter.resume()
        }
    }
}

private extension Dictionary where Key == String, Value == String {
    nonisolated func booleanValue(forAnyKey keys: [String]) -> Bool {
        for key in keys {
            guard let value = self[key]?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() else {
                continue
            }
            if ["1", "true", "yes"].contains(value) {
                return true
            }
        }
        return false
    }

    nonisolated func intValue(forAnyKey keys: [String]) -> Int? {
        for key in keys {
            guard let value = self[key]?.trimmingCharacters(in: .whitespacesAndNewlines),
                  let parsed = Int(value) else {
                continue
            }
            return parsed
        }
        return nil
    }
}

import Foundation

nonisolated enum GGUFEngineErrorMapper {
    static func map(_ error: Error) -> Error {
        if let engineError = error as? LLMEngineError {
            return engineError
        }

        if let bridgeError = error as? GGUFBridgeError {
            switch bridgeError {
            case .backendNotCompiled:
                return LLMEngineError.backendUnavailable("GGUF native backend is not compiled.")
            case .modelFileMissing:
                return LLMEngineError.modelNotFound
            case .modelNotLoaded:
                return LLMEngineError.modelNotLoaded
            case .generationAlreadyRunning:
                return LLMEngineError.generationAlreadyRunning
            case .generationCancelled:
                return LLMEngineError.generationCancelled
            case .invalidModelPath, .invalidPrompt, .nativeFailure:
                return LLMEngineError.internalFailure(bridgeError.localizedDescription)
            }
        }

        if let storageError = error as? ModelStorageError {
            switch storageError {
            case .fileNotFound, .unreadableFile:
                return LLMEngineError.modelNotFound
            case .invalidModelFileExtension:
                return LLMEngineError.invalidRequest(storageError.localizedDescription)
            default:
                return LLMEngineError.internalFailure(storageError.localizedDescription)
            }
        }

        return LLMEngineError.internalFailure(error.localizedDescription)
    }
}

