private func storageLocation() throws -> ModelStorageLocation {
    if let cachedLocation {
        return cachedLocation
    }
    let resolved = try ModelStorageDirectoryResolver.resolve(fileManager: fileManager)
    cachedLocation = resolved
    return resolved
}

private func readRecord(from fileURL: URL, location: ModelStorageLocation) throws -> InstalledModelRecord {
    let data: Data
    do {
        data = try Data(contentsOf: fileURL)
    } catch {
        throw ModelStorageError.metadataReadFailed(error.localizedDescription)
    }

    let record: InstalledModelRecord
    do {
        record = try JSONDecoder().decode(InstalledModelRecord.self, from: data)
    } catch {
        throw ModelStorageError.metadataDecodingFailed(error.localizedDescription)
    }
    return try repairedRecordIfNeeded(record, metadataURL: fileURL, location: location)
}

private func repairedRecordIfNeeded(
    _ record: InstalledModelRecord,
    metadataURL: URL,
    location: ModelStorageLocation
) throws -> InstalledModelRecord {
    guard let relativePath = record.relativePath,
          let storedFileURL = record.fileURL,
          fileManager.fileExists(atPath: storedFileURL.path) == false else {
        return record
    }

    let repairedFileURL = location.rootDirectory.appendingPathComponent(relativePath)
    guard fileManager.fileExists(atPath: repairedFileURL.path) else {
        return record
    }

    let repairedModel = LocalLLMModel(
        id: record.model.id,
        displayName: record.model.displayName,
        backend: record.model.backend,
        localURL: repairedFileURL,
        expectedSHA256: record.model.expectedSHA256,
        parameterCountBillion: record.model.parameterCountBillion,
        quantization: record.model.quantization,
        contextLength: record.model.contextLength,
        fileSizeBytes: record.model.fileSizeBytes,
        createdAt: record.model.createdAt,
        lastUsedAt: record.model.lastUsedAt
    )
    let repairedRecord = InstalledModelRecord(
        id: record.id,
        catalogID: record.catalogID,
        model: repairedModel,
        fileURL: repairedFileURL,
        relativePath: relativePath,
        sha256: record.sha256,
        sizeBytes: record.sizeBytes,
        installedAt: record.installedAt,
        lastVerifiedAt: record.lastVerifiedAt,
        verificationStatus: record.verificationStatus
    )

    do {
        let encoder = JSONEncoder()

        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        try encoder.encode(repairedRecord).write(to: metadataURL, options: [.atomic])
    } catch {
        throw ModelStorageError.metadataWriteFailed(error.localizedDescription)
    }
    return repairedRecord
}

private func metadataFileURL(for id: String, location: ModelStorageLocation) -> URL {
    location.metadataDirectory.appendingPathComponent(safeFileName(id), isDirectory: false)
        .appendingPathExtension("json")
}

private func uniqueDestinationURL(
    sourceURL: URL,
    preferredFileName: String?,
    location: ModelStorageLocation
) throws -> URL {
    let candidateName = safeImportFileName(preferredFileName ?? sourceURL.lastPathComponent)
    let baseName = URL(fileURLWithPath: candidateName).deletingPathExtension().lastPathComponent
    let pathExtension = URL(fileURLWithPath: candidateName).pathExtension
    let firstCandidate = location.modelsDirectory.appendingPathComponent(candidateName, isDirectory: false)
    if fileManager.fileExists(atPath: firstCandidate.path) == false {
        return firstCandidate
    }

    for _ in 0..<100 {
        let suffix = UUID().uuidString.prefix(8).lowercased()
        let name = pathExtension.isEmpty ? "\(baseName)-\(suffix)" : "\(baseName)-\(suffix).\(pathExtension)"
        let candidate = location.modelsDirectory.appendingPathComponent(name, isDirectory: false)
        if fileManager.fileExists(atPath: candidate.path) == false {
            return candidate
        }
    }

    throw ModelStorageError.importFailed("Could not allocate a unique destination filename.")
}

private func fileSizeBytes(for fileURL: URL) throws -> Int64? {
    do {
        let attributes = try fileManager.attributesOfItem(atPath: fileURL.path)
        if let size = attributes[.size] as? NSNumber {
            return size.int64Value
        }
        return nil
    } catch {
        throw ModelStorageError.importFailed(error.localizedDescription)
    }
}

private func installedRecordID(catalogEntry: ModelCatalogEntry?, fileURL: URL) -> String {
    let base = catalogEntry?.id ?? fileURL.deletingPathExtension().lastPathComponent

        return "installed.\(safeIdentifier(base)).\(UUID().uuidString.lowercased())"
    }

    private func relativePath(for fileURL: URL, root: URL) -> String? {
        let rootPath = normalizedDirectoryPath(root)
        let filePath = fileURL.standardizedFileURL.resolvingSymlinksInPath().path
        guard filePath.hasPrefix(rootPath) else {
            return nil
        }
        return String(filePath.dropFirst(rootPath.count))
    }

    private func isDescendant(_ fileURL: URL, of rootURL: URL) -> Bool {
        fileURL.standardizedFileURL.resolvingSymlinksInPath().path.hasPrefix(normalizedDirectoryPath(rootURL))
    }

    private func normalizedDirectoryPath(_ url: URL) -> String {
        let path = url.standardizedFileURL.resolvingSymlinksInPath().path
        return path.hasSuffix("/") ? path : "\(path)/"
    }

    private func safeFileName(_ value: String) -> String {
        let safe = safeIdentifier(value)
        return safe.isEmpty ? UUID().uuidString.lowercased() : safe
    }

    private func safeImportFileName(_ value: String) -> String {
        let url = URL(fileURLWithPath: value)
        let base = safeIdentifier(url.deletingPathExtension().lastPathComponent)
        let pathExtension = safeIdentifier(url.pathExtension.lowercased())
        let safeBase = base.isEmpty ? "model" : base
        return pathExtension.isEmpty ? safeBase : "\(safeBase).\(pathExtension)"
    }

    private func safeIdentifier(_ value: String) -> String {
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "._-"))
        return value.unicodeScalars.map { scalar in
            allowed.contains(scalar) ? Character(scalar) : "-"
        }
        .reduce(into: "") { $0.append($1) }
        .trimmingCharacters(in: CharacterSet(charactersIn: ".-_"))
    }
}

    case bundled
    case localImport
    case remote(url: URL)
    case huggingFace(repoID: String, fileName: String)
    case unknown

    private enum SourceType: String, Codable {
        case bundled
        case localImport
        case remote
        case huggingFace
        case unknown
    }

    private enum CodingKeys: String, CodingKey {
        case type
        case url
        case repoID
        case fileName
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let rawType = try container.decode(String.self, forKey: .type)
        let type = SourceType(rawValue: rawType) ?? .unknown

        switch type {
        case .bundled:
            self = .bundled
        case .localImport:
            self = .localImport
        case .remote:
            self = .remote(url: try container.decode(URL.self, forKey: .url))
        case .huggingFace:
            self = .huggingFace(
                repoID: try container.decode(String.self, forKey: .repoID),
                fileName: try container.decode(String.self, forKey: .fileName)
            )
        case .unknown:
            self = .unknown
        }
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)

        switch self {
        case .bundled:
            try container.encode(SourceType.bundled, forKey: .type)
        case .localImport:
            try container.encode(SourceType.localImport, forKey: .type)
        case .remote(let url):
            try container.encode(SourceType.remote, forKey: .type)
            try container.encode(url, forKey: .url)
        case .huggingFace(let repoID, let fileName):
            try container.encode(SourceType.huggingFace, forKey: .type)
            try container.encode(repoID, forKey: .repoID)
            try container.encode(fileName, forKey: .fileName)
        case .unknown:
            try container.encode(SourceType.unknown, forKey: .type)
        }
    }
}

import Foundation

enum ModelFileValidator {
    nonisolated static func validateExtension(for url: URL, backend: LLMBackendKind) throws {
        let fileExtension = url.pathExtension.lowercased()

        switch backend {
        case .gguf:
            guard fileExtension == "gguf" else {
                throw ModelStorageError.invalidModelFileExtension(url.lastPathComponent)
            }
        case .coreML:
            guard ["mlmodel", "mlmodelc", "mlpackage"].contains(fileExtension) else {
                throw ModelStorageError.invalidModelFileExtension(url.lastPathComponent)
            }
        case .tinyIntent, .mock, .remote:
            return
        }
    }

    nonisolated static func validateReadableFile(_ url: URL) throws {
        let fileManager = FileManager.default
        guard fileManager.fileExists(atPath: url.path) else {
            throw ModelStorageError.fileNotFound(url)
        }
        guard fileManager.isReadableFile(atPath: url.path) else {
            throw ModelStorageError.unreadableFile(url)
        }
    }

    static func verifyHashIfNeeded(fileURL: URL, expectedSHA256: String?) throws -> String? {
        try validateReadableFile(fileURL)

        guard let expectedSHA256, expectedSHA256.isEmpty == false else {
            return nil
        }

        let actualSHA256 = try SHA256FileHasher.sha256Hex(for: fileURL)
        guard actualSHA256.lowercased() == expectedSHA256.lowercased() else {
            throw ModelStorageError.hashMismatch(expected: expectedSHA256.lowercased(), actual: actualSHA256)
        }
        return actualSHA256
    }
}

import Foundation

actor ModelSelectionService {
    private let storage: LLMModelStorage
    private let policy: DeviceModelPolicy

    init(
        storage: LLMModelStorage,
        policy: DeviceModelPolicy
    ) {
        self.storage = storage
        self.policy = policy
    }

    func installedUsableModels(appIsForeground: Bool) async throws -> [InstalledModelRecord] {
        let records = try await storage.listInstalledModels().filter(\.isUsable)
        var usableRecords: [InstalledModelRecord] = []

        for record in records {
            let decision = await evaluateInstalledModel(record, appIsForeground: appIsForeground)
            if decision.isAllowed {
                usableRecords.append(record)
            }
        }

        return usableRecords
    }

    func bestModel(
        for recommendedUse: ModelRecommendedUse,
        appIsForeground: Bool
    ) async throws -> InstalledModelRecord? {
        let records = try await storage.listInstalledModels().filter(\.isUsable)
        var candidates: [(record: InstalledModelRecord, use: ModelRecommendedUse)] = []

        for record in records {
            let decision = await evaluateInstalledModel(record, appIsForeground: appIsForeground)
            guard decision.isAllowed else { continue }
            candidates.append((record, useForRecord(record)))
        }

        return candidates.sorted { lhs, rhs in
            let lhsRank = selectionRank(record: lhs.record, use: lhs.use, requestedUse: recommendedUse)
            let rhsRank = selectionRank(record: rhs.record, use: rhs.use, requestedUse: recommendedUse)
            if lhsRank != rhsRank {
                return lhsRank > rhsRank
            }

            let lhsParameters = lhs.record.model.parameterCountBillion ?? 0
            let rhsParameters = rhs.record.model.parameterCountBillion ?? 0
            if lhsParameters != rhsParameters {
                return lhsParameters > rhsParameters
            }

            return lhs.record.id < rhs.record.id
        }.first?.record
    }

    func evaluateInstalledModel(
        _ record: InstalledModelRecord,
        appIsForeground: Bool
    ) async -> ModelFitDecision {
        let use = useForRecord(record)
        let request = requestConfiguration(for: use, backend: record.model.backend)

        return await policy.evaluate(
            model: record.model,

            requestedProfile: request.profile,
            requestedBudget: request.budget,
            appIsForeground: appIsForeground
        )
    }

    private func useForRecord(_ record: InstalledModelRecord) -> ModelRecommendedUse {
        if let catalogID = record.catalogID, let entry = BuiltInModelCatalog.entry(id: catalogID) {
            return entry.recommendedUse
        }

        switch record.model.backend {
        case .tinyIntent:
            return .tinyIntent
        case .mock:
            return .testing
        case .remote, .gguf, .coreML:
            return .standardChat
        }
    }

    private func requestConfiguration(
        for use: ModelRecommendedUse,
        backend: LLMBackendKind
    ) -> (profile: InferenceProfile, budget: InferenceBudget) {
        if backend == .tinyIntent {
            return (.simulatorSafe, .fast)
        }

        switch use {
        case .tinyIntent:
            return (.simulatorSafe, .fast)
        case .fastChat:
            return (.iphoneBalanced, .fast)
        case .standardChat:
            return (.iphoneBalanced, .standard)
        case .deepThink:
            return (.iphoneDeepThink, .deepThink)
        case .embedding:
            return (
                .iphoneBalanced,
                InferenceBudget(
                    maxPromptTokens: 2_048,
                    maxCompletionTokens: 1,
                    maxWallClockSeconds: 30,
                    maxMemoryMB: 1_536,
                    allowGPU: true,
                    allowBackgroundExecution: false
                )
            )
        case .reranking, .vision, .testing:
            return (.simulatorSafe, .fast)
        }
    }

    private func selectionRank(
        record: InstalledModelRecord,
        use: ModelRecommendedUse,
        requestedUse: ModelRecommendedUse
    ) -> Int {
        if use == requestedUse {
            return 2
        }
        if record.model.backend == .tinyIntent {
            return 1
        }
        return 0
    }
}

import Foundation

struct ModelStorageLocation: Sendable, Codable, Equatable {
    let rootDirectory: URL
    let modelsDirectory: URL
    let metadataDirectory: URL
    let temporaryDirectory: URL
}

enum ModelStorageDirectoryResolver {
    static func resolve(fileManager: FileManager = .default) throws -> ModelStorageLocation {
        try resolve(
            documentDirectories: fileManager.urls(for: .documentDirectory, in: .userDomainMask),
            applicationSupportDirectories: fileManager.urls(for: .applicationSupportDirectory, in: .userDomainMask),
            fileManager: fileManager
        )
    }

    static func resolve(
        documentDirectories: [URL],
        applicationSupportDirectories: [URL],
        fileManager: FileManager = .default
    ) throws -> ModelStorageLocation {
        guard let documents = documentDirectories.first ?? applicationSupportDirectories.first else {
            throw ModelStorageError.applicationSupportUnavailable
        }

        let rootDirectory = documents.appendingPathComponent("Lumen", isDirectory: true)
        let modelsDirectory = rootDirectory.appendingPathComponent("Models", isDirectory: true)
        let metadataDirectory = modelsDirectory.appendingPathComponent("Metadata", isDirectory: true)
        let temporaryDirectory = modelsDirectory.appendingPathComponent("Tmp", isDirectory: true)

        for directory in [rootDirectory, modelsDirectory, metadataDirectory, temporaryDirectory] {
            do {
                try fileManager.createDirectory(at: directory, withIntermediateDirectories: true)
            } catch {
                throw ModelStorageError.failedToCreateDirectory(directory, error.localizedDescription)
            }
        }

        do {
            var values = URLResourceValues()
            values.isExcludedFromBackup = true
            var mutableModelsDirectory = modelsDirectory
            try mutableModelsDirectory.setResourceValues(values)
        } catch {
            throw ModelStorageError.failedToSetResourceValues(modelsDirectory, error.localizedDescription)
        }

        if let applicationSupport = applicationSupportDirectories.first, documentDirectories.first != nil {
            let previousRootDirectory = applicationSupport.appendingPathComponent("Lumen", isDirectory: true)

            if previousRootDirectory.standardizedFileURL != rootDirectory.standardizedFileURL {
                migratePreviousStorageRoot(
                    from: previousRootDirectory,
                    to: rootDirectory,
                    fileManager: fileManager
                )
            }
        }

        return ModelStorageLocation(
            rootDirectory: rootDirectory,
            modelsDirectory: modelsDirectory,
            metadataDirectory: metadataDirectory,
            temporaryDirectory: temporaryDirectory
        )
    }

    private static func migratePreviousStorageRoot(
        from previousRootDirectory: URL,
        to rootDirectory: URL,
        fileManager: FileManager
    ) {
        guard fileManager.fileExists(atPath: previousRootDirectory.path) else { return }

        let previousModels = previousRootDirectory.appendingPathComponent("Models", isDirectory: true)
        let currentModels = rootDirectory.appendingPathComponent("Models", isDirectory: true)
        guard let children = try? fileManager.contentsOfDirectory(
            at: previousModels,
            includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles]
        ) else {
            return
        }

        for source in children {
            let destination = currentModels.appendingPathComponent(source.lastPathComponent, isDirectory: source.hasDirectoryPath)
            guard fileManager.fileExists(atPath: destination.path) == false else { continue }
            do {
                try fileManager.moveItem(at: source, to: destination)
            } catch {
                try? fileManager.copyItem(at: source, to: destination)
            }
        }
    }
}

import CryptoKit
import Foundation

enum SHA256FileHasher {
    private static let chunkSize = 4 * 1_024 * 1_024

    static func sha256Hex(for fileURL: URL) throws -> String {
        let fileManager = FileManager.default
        guard fileManager.fileExists(atPath: fileURL.path) else {
            throw ModelStorageError.fileNotFound(fileURL)
        }
        guard fileManager.isReadableFile(atPath: fileURL.path) else {
            throw ModelStorageError.unreadableFile(fileURL)
        }

        let handle: FileHandle
        do {
            handle = try FileHandle(forReadingFrom: fileURL)
        } catch {
            throw ModelStorageError.unreadableFile(fileURL)
        }
        defer {
            try? handle.close()
        }

        var hasher = SHA256()
        do {
            while true {
                guard let data = try handle.read(upToCount: chunkSize), !data.isEmpty else {
                    break
                }
                hasher.update(data: data)
            }
        } catch {
            throw ModelStorageError.unreadableFile(fileURL)
        }

        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }
}

