nonisolated struct MemoryCascadeResult: Sendable {
    let ephemeral: [MemoryContextItem]
    let vectorized: [MemoryContextItem]
    let condensed: [MemoryContextItem]

    var promptFragments: [MemoryContextItem] {
        var fragments: [MemoryContextItem] = []
        if !ephemeral.isEmpty { fragments.append(contentsOf: ephemeral) }
        if !vectorized.isEmpty { fragments.append(contentsOf: vectorized) }
        if !condensed.isEmpty { fragments.append(contentsOf: condensed) }
        return fragments
    }
}

@MainActor
enum MemoryCascade {
    static func recall(
        query: String,
        history: [(role: MessageRole, content: String)],
        context: ModelContext
    ) async -> MemoryCascadeResult {
        let tier1 = history
            .suffix(12)
            .compactMap { item -> MemoryContextItem? in
                let compact = compactAndTrim(item.content, maxLength: 260)
                guard !compact.isEmpty else { return nil }
                return MemoryContextItem(content: compact, scope: .currentTurn, authority: .referenceOnly, createdAt: nil, expiresAt: nil, source: "tier1-ephemeral", topic: nil)
            }

        let tier2 = await MemoryStore.recall(query: query, context: context, limit: 8)
            .filter { $0.source != "rem-condensed" }
            .compactMap { item -> MemoryContextItem? in
                let compact = compactAndTrim(item.content, maxLength: 260)
                guard !compact.isEmpty else { return nil }
                return MemoryContextItem(content: compact, scope: .conversation, authority: .referenceOnly, createdAt: item.createdAt, expiresAt: MemoryStore.inferredExpiresAt(for: item), source: item.source, topic: item.topic)
            }

        let queryTokens = tokenSet(query)
        let condensedDescriptor = FetchDescriptor<MemoryItem>(
            predicate: #Predicate<MemoryItem> { $0.source == "rem-condensed" }
        )
        let condensedItems = ((try? context.fetch(condensedDescriptor)) ?? []).filter { item in
            !MemoryStore.isExpired(item)
        }

        let rankedTier3 = condensedItems
            .map { item in
                (
                    item: item,
                    overlap: overlapScore(tokens: queryTokens, content: item.content)
                )
            }
            .sorted { lhs, rhs in

            if lhs.overlap != rhs.overlap { return lhs.overlap > rhs.overlap }
            return lhs.item.createdAt > rhs.item.createdAt
        }
        .prefix(8)
        .compactMap { pair -> MemoryContextItem? in
            let compact = compactAndTrim(pair.item.content, maxLength: 260)
            guard !compact.isEmpty else { return nil }
            return MemoryContextItem(content: compact, scope: .remCondensed, authority: .backgroundOnly, createdAt: pair.item.createdAt, expiresAt: MemoryStore.inferredExpiresAt(for: pair.item), source: pair.item.source, topic: pair.item.topic)
        }

    return MemoryCascadeResult(
        ephemeral: tier1,
        vectorized: tier2,
        condensed: Array(rankedTier3)
    )
}


static func condenseIfNeeded(context: ModelContext, minimumCount: Int = 24) async throws {
    let descriptor = FetchDescriptor<MemoryItem>(
        sortBy: [SortDescriptor(\.createdAt, order: .forward)]
    )
    let allItems = try context.fetch(descriptor)

    let candidates = allItems.filter { item in
        guard item.source != "rem-condensed" else { return false }
        guard item.isPinned == false else { return false }
        guard !MemoryStore.isExpired(item) else { return false }
        return !item.content.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    guard candidates.count >= minimumCount else { return }

    let grouped = Dictionary(grouping: candidates) { item -> String in
        let topic = item.topic?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if !topic.isEmpty {
            return topic
        }
        return "kind:\(item.kind)"
    }

    for groupKey in grouped.keys.sorted() {
        guard let groupItems = grouped[groupKey], groupItems.count >= 6 else { continue }

        let sortedItems = groupItems.sorted { lhs, rhs in
            if lhs.createdAt != rhs.createdAt { return lhs.createdAt < rhs.createdAt }
            if lhs.content != rhs.content { return lhs.content < rhs.content }
            return lhs.id.uuidString < rhs.id.uuidString
        }
        let newestItems = Array(sortedItems.suffix(12))
        let newestSourceDate = newestItems.last?.createdAt ?? .distantPast

        let cascadeTopic = "cascade:\(groupKey)"

        let existingDescriptor = FetchDescriptor<MemoryItem>(
            predicate: #Predicate<MemoryItem> {
                $0.source == "rem-condensed" && $0.topic == cascadeTopic
            },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        if let newestCondensed = try context.fetch(existingDescriptor).first,
           newestCondensed.createdAt > newestSourceDate {
            continue
        }

        var seenLines: Set<String> = []
        let extracts = newestItems.compactMap { item -> String? in
            let compact = compactAndTrim(item.content, maxLength: 140)
            guard !compact.isEmpty else { return nil }
            let dedupeKey = compact.lowercased()
            guard !seenLines.contains(dedupeKey) else { return nil }
            seenLines.insert(dedupeKey)
            return compact
        }

        guard !extracts.isEmpty else { continue }
        let summaryBody = extracts.enumerated().map { index, line in
            "\(index + 1). \(line)"
        }.joined(separator: " ")
        let summary = "Background (low-authority) condensed \(groupKey): \(summaryBody)"

        try await MemoryStore.remember(
            summary,
            kind: .conversation,
            source: "rem-condensed",
            topic: cascadeTopic,
            context: context
        )

        let saved = try context.fetch(existingDescriptor)
        _ = saved.first
    }

    try context.save()
}

private static func compactAndTrim(_ text: String, maxLength: Int) -> String {
    let normalized = text
        .replacingOccurrences(of: "\n", with: " ")
        .split(whereSeparator: { $0.isWhitespace })
        .joined(separator: " ")
        .trimmingCharacters(in: .whitespacesAndNewlines)

    guard !normalized.isEmpty else { return "" }
    if normalized.count <= maxLength { return normalized }
    let end = normalized.index(normalized.startIndex, offsetBy: maxLength)
    return String(normalized[..<end]).trimmingCharacters(in: .whitespacesAndNewlines) + "…"
}

private static func tokenSet(_ text: String) -> Set<String> {
    let lower = text.lowercased()

        var tokens: Set<String> = []
        var current = ""

        for scalar in lower.unicodeScalars {
            if CharacterSet.alphanumerics.contains(scalar) {
                current.unicodeScalars.append(scalar)
            } else if !current.isEmpty {
                if current.count >= 2 {
                    tokens.insert(current)
                }
                current.removeAll(keepingCapacity: true)
            }
        }

        if current.count >= 2 {
            tokens.insert(current)
        }

        return tokens
    }

    private static func overlapScore(tokens queryTokens: Set<String>, content: String) -> Int {
        guard !queryTokens.isEmpty else { return 0 }
        let memoryTokens = tokenSet(content)
        return queryTokens.intersection(memoryTokens).count
    }
}

import Foundation
import OSLog

nonisolated enum MemoryGate {
    private nonisolated static let logger = Logger(subsystem: "ai.lumen.app", category: "memory-gate")

    static func filter(intent: UserIntent, items: [MemoryContextItem], userMessage: String, now: Date = Date()) -> [MemoryContextItem] {
        let normalized = normalize(userMessage)
        return items.compactMap { item in
            if let expiresAt = item.expiresAt, expiresAt <= now {
                logReject(item, reason: "expired")
                return nil
            }
            if let createdAt = item.createdAt, createdAt > now.addingTimeInterval(300) {
                logReject(item, reason: "created_in_future")
                return nil
            }

            switch intent {
            case .phoneCall, .messageDraft:
                guard allowForPhoneOrMessage(item) else {
                    logReject(item, reason: "intent_mismatch_phone_message")
                    return nil
                }
            case .weather:
                guard allowForWeather(item, userMessage: normalized) else {
                    logReject(item, reason: "intent_mismatch_weather")
                    return nil
                }
            case .webSearch:
                guard allowForWebSearch(item) else {
                    logReject(item, reason: "intent_mismatch_web")
                    return nil
                }
            default:
                break
            }
            return item
        }
    }

    private static func allowForPhoneOrMessage(_ item: MemoryContextItem) -> Bool {
        if item.scope == .person { return true }
        if item.scope == .conversation, item.authority == .referenceOnly { return true }
        if hasTopic(item, containsAny: ["contact", "recipient", "phone", "message", "imessage", "sms"]) { return true }
        if hasTopic(item, containsAny: ["weather", "forecast", "search", "calendar", "event"]) { return false }
        return item.scope != .toolObservation
    }

    private static func allowForWeather(_ item: MemoryContextItem, userMessage: String) -> Bool {
        let askedSameOrPrevious = userMessage.contains("same") || userMessage.contains("previous")
        if item.scope == .userPreference, hasTopic(item, containsAny: ["location", "city", "units", "weather"]) {
            return true
        }

        if item.scope == .currentTurn {
            return true
        }
        if item.scope == .toolObservation {
            if askedSameOrPrevious { return true }
            if let createdAt = item.createdAt {
                return Date().timeIntervalSince(createdAt) <= 15 * 60
            }
            return false
        }
        if hasTopic(item, containsAny: ["weather", "forecast", "search"]) {
            return askedSameOrPrevious
        }
        return false
    }

    private static func allowForWebSearch(_ item: MemoryContextItem) -> Bool {
        if item.scope == .project || item.scope == .userPreference { return true }
        if item.scope == .toolObservation {
            return hasTopic(item, containsAny: ["web", "search", "url", "http"])
        }
        return item.scope != .toolObservation
    }

    private static func hasTopic(_ item: MemoryContextItem, containsAny values: [String]) -> Bool {
        let haystack = "\(item.topic ?? "") \(item.source ?? "") \(item.content)".lowercased()
        return values.contains(where: { haystack.contains($0) })
    }

    private static func normalize(_ text: String) -> String {
        text.lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func logReject(_ item: MemoryContextItem, reason: String) {
        #if DEBUG
        logger.debug("memory_gate_reject reason=\(reason, privacy: .public) scope=\(item.scope.rawValue, privacy: .public) authority=\(item.authority.rawValue, privacy: .public) topic=\(item.topic ?? "-", privacy: .public) source=\(item.source ?? "-", privacy: .public)")
        #endif
    }
}

import Foundation
import SwiftData

@MainActor
enum MemoryRecall {
    static func recallAndNormalize(
        query: String,
        routing: IntentRoutingDecision,
        context: ModelContext,
        limit: Int = 8
    ) async -> [MemoryContextItem] {
        let rawItems = await MemoryStore.recall(query: query, context: context, limit: limit)
        return rawItems.compactMap { item in
            guard !MemoryStore.isExpired(item) else { return nil }
            let content = item.content.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !content.isEmpty else { return nil }
            return MemoryContextItem(
                content: content,
                scope: scope(for: item),
                authority: authority(for: item),
                createdAt: item.createdAt,
                expiresAt: MemoryStore.inferredExpiresAt(for: item),
                source: item.source,
                topic: item.topic
            )
        }
    }

    private static func scope(for item: MemoryItem) -> MemoryContextItem.Scope {
        let source = item.source.lowercased()
        if source == "rem-condensed" { return .remCondensed }
        if source.contains("tool") || source.contains("observation") { return .toolObservation }

        switch item.memoryKind {
        case .preference:
            return .userPreference
        case .person:
            return .person
        case .project:
            return .project
        case .conversation:
            return .conversation
        case .fact:
            if item.topic?.lowercased().contains("people") == true || item.topic?.lowercased().contains("contact") == true {
                return .person
            }
            return .conversation
        }
    }

    private static func authority(for item: MemoryItem) -> MemoryContextItem.Authority {
        let source = item.source.lowercased()
        if source == "rem-condensed" { return .backgroundOnly }
        if source.contains("tool") || source.contains("observation") { return .referenceOnly }

        switch item.memoryKind {
        case .preference:
            return .preferenceOnly
        case .person, .project:
            return .referenceOnly
        case .conversation, .fact:
            return .referenceOnly
        }
    }
}

import Foundation
import SwiftData
import OSLog

@MainActor
enum MemoryStore {
    private static let logger = Logger(subsystem: "ai.lumen.app", category: "persistence")

    private static func persist(_ context: ModelContext, operation: String, scope: String) throws {
        guard DiskWriteBudget.shared.canWrite(bytes: 64 * 1024, category: .memory) else { return }
        do {
            try context.save()
            DiskWriteBudget.shared.recordWrite(bytes: 64 * 1024, category: .memory)
        } catch {
            logger.error("persist_failed op=\(operation, privacy: .public) scope=\(scope, privacy: .public) error=\(String(describing: error), privacy: .public)")
            throw error
        }
    }

    static func auditPersistence(operation: String, scope: String, save: () throws -> Void) -> Bool {
        do {
            try save()
            return true
        } catch {
            logger.error("persist_failed op=\(operation, privacy: .public) scope=\(scope, privacy: .public) error=\(String(describing: error), privacy: .public)")
            return false
        }
    }

    nonisolated struct TTLPolicy: Sendable {
        let freshness: MemoryFreshnessClass
        let ttl: TimeInterval?
    }

    struct RecallResult {
        let items: [MemoryItem]
        let mode: String
        let diagnostic: String?
    }

    static func recall(query: String, context: ModelContext, limit: Int = 5) async -> [MemoryItem] {
        await recallWithDiagnostics(query: query, context: context, limit: limit).items
    }

    static func recallWithDiagnostics(query: String, context: ModelContext, limit: Int = 5) async -> RecallResult {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, limit > 0 else {
            return RecallResult(items: [], mode: "empty_query", diagnostic: "empty_query")
        }

        if let budgetDenial = ResourceBudgetGate.budgetDenialReason(policy: .embedding, reason: "memory.recall") {
            logger.error("memory_embedding_budget_denied op=recall reason=\(budgetDenial, privacy: .public)")
            return RecallResult(
                items: lexicalRecall(query: trimmed, context: context, limit: limit),
                mode: "lexical_fallback",
                diagnostic: budgetDenial
            )
        }

        let queryVec: [Double]
        do {

    queryVec = try await AppLlamaService.shared.embed(trimmed)
} catch {
    logger.error("memory_embedding_failed op=recall error=\(String(describing: error), privacy: .public)")
    return RecallResult(
        items: lexicalRecall(query: trimmed, context: context, limit: limit),
        mode: "lexical_fallback",
        diagnostic: "embedding_failed:\(RuntimeMetricErrorSanitizer.code(for: error))"
    )
}
guard !queryVec.isEmpty else {
    logger.error("memory_embedding_empty op=recall")
    return RecallResult(
        items: lexicalRecall(query: trimmed, context: context, limit: limit),
        mode: "lexical_fallback",
        diagnostic: "embedding_empty"
    )
}

let availableItems = (try? context.fetch(FetchDescriptor<MemoryItem>())) ?? []
guard !availableItems.isEmpty else {
    return RecallResult(items: [], mode: "semantic", diagnostic: "empty_store")
}
let itemByID = Dictionary(uniqueKeysWithValues: availableItems.map { ($0.persistentModelID, $0) })

MemoryVectorIndex.shared.ensureLoaded(context: context)
var results: [MemoryItem] = []
results.reserveCapacity(limit)
var seenIds: Set<PersistentIdentifier> = []
var topK = max(limit * 3, limit + 8)
let maxTopK = max(topK, 256)
var sawStaleVectorID = false

while results.count < limit {
    let hits = MemoryVectorIndex.shared.search(query: queryVec, topK: topK, pinBonus: 0.15)
    if hits.isEmpty { break }

    for h in hits {
        if results.count >= limit { break }
        guard seenIds.insert(h.id).inserted else { continue }
        guard let item = itemByID[h.id] else {
            sawStaleVectorID = true
            continue
        }
        guard !isExpired(item) else { continue }
        results.append(item)
    }

    if results.count >= limit || hits.count < topK || topK >= maxTopK {
        break
    }
    topK = min(topK * 2, maxTopK)
}

if sawStaleVectorID {
    MemoryVectorIndex.shared.invalidate()
    MemoryVectorIndex.shared.ensureLoaded(context: context)
}

    if results.count < limit {
        let existingIDs = Set(results.map(\.persistentModelID))
        let backfill = lexicalRecall(query: trimmed, context: context, limit: limit - results.count, excluding: existingIDs)
        results.append(contentsOf: backfill)
        if !backfill.isEmpty {
            return RecallResult(items: results, mode: "semantic_with_lexical_backfill", diagnostic: nil)
        }
    }
    return RecallResult(items: results, mode: "semantic", diagnostic: nil)
}

static func lexicalRecall(
    query: String,
    context: ModelContext,
    limit: Int,
    excluding excludedIDs: Set<PersistentIdentifier> = []
) -> [MemoryItem] {
    let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty, limit > 0 else { return [] }
    let queryLower = trimmed.lowercased()
    let terms = queryLower
        .components(separatedBy: CharacterSet.alphanumerics.inverted)
        .filter { $0.count >= 2 }
    guard let availableItems = try? context.fetch(FetchDescriptor<MemoryItem>()) else { return [] }
    let now = Date()
    return availableItems.compactMap { item -> (MemoryItem, Double)? in
        guard !excludedIDs.contains(item.persistentModelID), !isExpired(item, now: now) else { return nil }
        let content = item.content.lowercased()
        let topic = item.topic?.lowercased() ?? ""
        var score = 0.0
        if content == queryLower { score += 5.0 }
        if content.hasPrefix(queryLower) { score += 2.0 }
        if content.contains(queryLower) { score += 1.25 }
        if topic.contains(queryLower) { score += 0.75 }
        let hits = terms.reduce(0) { count, term in
            count + ((content.contains(term) || topic.contains(term)) ? 1 : 0)
        }
        if !terms.isEmpty { score += Double(hits) / Double(terms.count) }
        if item.isPinned { score += 0.5 }
        guard score > 0 else { return nil }
        score += max(0, 0.25 - now.timeIntervalSince(item.createdAt) / (60 * 60 * 24 * 365))
        return (item, score)
    }
    .sorted {
        if $0.1 != $1.1 { return $0.1 > $1.1 }
        return $0.0.createdAt > $1.0.createdAt
    }
    .prefix(limit)
    .map { $0.0 }
}

static func remember(_ content: String, kind: MemoryKind = .fact, source: String = "manual", topic: String? = nil, context: ModelContext) async throws {
    let trimmed = content.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else { return }
    if let existing = try? context.fetch(FetchDescriptor<MemoryItem>()) {
        if existing.contains(where: { $0.content.caseInsensitiveCompare(trimmed) == .orderedSame }) {
            return
        }
    }
    let embedding: [Double]
    do {
        embedding = try await AppLlamaService.shared.embed(trimmed)
    } catch {
        logger.error("memory_embedding_failed op=remember error=\(String(describing: error), privacy: .public)")
        throw error
    }
    guard !embedding.isEmpty else {
        logger.error("memory_embedding_empty op=remember")
        throw LlamaError.embeddingFailed("Memory embedding returned empty vector")
    }
    let policy = ttlPolicy(kind: kind, source: source)
    let item = MemoryItem(
        content: trimmed,
        kind: kind,
        source: source,
        embedding: embedding,
        topic: topic,
        expiresAt: policy.ttl.map { Date().addingTimeInterval($0) },
        freshnessClass: policy.freshness
    )
    context.insert(item)
    try persist(context, operation: "remember.insert", scope: "MemoryItem")
    MemoryVectorIndex.shared.ensureLoaded(context: context)
    MemoryVectorIndex.shared.append(id: item.persistentModelID, isPinned: item.isPinned, vector: embedding)
}

static func extractAndStore(userText: String, assistantText: String, transientTexts: [String] = [], context: ModelContext) async {
    let durableAssistant = durableAssistantText(assistantText, transientTexts: transientTexts)
    let combined = userText + "\n" + durableAssistant
    let cpuToken = CPUWatchdogGuard.shared.begin(category: .memory)
    defer { CPUWatchdogGuard.shared.end(token: cpuToken) }
    for extracted in extractFacts(from: combined) {
        if Task.isCancelled || CPUWatchdogGuard.shared.shouldDegrade(category: .memory) || !ResourceBudgetGate.allowsMaintenance(reason: "memory.extract") { break }

        try? await remember(extracted.content, kind: extracted.kind, source: "auto", topic: extracted.topic, context: context)
    }
}

static func wipeAll(context: ModelContext) throws {
    guard let all = try? context.fetch(FetchDescriptor<MemoryItem>()) else { return }
    for item in all where !item.isPinned {
        context.delete(item)
    }
    try persist(context, operation: "wipeAll", scope: "MemoryItem")
    MemoryVectorIndex.shared.invalidate()
}

static func wipeEverything(context: ModelContext) throws {
    guard let all = try? context.fetch(FetchDescriptor<MemoryItem>()) else { return }
    for item in all { context.delete(item) }
    try persist(context, operation: "wipeEverything", scope: "MemoryItem")
    MemoryVectorIndex.shared.invalidate()
}

static func exportJSON(context: ModelContext) -> String {
    guard let all = try? context.fetch(FetchDescriptor<MemoryItem>()) else { return "[]" }
    struct Export: Codable { let content: String; let kind: String; let topic: String?; let pinned: Bool; let createdAt: Date }
    let items = all.map { Export(content: $0.content, kind: $0.kind, topic: $0.topic, pinned: $0.isPinned, createdAt: $0.createdAt) }
    let enc = JSONEncoder()
    enc.outputFormatting = [.prettyPrinted, .sortedKeys]
    enc.dateEncodingStrategy = .iso8601
    return (try? String(data: enc.encode(items), encoding: .utf8)) ?? "[]"
}

// MARK: - Fact extraction (lightweight, rule-based)

nonisolated struct Extracted {
    let content: String
    let kind: MemoryKind
    let topic: String?
}

nonisolated static func extractFacts(from text: String) -> [Extracted] {
    var results: [Extracted] = []
    let sentences = text
        .replacingOccurrences(of: "\n", with: " ")
        .components(separatedBy: CharacterSet(charactersIn: ".!?"))
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }

    let prefLove = ["i love", "i like", "i enjoy", "i prefer", "my favorite", "i'm a fan of", "i am a fan of"]
    let durableAllowlist = ["prefer", "favorite", "i am", "i'm", "my name is", "i live", "i work", "working on", "building", "my project", "my app", "my startup"]

let volatileDenylist = ["weather", "temperature", "forecast", "current location", "located", "search result", "live result", "breaking", "reminder", "alarm", "calendar", "busy", "free", "availability", "tomorrow", "today"]
let prefHate = ["i hate", "i dislike", "i don't like", "i do not like", "i can't stand"]
let factSelf = ["i am", "i'm", "i live", "i work", "my name is", "i was born", "i have", "my birthday"]
let projectMarkers = ["working on", "building", "my project", "my app", "my startup"]
let personMarkers: [(String, String)] = [
    (#"my (wife|husband|partner|boyfriend|girlfriend|mom|mother|dad|father|brother|sister|son|daughter|friend|boss|manager|teammate|colleague|neighbor|dog|cat) (?:is |named |'s name is |'s )?([A-Z][a-z]+)"#, "relation")
]

var seen: Set<String> = []
func push(_ e: Extracted) {
    let key = e.content.lowercased()
    if seen.contains(key) { return }
    seen.insert(key)
    results.append(e)
}
for s in sentences {
    let lower = s.lowercased()
    guard durableAllowlist.contains(where: { lower.contains($0) }) else { continue }
    if volatileDenylist.contains(where: { lower.contains($0) }) { continue }
    if prefLove.contains(where: { lower.contains($0) }) {
        push(Extracted(content: "User preference: \(cleaned(s))", kind: .preference, topic: nil))
        continue
    }
    if prefHate.contains(where: { lower.contains($0) }) {
        push(Extracted(content: "User dislike: \(cleaned(s))", kind: .preference, topic: nil))
        continue
    }
    if projectMarkers.contains(where: { lower.contains($0) }) {
        push(Extracted(content: "Project: \(cleaned(s))", kind: .project, topic: "projects"))
        continue
    }
    if factSelf.contains(where: { lower.hasPrefix($0) || lower.contains(" \($0) ") }) {
        push(Extracted(content: cleaned(s), kind: .fact, topic: nil))
        continue
    }
    for (pattern, _) in personMarkers {
        if let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]),
           let match = regex.firstMatch(in: s, range: NSRange(s.startIndex..., in: s)),

               match.numberOfRanges >= 3,
               let rRel = Range(match.range(at: 1), in: s),
               let rName = Range(match.range(at: 2), in: s) {
                let rel = String(s[rRel])
                let name = String(s[rName])
                push(Extracted(content: "\(rel.capitalized): \(name)", kind: .person, topic: "people"))
                break
            }
        }
    }
    return Array(results.prefix(8))
}


nonisolated private static func durableAssistantText(_ assistantText: String, transientTexts: [String]) -> String {
    let base = assistantText.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !base.isEmpty else { return "" }
    var filtered = base
    for transient in transientTexts where !transient.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
        filtered = filtered.replacingOccurrences(of: transient, with: "", options: [.caseInsensitive])
    }
    let blockedMarkers = ["tool", "observation", "search results", "temporary status"]
    let lines = filtered
        .components(separatedBy: .newlines)
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { line in !line.isEmpty && !blockedMarkers.contains(where: { line.lowercased().contains($0) }) }
    return lines.joined(separator: " ")
}

nonisolated private static func cleaned(_ s: String) -> String {
    var out = s
    if out.count > 140 { out = String(out.prefix(140)) + "…" }
    return out
}

static func migrateExpiryIfNeeded(for item: MemoryItem) {
    // Persisted expiry columns were added after early TestFlight builds. On some upgraded
    // stores, touching those generated SwiftData accessors from the hot chat path can trap
    // before Swift can throw an error. Treat the TTL as computed policy instead of eagerly
    // reading or mutating the optional persisted cache fields during recall.
    _ = item
}

static func inferredExpiresAt(for item: MemoryItem) -> Date? {
    ttlPolicy(kind: item.memoryKind, source: item.source).ttl.map { item.createdAt.addingTimeInterval($0) }
}

static func isExpired(_ item: MemoryItem, now: Date = Date()) -> Bool {
    guard let expiresAt = inferredExpiresAt(for: item) else { return false }

        return expiresAt <= now
    }

    nonisolated static func ttlPolicy(kind: MemoryKind, source: String) -> TTLPolicy {
        let lowerSource = source.lowercased()

        if lowerSource.contains("tool") || lowerSource.contains("ephemeral") || lowerSource.contains("observation") {
            return TTLPolicy(freshness: .volatile, ttl: 45 * 60)
        }

        if lowerSource == "rem-condensed" {
            return TTLPolicy(freshness: .durable, ttl: nil)
        }

        if kind == .conversation || lowerSource.contains("crumb") || lowerSource.contains("chat") {
            return TTLPolicy(freshness: .shortLived, ttl: 6 * 60 * 60)
        }

        if kind == .preference || kind == .project || kind == .person {
            return TTLPolicy(freshness: .timeless, ttl: nil)
        }

        return TTLPolicy(freshness: .durable, ttl: 30 * 24 * 60 * 60)
    }
}

import Foundation
import Observation
import OSLog
import UIKit
