@MainActor
final class LocationAuthWaiter: NSObject, CLLocationManagerDelegate {
    /// Concurrency contract: all state mutation and callback dispatch are confined to MainActor.
    var onChange: (() -> Void)?
    private var done = false

    func finishOnce() {
        MainActor.preconditionIsolated()
        if done { return }
        done = true
        let cb = onChange
        onChange = nil
        cb?()
    }

    nonisolated func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
        Task { @MainActor in
            if manager.authorizationStatus != .notDetermined {
                self.finishOnce()
            }
        }
    }
}

import Foundation

/// Coarse token ≈ char conversion factor used for llama.cpp-style prompt budgeting.
/// SentencePiece/BPE tokenizers average ~3.5–4.2 chars/token on English text; we pick
/// a conservative value so budgets err on the side of fitting, not overflowing.
nonisolated enum PromptBudgetConstants {
    static let approxCharsPerToken: Double = 3.8
    static let safetyTokens: Int = 256
    static let hardAttachmentCeiling: Int = 80_000
    static let hardMemoriesCeiling: Int = 4_000
    static let minUserCharCap: Int = 4_000
    static let attachmentShareFraction: Double = 0.55
    static let memoriesShareFraction: Double = 0.20
    static let minHistoryChars: Int = 512
    static let minPerAttachmentChars: Int = 800
    static let fastInteractiveTotalChars: Int = 2_200
    static let fastInteractiveSystemChars: Int = 900
    static let fastInteractiveHistoryChars: Int = 420
    static let fastInteractiveMemoriesChars: Int = 220
    static let fastInteractiveMaxUserChars: Int = 280
    static let fastInteractiveUserMessageChars: Int = 160
    static let agentJSONTotalChars: Int = 3_800
    static let agentJSONSystemChars: Int = 2_200
    static let agentJSONHistoryChars: Int = 420
    static let agentJSONUserChars: Int = 900
    static let agentJSONSafetyTokens: Int = 160
}

nonisolated enum PromptLatencyClass: String, Sendable {
    case fastInteractive
    case normalInteractive
    case documentGrounded
    case developerTrace
}

nonisolated struct PromptLatencySelection: Sendable, Equatable {
    let latencyClass: PromptLatencyClass
    let reason: String
}

nonisolated enum PromptLatencyClassifier {
    static func classify(
        userMessage: String,
        attachments: [ChatAttachment],
        developerTraceModeEnabled: Bool,
        reasoningCaptureEnabled: Bool,
        modelName: String
    ) -> PromptLatencySelection {
        if developerTraceModeEnabled || reasoningCaptureEnabled {
            return PromptLatencySelection(latencyClass: .developerTrace, reason: "developer-trace")
        }
        if !attachments.isEmpty {
            return PromptLatencySelection(latencyClass: .documentGrounded, reason: "attachments")
        }
        let trimmed = userMessage.trimmingCharacters(in: .whitespacesAndNewlines)
        let lower = trimmed.lowercased()
        if modelName.lowercased().contains("json") {

            return PromptLatencySelection(latencyClass: .normalInteractive, reason: "agent-json")
        }
        if trimmed.count <= PromptBudgetConstants.fastInteractiveUserMessageChars, !looksDocumentOrToolHeavy(lower) {
            return PromptLatencySelection(latencyClass: .fastInteractive, reason: "short-simple-user-turn")
        }
        return PromptLatencySelection(latencyClass: .normalInteractive, reason: "standard-turn")
    }

    private static func looksDocumentOrToolHeavy(_ lowercasedMessage: String) -> Bool {
        let signals = [
            "file", "document", "attachment", "pdf", "rag", "search", "web", "url",
            "summarize", "analyse this", "analyze this", "read ", "browse", "tool", "codebase"
        ]
        return signals.contains { lowercasedMessage.contains($0) }
    }
}

/// Total per-section character budget for a single generation request.
/// Attachments get the largest dedicated share because they are typically the
/// biggest non-mandatory block. The user message and system prompt are always
/// fit in full (bounded by a generous cap to avoid pathological inputs).
nonisolated struct PromptBudget: Sendable {
    let totalChars: Int
    let attachmentsShare: Int
    let memoriesShare: Int
    let historyShare: Int
    let maxUserChars: Int?
    let maxSystemPromptChars: Int?

    init(totalChars: Int, attachmentsShare: Int, memoriesShare: Int, historyShare: Int, maxUserChars: Int? = nil, maxSystemPromptChars: Int? = nil) {
        self.totalChars = totalChars
        self.attachmentsShare = attachmentsShare
        self.memoriesShare = memoriesShare
        self.historyShare = historyShare
        self.maxUserChars = maxUserChars
        self.maxSystemPromptChars = maxSystemPromptChars
    }

    static func make(
        contextSize: Int,
        maxTokens: Int,
        systemPromptChars: Int,
        userMessageChars: Int,
        hasAttachments: Bool,
        hasMemories: Bool
    ) -> PromptBudget {
        let tokenBudget = max(512, contextSize - maxTokens - PromptBudgetConstants.safetyTokens)
        let totalChars = max(2048, Int(Double(tokenBudget) * PromptBudgetConstants.approxCharsPerToken))

        // Fixed cost: system prompt + a reasonable cap on user text + chat template overhead.
        let boundedUser = min(userMessageChars, max(PromptBudgetConstants.minUserCharCap, totalChars / 4))

    let templateOverhead = 512
    let fixed = min(systemPromptChars + boundedUser + templateOverhead, totalChars - 512)
    var remaining = max(1024, totalChars - fixed)

    let attachmentsShare: Int
    if hasAttachments {
        attachmentsShare = min(
            Int(Double(remaining) * PromptBudgetConstants.attachmentShareFraction),
            PromptBudgetConstants.hardAttachmentCeiling
        )
    } else {
        attachmentsShare = 0
    }
    remaining -= attachmentsShare

    let memoriesShare: Int
    if hasMemories {
        memoriesShare = min(
            Int(Double(remaining) * PromptBudgetConstants.memoriesShareFraction),
            PromptBudgetConstants.hardMemoriesCeiling
        )
    } else {
        memoriesShare = 0
    }
    remaining -= memoriesShare

    let historyShare = max(PromptBudgetConstants.minHistoryChars, remaining)

    return PromptBudget(
        totalChars: totalChars,
        attachmentsShare: attachmentsShare,
        memoriesShare: memoriesShare,
        historyShare: historyShare,
        maxUserChars: nil,
        maxSystemPromptChars: nil
    )
}

static func fastInteractive() -> PromptBudget {
    PromptBudget(
        totalChars: PromptBudgetConstants.fastInteractiveTotalChars,
        attachmentsShare: 0,
        memoriesShare: PromptBudgetConstants.fastInteractiveMemoriesChars,
        historyShare: PromptBudgetConstants.fastInteractiveHistoryChars,
        maxUserChars: PromptBudgetConstants.fastInteractiveMaxUserChars,
        maxSystemPromptChars: PromptBudgetConstants.fastInteractiveSystemChars
    )
}

static func agentJSON(contextSize: Int, maxTokens: Int) -> PromptBudget {
    let promptTokenBudget = max(
        256,
        contextSize - maxTokens - PromptBudgetConstants.agentJSONSafetyTokens
    )
    let contextBoundChars = Int(Double(promptTokenBudget) * 3.2)
    let totalChars = min(
        PromptBudgetConstants.agentJSONTotalChars,
        max(1_800, contextBoundChars)
    )
    return PromptBudget(
        totalChars: totalChars,
        attachmentsShare: 0,
        memoriesShare: 0,

            historyShare: min(PromptBudgetConstants.agentJSONHistoryChars, totalChars / 5),
            maxUserChars: min(PromptBudgetConstants.agentJSONUserChars, totalChars / 3),
            maxSystemPromptChars: min(PromptBudgetConstants.agentJSONSystemChars, (totalChars * 2) / 3)
        )
    }
}


/// Per-attachment outcome after the budget is applied. Surfaced to the UI so
/// the user can see when a file was trimmed.
nonisolated struct AttachmentRenderState: Sendable, Hashable {
    let id: UUID
    let name: String
    let includedChars: Int
    let totalChars: Int
    var truncated: Bool { includedChars < totalChars }
}

/// Result of running the prompt assembler on a request.
nonisolated struct PromptAssembly: Sendable {
    let systemPrompt: String
    let history: [(role: MessageRole, content: String)]
    let userMessage: String
    let attachmentStates: [AttachmentRenderState]
    let usedChars: Int
    let budgetChars: Int
    let latencyClass: PromptLatencyClass

    var historyTuples: [(String, String)] {
        history.map { ($0.role.rawValue, $0.content) }
    }
}

nonisolated enum AttachmentNormalizationMode: Sendable {
    case preserveRaw
    case agentRouting
}

/// Deterministic, priority-based prompt assembly.
///
/// Truncation priority (first to shrink, in order):
/// 1. Attachments — each file is head-truncated to its per-file cap and annotated
///    with a visible "[... truncated ...]" marker.
/// 2. Conversation history — oldest turns are dropped until the share fits.
///    The most recent turns are preserved because they're most relevant.
/// 3. Memories — the list is prefix-truncated to fit its share.
///
/// Preserved but bounded:
/// - The system prompt keeps original head/tail constraints when capped, with
///   fast-mode guidance appended only after preserved original instructions.
/// - The current user message, except for a final safety cap at roughly
///   ¼ of the total budget (protects against multi-MB paste dumps).
nonisolated enum PromptAssembler {

    static func assemble(
        systemPrompt: String,
        history: [(role: MessageRole, content: String)],
        userMessage: String,
        memories: [MemoryContextItem],
        attachments: [ChatAttachment],
        budget: PromptBudget,
        attachmentNormalization: AttachmentNormalizationMode = .preserveRaw,

    latencyClass: PromptLatencyClass = .normalInteractive
) -> PromptAssembly {
    let userCap = budget.maxUserChars.map { min(userMessage.count, $0) }
        ?? min(userMessage.count, max(PromptBudgetConstants.minUserCharCap, budget.totalChars / 4))
    let boundedUser = truncateMiddle(userMessage, maxChars: userCap)

    let systemCap = budget.maxSystemPromptChars ?? systemPrompt.count
    let boundedSystemPrompt = truncateSystemPrompt(systemPrompt, maxChars: systemCap, latencyClass: latencyClass)

    let memoriesBlock = buildMemoriesBlock(memories: memories, share: budget.memoriesShare, latencyClass: latencyClass)
    let (attachmentsBlock, states) = buildAttachmentsBlock(
        attachments: attachments,
        share: budget.attachmentsShare,
        normalization: attachmentNormalization
    )
    let finalSystem = boundedSystemPrompt + memoriesBlock + attachmentsBlock

    let keptHistory = fitHistory(history: history, share: budget.historyShare, latencyClass: latencyClass)

    let historyChars = keptHistory.reduce(0) { $0 + $1.content.count + 16 }
    let totalUsed = finalSystem.count + boundedUser.count + historyChars

    return PromptAssembly(
        systemPrompt: finalSystem,
        history: keptHistory,
        userMessage: boundedUser,
        attachmentStates: states,
        usedChars: totalUsed,
        budgetChars: budget.totalChars,
        latencyClass: latencyClass
    )
}

/// Lightweight preview used by the chat UI to show whether attachments
/// will be truncated at send time. Uses the same budget math as `assemble`.
static func previewAttachmentStates(
    attachments: [ChatAttachment],
    contextSize: Int,
    maxTokens: Int,
    systemPromptChars: Int,
    userMessageChars: Int,
    hasMemories: Bool
) -> [AttachmentRenderState] {
    guard !attachments.isEmpty else { return [] }
    let budget = PromptBudget.make(
        contextSize: contextSize,
        maxTokens: maxTokens,
        systemPromptChars: systemPromptChars,
        userMessageChars: userMessageChars,
        hasAttachments: true,
        hasMemories: hasMemories
    )
    let (_, states) = buildAttachmentsBlock(
        attachments: attachments,

        share: budget.attachmentsShare,
        normalization: .preserveRaw
    )
    return states
}

// MARK: - Sections

private static func buildMemoriesBlock(memories: [MemoryContextItem], share: Int, latencyClass: PromptLatencyClass) -> String {
    guard !memories.isEmpty, share > 0 else { return "" }
    var used = 0
    var items: [MemoryContextItem] = []
    let isFastInteractive = latencyClass == .fastInteractive
    let maxItems = isFastInteractive ? 2 : 10
    for m in memories.prefix(maxItems) {
        let cleaned = m.content.trimmingCharacters(in: .whitespacesAndNewlines)
        if cleaned.isEmpty { continue }
        let contentCap = isFastInteractive ? 96 : cleaned.count
        let bounded = truncateMiddle(cleaned, maxChars: contentCap)
        let line = "• [\(m.scope.rawValue) | \(m.authority.rawValue)] " + bounded
        let cost = line.count + 1
        if used + cost > share { break }
        items.append(MemoryContextItem(content: bounded, scope: m.scope, authority: m.authority, createdAt: m.createdAt, expiresAt: m.expiresAt, source: m.source, topic: m.topic))
        used += cost
    }
    return PromptContextBuilder.renderMemoryBlock(items)
}

private static func buildAttachmentsBlock(
    attachments: [ChatAttachment],
    share: Int,
    normalization: AttachmentNormalizationMode
) -> (String, [AttachmentRenderState]) {
    guard !attachments.isEmpty else { return ("", []) }

    struct Loaded { let attachment: ChatAttachment; let raw: String }
    let loaded: [Loaded] = attachments.map {
        let raw = AttachmentResolver.rawExtractText($0)
        let prepared: String
        switch normalization {
        case .preserveRaw:
            prepared = raw
        case .agentRouting:
            prepared = normalizeForAgentRouting(raw)
        }
        return Loaded(attachment: $0, raw: prepared)
    }

    if share <= 0 {
        // No room at all — still report states so UI can show "truncated".
        let states = loaded.map {
            AttachmentRenderState(
                id: $0.attachment.id,
                name: $0.attachment.name,
                includedChars: 0,
                totalChars: $0.raw.count

            )
        }
        return ("", states)
    }

    let perFileCap = max(PromptBudgetConstants.minPerAttachmentChars, share / max(1, loaded.count))
    var out = "\nThe user attached the following file(s) to this message. Treat them as authoritative context. Do NOT call files.read for them — their content is provided below.\n"
    var states: [AttachmentRenderState] = []
    states.reserveCapacity(loaded.count)

    for (i, item) in loaded.enumerated() {
        let totalCount = item.raw.count
        let included = truncateHead(item.raw, maxChars: perFileCap)
        let trimmed = included.trimmingCharacters(in: .whitespacesAndNewlines)

        out += "\n--- Attachment \(i + 1): \(item.attachment.name) (\(item.attachment.kind.rawValue)) ---\n"
        if trimmed.isEmpty {
            out += "[Could not extract text from this file.]\n"
        } else {
            out += trimmed
            if included.count < totalCount {
                let omitted = totalCount - included.count
                out += "\n[... truncated: \(omitted) more characters omitted ...]\n"
            } else {
                out += "\n"
            }
        }

        states.append(AttachmentRenderState(
            id: item.attachment.id,
            name: item.attachment.name,
            includedChars: min(included.count, totalCount),
            totalChars: totalCount
        ))
    }
    out += "--- End attachments ---\n"
    return (out, states)
}

private static func fitHistory(
    history: [(role: MessageRole, content: String)],
    share: Int,
    latencyClass: PromptLatencyClass
) -> [(role: MessageRole, content: String)] {
    guard share > 0, !history.isEmpty else { return [] }
    var kept: [(role: MessageRole, content: String)] = []
    var used = 0
    let maxTurns = latencyClass == .fastInteractive ? 2 : Int.max
    // Walk newest → oldest; prepend so original order is preserved.
    for h in history.reversed() {
        if kept.count >= maxTurns { break }
        let content = h.content.count > share
            ? truncateMiddle(h.content, maxChars: max(256, share / 2))
            : h.content
        let cost = content.count + 16

        if used + cost > share { break }
        kept.insert((role: h.role, content: content), at: 0)
        used += cost
    }
    return kept
}

// MARK: - Truncation primitives

private static func truncateSystemPrompt(_ systemPrompt: String, maxChars: Int, latencyClass: PromptLatencyClass) -> String {
    guard systemPrompt.count > maxChars else { return systemPrompt }
    guard latencyClass == .fastInteractive else { return truncateMiddle(systemPrompt, maxChars: maxChars) }
    let fastDirective = """

    Fast interactive mode: keep the answer concise for this simple turn, but continue to obey all preserved system, tool, privacy, and safety instructions above.
    """
    guard maxChars > fastDirective.count + 128 else {
        return truncateMiddle(systemPrompt, maxChars: maxChars)
    }
    let preservedOriginal = truncateMiddle(systemPrompt, maxChars: maxChars - fastDirective.count)
    return preservedOriginal + fastDirective
}

static func truncateHead(_ s: String, maxChars: Int) -> String {
    if s.count <= maxChars { return s }
    if maxChars <= 0 { return "" }
    return String(s.prefix(maxChars))
}

static func truncateMiddle(_ s: String, maxChars: Int) -> String {
    if s.count <= maxChars { return s }
    if maxChars <= 64 { return String(s.prefix(maxChars)) }
    let half = (maxChars - 32) / 2
    return String(s.prefix(half)) + "\n[... truncated ...]\n" + String(s.suffix(half))
}

private static func normalizeForAgentRouting(_ text: String) -> String {
    var normalized = text.replacingOccurrences(of: "\r\n", with: "\n")
    normalized = stripCodeFenceWrapperIfPresent(normalized)
    normalized = collapseNoisyStructuralRuns(normalized)
    normalized = normalized.replacingOccurrences(of: #"[ \t]{2,}"#, with: " ", options: .regularExpression)
    normalized = normalized.replacingOccurrences(of: #"\n{3,}"#, with: "\n\n", options: .regularExpression)
    return normalized.trimmingCharacters(in: .whitespacesAndNewlines)
}

private static func stripCodeFenceWrapperIfPresent(_ text: String) -> String {
    let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
    guard trimmed.hasPrefix("```"), trimmed.hasSuffix("```") else { return text }

        let lines = trimmed.split(separator: "\n", omittingEmptySubsequences: false)
        guard lines.count >= 2 else { return text }
        guard String(lines[0]).hasPrefix("```"), String(lines[lines.count - 1]) == "```" else { return text }
        return lines.dropFirst().dropLast().joined(separator: "\n")
    }

    private static func collapseNoisyStructuralRuns(_ text: String) -> String {
        var out = text
        out = out.replacingOccurrences(of: #"`{4,}"#, with: "```", options: .regularExpression)
        out = out.replacingOccurrences(of: #"[=_\-\*#]{8,}"#, with: "-----", options: .regularExpression)
        out = out.replacingOccurrences(of: #"[|]{4,}"#, with: "|||", options: .regularExpression)
        out = out.replacingOccurrences(of: #"[<>]{4,}"#, with: "<<<>>>", options: .regularExpression)
        out = out.replacingOccurrences(of: #"[\\/\[\]\(\)\{\}:;,+]{12,}"#, with: " [structural-run-collapsed] ", options: .regularExpression)
        return out
    }
}

import Foundation

nonisolated enum PromptContextBuilder {
    static func renderMemoryBlock(_ memories: [MemoryContextItem], limit: Int = 10) -> String {
        guard !memories.isEmpty else { return "" }
        let lines = memories.prefix(limit).map { item in
            "• [\(item.scope.rawValue) | \(item.authority.rawValue)] \(item.content)"
        }
        guard !lines.isEmpty else { return "" }
        return "\n\nRelevant memory from previous conversations:\n" + lines.joined(separator: "\n")
    }
}

import Foundation
import SwiftData
import PDFKit
import Photos
import OSLog

@MainActor
enum RAGStore {
    private static let logger = Logger(subsystem: "ai.lumen.app", category: "persistence")

    private static func persist(_ context: ModelContext, operation: String, scope: String) throws {
        guard DiskWriteBudget.shared.canWrite(bytes: 128 * 1024, category: .rag) else { return }
        do {
            try context.save()
            DiskWriteBudget.shared.recordWrite(bytes: 128 * 1024, category: .rag)
        } catch {
            logger.error("persist_failed op=\(operation, privacy: .public) scope=\(scope, privacy: .public) error=\(String(describing: error), privacy: .public)")
            throw error
        }
    }

    static func persistAndAppendVectors(
        context: ModelContext,
        operation: String,
        scope: String = "RAGChunk",
        pending: inout [(id: PersistentIdentifier, bucket: String, vector: [Double])],
        save: ((ModelContext, String, String) throws -> Void)? = nil
    ) -> Int? {
        let appendedCount = pending.count
        let saveAction = save ?? persist
        do {
            try saveAction(context, operation, scope)
        } catch {
            return nil
        }
        for item in pending {
            RAGVectorIndex.shared.append(id: item.id, bucket: item.bucket, vector: item.vector)
        }
        pending.removeAll(keepingCapacity: true)
        return appendedCount
    }

    static func auditPersistence(operation: String, scope: String, save: () throws -> Void) -> Bool {
        do {
            try save()
            return true
        } catch {
            logger.error("persist_failed op=\(operation, privacy: .public) scope=\(scope, privacy: .public) error=\(String(describing: error), privacy: .public)")
            return false
        }
    }

    static let chunkSize = 600
    static let chunkOverlap = 80
    static let candidatePoolMultiplier = 8
    static let maxCandidatePool = 256
    static let minScore: Float = 0.12

    struct SearchResult {
        let matches: [(chunk: RAGChunk, score: Double)]
        let mode: String
        let diagnostic: String?
    }

    static func search(
        query: String,
        context: ModelContext,
        limit: Int = 5,
        sourceTypes: Set<RAGSourceType>? = nil
    ) async -> [(chunk: RAGChunk, score: Double)] {

    await searchWithDiagnostics(query: query, context: context, limit: limit, sourceTypes: sourceTypes).matches
}

static func searchWithDiagnostics(
    query: String,
    context: ModelContext,
    limit: Int = 5,
    sourceTypes: Set<RAGSourceType>? = nil
) async -> SearchResult {
    let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty, limit > 0 else {
        return SearchResult(matches: [], mode: "empty_query", diagnostic: "empty_query")
    }
    let allowed: Set<String>? = sourceTypes.map { Set($0.map(\.rawValue)) }

    if let budgetDenial = ResourceBudgetGate.budgetDenialReason(policy: .embedding, reason: "rag.search") {
        logger.error("rag_embedding_budget_denied op=search reason=\(budgetDenial, privacy: .public)")
        return SearchResult(
            matches: lexicalSearch(query: trimmed, context: context, allowed: allowed, limit: limit),
            mode: "lexical_fallback",
            diagnostic: budgetDenial
        )
    }

    let queryVec: [Double]
    do {
        queryVec = try await AppLlamaService.shared.embed(trimmed)
    } catch {
        logger.error("rag_embedding_failed op=search error=\(String(describing: error), privacy: .public)")
        return SearchResult(
            matches: lexicalSearch(query: trimmed, context: context, allowed: allowed, limit: limit),
            mode: "lexical_fallback",
            diagnostic: "embedding_failed:\(RuntimeMetricErrorSanitizer.code(for: error))"
        )
    }
    guard !queryVec.isEmpty else {
        logger.error("rag_embedding_empty op=search")
        return SearchResult(
            matches: lexicalSearch(query: trimmed, context: context, allowed: allowed, limit: limit),
            mode: "lexical_fallback",
            diagnostic: "embedding_empty"
        )
    }

    RAGVectorIndex.shared.ensureLoaded(context: context)

    let k = min(max(limit * candidatePoolMultiplier, limit + 4), maxCandidatePool)

    let vectorHits = RAGVectorIndex.shared.search(
        query: queryVec,
        topK: k,
        allowedBuckets: allowed,
        minScore: minScore
    )

    var candidates = resolvedVectorCandidates(vectorHits: vectorHits, context: context)
    let vectorCandidateCount = candidates.count

    if candidates.count < limit {
        // Lexical backfill: keyword overlap as a rescue path when embeddings
        // missed obviously relevant chunks (short queries, OOV vocab, etc.).
        let seenIDs: Set<PersistentIdentifier> = Set(candidates.map { $0.0.persistentModelID })
        let lexical = lexicalScore(query: trimmed, context: context, allowed: allowed, exclude: seenIDs, limit: limit - candidates.count)
        candidates.append(contentsOf: lexical)
    }

    let sorted = candidates
        .sorted { $0.1 > $1.1 }
        .prefix(limit)
        .map { ($0.0, $0.1) }
    let mode = candidates.count > vectorCandidateCount ? "semantic_with_lexical_backfill" : "semantic"
    return SearchResult(matches: sorted, mode: mode, diagnostic: nil)
}

static func lexicalSearch(
    query: String,
    context: ModelContext,
    sourceTypes: Set<RAGSourceType>? = nil,
    limit: Int
) -> [(RAGChunk, Double)] {
    let allowed: Set<String>? = sourceTypes.map { Set($0.map(\.rawValue)) }
    return lexicalSearch(query: query, context: context, allowed: allowed, limit: limit)
}

private static func lexicalSearch(
    query: String,
    context: ModelContext,
    allowed: Set<String>?,
    limit: Int
) -> [(RAGChunk, Double)] {
    lexicalScore(query: query, context: context, allowed: allowed, exclude: [], limit: limit)
}

private static func lexicalScore(
    query: String,
    context: ModelContext,
    allowed: Set<String>?,
    exclude: Set<PersistentIdentifier>,
    limit: Int
) -> [(RAGChunk, Double)] {
    guard limit > 0 else { return [] }
    let terms = query.lowercased()
        .components(separatedBy: CharacterSet.alphanumerics.inverted)
        .filter { $0.count >= 3 }
    guard !terms.isEmpty else { return [] }
    var descriptor = FetchDescriptor<RAGChunk>()
    descriptor.fetchLimit = 400
    guard let all = try? context.fetch(descriptor) else { return [] }
    var scored: [(RAGChunk, Double)] = []
    for c in all where !exclude.contains(c.persistentModelID) {

        if let allowed, !allowed.contains(c.sourceType) { continue }
        let haystack = c.content.lowercased()
        var hits = 0
        for t in terms where haystack.contains(t) { hits += 1 }
        if hits > 0 {
            let score = Double(hits) / Double(terms.count) * 0.2
            scored.append((c, score))
        }
    }
    return scored.sorted { $0.1 > $1.1 }.prefix(limit).map { $0 }
}

static func resolvedVectorCandidates(
    vectorHits: [(id: PersistentIdentifier, score: Float)],
    context: ModelContext
) -> [(RAGChunk, Double)] {
    let chunksByID = fetchedChunksByPersistentID(context: context)
    var candidates: [(RAGChunk, Double)] = []
    candidates.reserveCapacity(vectorHits.count)
    for hit in vectorHits {
        if let chunk = chunksByID[hit.id] {
            candidates.append((chunk, Double(hit.score)))
        }
    }
    return candidates
}

private static func fetchedChunksByPersistentID(context: ModelContext) -> [PersistentIdentifier: RAGChunk] {
    let chunks = (try? context.fetch(FetchDescriptor<RAGChunk>())) ?? []
    var byID: [PersistentIdentifier: RAGChunk] = [:]
    byID.reserveCapacity(chunks.count)
    for chunk in chunks {
        byID[chunk.persistentModelID] = chunk
    }
    return byID
}

static func counts(context: ModelContext) -> [RAGSourceType: Int] {
    guard let all = try? context.fetch(FetchDescriptor<RAGChunk>()) else { return [:] }
    var out: [RAGSourceType: Int] = [:]
    for c in all { out[c.kind, default: 0] += 1 }
    return out
}

static func wipe(_ type: RAGSourceType?, context: ModelContext) throws {
    let all = try context.fetch(FetchDescriptor<RAGChunk>())
    for c in all {
        if type == nil || c.kind == type { context.delete(c) }
    }
    try persist(context, operation: "wipe", scope: "RAGChunk")
    if let type {
        RAGVectorIndex.shared.removeBucket(type.rawValue)
    } else {
        RAGVectorIndex.shared.removeAll()
    }
}

static func chunks(for type: RAGSourceType, context: ModelContext) -> [RAGChunk] {
    let raw = (try? context.fetch(FetchDescriptor<RAGChunk>())) ?? []

    return raw.filter { $0.kind == type }.sorted { $0.createdAt > $1.createdAt }
}

// MARK: - File / PDF indexing

static func indexImportedFiles(context: ModelContext, progress: ((Double) -> Void)? = nil) async -> Int {
    do {
        try wipe(.file, context: context)
        try wipe(.pdf, context: context)
    } catch {
        logger.error("persist_failed op=indexImportedFiles.cleanup scope=RAGChunk error=\(String(describing: error), privacy: .public)")
        return 0
    }
    let files = FileStore.importedFiles()
    var total = 0
    for (idx, url) in files.enumerated() {
        let added = await indexFile(url: url, context: context)
        total += added
        progress?(Double(idx + 1) / Double(max(1, files.count)))
    }
    return total
}

static func indexFile(url: URL, context: ModelContext) async -> Int {
    let name = url.lastPathComponent
    let ext = url.pathExtension.lowercased()
    let text: String
    let type: RAGSourceType

    if ext == "pdf" {
        guard let pdf = PDFDocument(url: url) else { return 0 }
        var combined = ""
        for i in 0..<pdf.pageCount {
            combined += pdf.page(at: i)?.string ?? ""
            combined += "\n\n"
        }
        text = combined
        type = .pdf
    } else if ext == "rtf" || ext == "rtfd" {
        guard let data = try? Data(contentsOf: url),
              let attr = try? NSAttributedString(data: data, options: [.documentType: NSAttributedString.DocumentType.rtf], documentAttributes: nil) else { return 0 }
        text = attr.string
        type = .file
    } else {
        guard let data = try? Data(contentsOf: url) else { return 0 }
        if let utf8 = String(data: data, encoding: .utf8) {
            text = utf8
        } else if let ascii = String(data: data, encoding: .isoLatin1) {
            text = ascii
        } else if let attr = try? NSAttributedString(data: data, options: [:], documentAttributes: nil) {
            text = attr.string
        } else {
            return 0
        }
        type = .file
    }

    RAGVectorIndex.shared.ensureLoaded(context: context)
    let pieces = chunkText(text)
    var count = 0

    var persistedCount = 0
    var pendingVectors: [(id: PersistentIdentifier, bucket: String, vector: [Double])] = []
    let cpuToken = CPUWatchdogGuard.shared.begin(category: .rag)
    defer { CPUWatchdogGuard.shared.end(token: cpuToken) }
    for (i, piece) in pieces.enumerated() {
        if Task.isCancelled || CPUWatchdogGuard.shared.shouldDegrade(category: .rag) || !ResourceBudgetGate.allowsMaintenance(reason: "rag.indexFile") { break }
        let emb: [Double]
        do {
            emb = try await AppLlamaService.shared.embed(piece)
        } catch {
            logger.error("rag_embedding_failed op=indexFile source=\(name, privacy: .public) error=\(String(describing: error), privacy: .public)")
            return 0
        }
        guard !emb.isEmpty else {
            logger.error("rag_embedding_empty op=indexFile source=\(name, privacy: .public)")
            return 0
        }
        let chunk = RAGChunk(content: piece, sourceType: type, sourceName: name, sourceRef: url.path, chunkIndex: i, embedding: emb)
        context.insert(chunk)
        pendingVectors.append((id: chunk.persistentModelID, bucket: type.rawValue, vector: emb))
        if i % 8 == 7 {
            guard let appendedCount = persistAndAppendVectors(context: context, operation: "indexFile.batch", pending: &pendingVectors) else {
                logger.error("rag_index_partial_failure op=indexFile source=\(name, privacy: .public) persisted=\(persistedCount, privacy: .public) attempted=\(count + 1, privacy: .public)")
                return persistedCount
            }
            persistedCount += appendedCount
        }
        count += 1
    }
    guard let appendedCount = persistAndAppendVectors(context: context, operation: "indexFile.complete", pending: &pendingVectors) else {
        logger.error("rag_index_partial_failure op=indexFile source=\(name, privacy: .public) persisted=\(persistedCount, privacy: .public) attempted=\(count, privacy: .public)")
        return persistedCount
    }
    persistedCount += appendedCount
    return persistedCount
}

// MARK: - Photos metadata

static func indexPhotos(monthsBack: Int = 6, context: ModelContext) async -> Int {

let status = await withCheckedContinuation { (cont: CheckedContinuation<PHAuthorizationStatus, Never>) in
    PHPhotoLibrary.requestAuthorization(for: .readWrite) { cont.resume(returning: $0) }
}
guard status == .authorized || status == .limited else { return 0 }
do {
    try wipe(.photo, context: context)
} catch {
    logger.error("persist_failed op=indexPhotos.cleanup scope=RAGChunk error=\(String(describing: error), privacy: .public)")
    return 0
}
RAGVectorIndex.shared.ensureLoaded(context: context)

let start = Calendar.current.date(byAdding: .month, value: -monthsBack, to: Date()) ?? Date()
let options = PHFetchOptions()
options.predicate = NSPredicate(format: "creationDate >= %@", start as NSDate)
options.sortDescriptors = [NSSortDescriptor(key: "creationDate", ascending: false)]
options.fetchLimit = 2000
let fetch = PHAsset.fetchAssets(with: options)

var assets: [PHAsset] = []
fetch.enumerateObjects { a, _, _ in assets.append(a) }

var selfieIDs: Set<String> = []
let selfieAlbums = PHAssetCollection.fetchAssetCollections(with: .smartAlbum, subtype: .smartAlbumSelfPortraits, options: nil)
selfieAlbums.enumerateObjects { coll, _, _ in
    let a = PHAsset.fetchAssets(in: coll, options: nil)
    a.enumerateObjects { asset, _, _ in selfieIDs.insert(asset.localIdentifier) }
}

var buckets: [String: [PHAsset]] = [:]
let df = DateFormatter(); df.dateFormat = "yyyy-MM"
for a in assets {
    let key = df.string(from: a.creationDate ?? Date())
    buckets[key, default: []].append(a)
}

var count = 0
var pendingVectors: [(id: PersistentIdentifier, bucket: String, vector: [Double])] = []
let cpuToken = CPUWatchdogGuard.shared.begin(category: .rag)
defer { CPUWatchdogGuard.shared.end(token: cpuToken) }
for (month, items) in buckets {
    if Task.isCancelled || CPUWatchdogGuard.shared.shouldDegrade(category: .rag) || !ResourceBudgetGate.allowsMaintenance(reason: "rag.indexPhotos") { break }
    let favorites = items.filter(\.isFavorite).count
    let videos = items.filter { $0.mediaType == .video }.count

        let screenshots = items.filter { $0.mediaSubtypes.contains(.photoScreenshot) }.count
        let selfies = items.filter { selfieIDs.contains($0.localIdentifier) }.count
        let livePhotos = items.filter { $0.mediaSubtypes.contains(.photoLive) }.count
        let portraits = items.filter { $0.mediaSubtypes.contains(.photoDepthEffect) }.count
        var geo = 0
        for a in items where a.location != nil { geo += 1 }

        let df2 = DateFormatter(); df2.dateStyle = .medium
        let first = items.last?.creationDate.map { df2.string(from: $0) } ?? "?"
        let last = items.first?.creationDate.map { df2.string(from: $0) } ?? "?"

        let summary = """
        Photos (\(month)): \(items.count) items between \(first) and \(last).
        \(favorites) favorites, \(videos) videos, \(screenshots) screenshots, \(selfies) selfies, \(livePhotos) live photos, \(portraits) portraits, \(geo) with location.
        """

        let emb: [Double]
        do {
            emb = try await AppLlamaService.shared.embed(summary)
        } catch {
            logger.error("rag_embedding_failed op=indexPhotos source=\(month, privacy: .public) error=\(String(describing: error), privacy: .public)")
            return 0
        }
        guard !emb.isEmpty else {
            logger.error("rag_embedding_empty op=indexPhotos source=\(month, privacy: .public)")
            return 0
        }
        let chunk = RAGChunk(content: summary, sourceType: .photo, sourceName: "Photos \(month)", sourceRef: month, chunkIndex: 0, embedding: emb)
        context.insert(chunk)
        pendingVectors.append((id: chunk.persistentModelID, bucket: RAGSourceType.photo.rawValue, vector: emb))
        count += 1
    }
    guard let persistedCount = persistAndAppendVectors(context: context, operation: "indexPhotos.complete", pending: &pendingVectors) else {
        logger.error("rag_index_partial_failure op=indexPhotos persisted=0 attempted=\(count, privacy: .public)")
        return 0
    }
    return persistedCount
}

