        return accepted("Contact search results:\n\(plainObservation)\(payloadMarkers)")
    }
    if let single = contactSummaries(from: plainObservation).first, contactSummaries(from: plainObservation).count == 1 {
        return accepted("Contact found: \(single)\(payloadMarkers)")
    }
    return accepted("Contact search results:\n\(plainObservation)\(payloadMarkers)")
case "memory.save":
    guard intent == .memory || intent == .note else { return rejected("intent-mismatch") }
    return accepted("Saved to memory: \(plainObservation)\(payloadMarkers)")
case "memory.recall":

    guard intent == .memory || intent == .note else { return rejected("intent-mismatch") }
    return accepted("Memory recall:\n\(plainObservation)\(payloadMarkers)")
case "maps.search":
    guard intent == .maps else { return rejected("intent-mismatch") }
    return accepted("Maps search results:\n\(plainObservation)\(payloadMarkers)")
case "maps.directions":
    guard intent == .maps else { return rejected("intent-mismatch") }
    return accepted("Maps directions:\n\(plainObservation)\(payloadMarkers)")
case "motion.activity":
    guard intent == .motion else { return rejected("intent-mismatch") }
    return accepted("Motion activity:\n\(plainObservation)\(payloadMarkers)")
case "health.summary":
    guard intent == .health else { return rejected("intent-mismatch") }
    return accepted("Health summary:\n\(plainObservation)\(payloadMarkers)")
case "rag.index_files":
    guard intent == .rag else { return rejected("intent-mismatch") }
    return accepted("Local file index updated: \(plainObservation)\(payloadMarkers)")
case "rag.index_photos":
    guard intent == .rag else { return rejected("intent-mismatch") }
    return accepted("Photo index updated: \(plainObservation)\(payloadMarkers)")
case "rag.search":
    guard intent == .rag else { return rejected("intent-mismatch") }
    return accepted("RAG search results:\n\(groundedRAGObservation(plainObservation))\(payloadMarkers)")
case "files.read":
    guard intent == .files || intent == .rag else { return rejected("intent-mismatch") }
    let prefix = intent == .rag ? "RAG file result" : "File result"
    return accepted("\(prefix):\n\(plainObservation)\(payloadMarkers)")
case "photos.search":
    guard intent == .photos || intent == .rag else { return rejected("intent-mismatch") }
    let prefix = intent == .rag ? "RAG photo search results" : "Photo search results"
    return accepted("\(prefix):\n\(plainObservation)\(payloadMarkers)")
case "alarm.authorization_status":
    guard intent == .alarm else { return rejected("intent-mismatch") }
    return accepted("Alarm authorization status: \(plainObservation)\(payloadMarkers)")

    case "alarm.list":
        guard intent == .alarm else { return rejected("intent-mismatch") }
        return accepted("Active alarms:\n\(plainObservation)\(payloadMarkers)")
    case "trigger.create":
        guard intent == .trigger else { return rejected("intent-mismatch") }
        return accepted("Trigger scheduled: \(plainObservation)\(payloadMarkers)")
    case "trigger.list":
        guard intent == .trigger else { return rejected("intent-mismatch") }
        return accepted("Scheduled triggers:\n\(plainObservation)\(payloadMarkers)")
    case "trigger.cancel":
        guard intent == .trigger else { return rejected("intent-mismatch") }
        return accepted("Trigger cancellation:\n\(plainObservation)\(payloadMarkers)")
    default:
        return rejected("unsupported-tool")
    }
}

private static func accepted(_ text: String) -> ToolObservationFinalizationOutcome {
    ToolObservationFinalizationOutcome(text: text, accepted: true, rejectionReason: nil)
}

private static func rejected(_ reason: String) -> ToolObservationFinalizationOutcome {
    ToolObservationFinalizationOutcome(text: nil, accepted: false, rejectionReason: reason)
}

private static func asksForDeepSynthesis(_ prompt: String) -> Bool {
    ["summarize", "compare", "analyze", "analysis", "deep", "explain", "synthesize", "pros and cons"].contains { prompt.contains($0) }
}

/// Determines whether text contains unsafe content markers.
/// - Returns: `true` if the text contains unsafe markers, `false` otherwise.
private static func looksUnsafe(_ text: String) -> Bool {
    let lower = text.lowercased()
    return lower.contains("<think") || lower.contains("{\"kind\"") || lower.contains("\"mediakind\"")
}

/// Formats and attributes a RAG search observation to the local index.
///
/// - Parameter observation: The raw observation from a RAG search.
/// - Returns: The observation with local RAG index source attribution and appropriate formatting.
private static func groundedRAGObservation(_ observation: String) -> String {
    let trimmed = observation.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else { return "No matching local snippets were retrieved. Source: local RAG index." }

        let lower = trimmed.lowercased()
        if trimmed.contains("[") || lower.contains("snippet") || lower.contains("source") {
            return trimmed
        }
        if lower.contains("no matching") || lower.contains("no relevant") {
            return "\(trimmed) Source: local RAG index; no matching module snippets were retrieved."
        }
        return "[1] \(trimmed)\nSource: local RAG index snippet."
    }

    private static func contactSummaries(from observation: String) -> [String] {
        observation
            .split(whereSeparator: \.isNewline)
            .map { line in
                line.trimmingCharacters(in: .whitespacesAndNewlines)
                    .replacingOccurrences(of: #"^\s*[•\-]\s*"#, with: "", options: .regularExpression)
            }
            .filter { !$0.isEmpty }
            .filter { !$0.lowercased().contains("no contacts match") }
    }

    /// Formats search results into a compact list, or displays fallback text when no results are available.
    /// - Parameters:
    ///   - text: A string containing encoded `WebRichContentPayload` items.
    ///   - fallback: Alternative text to display if no search results are found.
    /// - Returns: A formatted string containing up to five search results with titles, optional URLs, and snippets, or the first twelve non-empty lines of fallback text.
    private static func compactWebResults(from text: String, fallback: String) -> String {
        let payloads = WebRichContentPayload.decodeAll(from: text)
        if let payload = payloads.first(where: { $0.kind == .searchResults }), !payload.results.isEmpty {
            return payload.results.prefix(5).enumerated().map { index, result in
                var lines = ["\(index + 1). \(result.title)"]
                if let url = result.url, !url.isEmpty { lines.append(url) }
                if let snippet = result.snippet, !snippet.isEmpty { lines.append(snippet) }
                return lines.joined(separator: "\n")
            }.joined(separator: "\n\n")
        }
        return fallback
            .split(whereSeparator: \.isNewline)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .prefix(12)
            .joined(separator: "\n")
    }
}

import Foundation

#if canImport(AlarmKit)
import AlarmKit
#endif

@MainActor
enum AlarmTools {
    static func authorizationStatus() async -> String {
#if canImport(AlarmKit)
        if #available(iOS 26.0, *) {
            return "Alarm authorization: \(String(describing: AlarmManager.shared.authorizationState))."
        }
#endif
        return "AlarmKit requires iOS 26.0+ and an AlarmKit-capable runtime."
    }

    static func requestAuthorization() async -> String {
#if canImport(AlarmKit)
        if #available(iOS 26.0, *) {
            do {
                let state = try await AlarmManager.shared.requestAuthorization()
                return "Alarm authorization result: \(String(describing: state))."
            } catch {
                return "Alarm authorization failed: \(error.localizedDescription)"
            }
        }
#endif
        return "AlarmKit requires iOS 26.0+ and an AlarmKit-capable runtime."
    }

    static func schedule(args: [String: String]) async -> String {
        let title = args["title"]?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
            ? args["title"]!
            : "Alarm"
        let snoozeMinutes = Int(args["snoozeMinutes"] ?? "5") ?? 5
        let repeats = (args["repeats"] ?? "false").lowercased() == "true"

        if let inMinutes = Int(args["inMinutes"] ?? "") {
            let fireDate = Date().addingTimeInterval(TimeInterval(max(1, inMinutes) * 60))
            return await scheduleAlarm(
                title: title,
                fireDate: fireDate,
                repeats: repeats,
                snoozeMinutes: max(1, snoozeMinutes)
            )
        }

        if let unix = TimeInterval(args["timestamp"] ?? "") {
            let fireDate = Date(timeIntervalSince1970: unix)
            return await scheduleAlarm(
                title: title,
                fireDate: fireDate,
                repeats: repeats,
                snoozeMinutes: max(1, snoozeMinutes)
            )
        }

        return "Missing schedule. Provide `inMinutes` or `timestamp` (Unix seconds)."
    }

    static func countdown(args: [String: String]) async -> String {
        let title = args["title"]?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
            ? args["title"]!
            : "Countdown"
        let duration = Int(args["durationSeconds"] ?? "") ?? 0

        guard duration > 0 else {
            return "Missing duration. Provide `durationSeconds` greater than 0."
        }
        let fireDate = Date().addingTimeInterval(TimeInterval(duration))
        return await scheduleAlarm(title: title, fireDate: fireDate, repeats: false, snoozeMinutes: 1)
    }

    static func list() async -> String {
#if canImport(AlarmKit)
        if #available(iOS 26.0, *) {
            do {
                let alarms = try AlarmManager.shared.alarms
                if alarms.isEmpty { return "No active alarms." }
                return alarms.map { "• \(String(describing: $0))" }.joined(separator: "\n")
            } catch {
                return "Unable to read alarms: \(error.localizedDescription)"
            }
        }
#endif
        return "AlarmKit requires iOS 26.0+ and an AlarmKit-capable runtime."
    }

    static func cancel(id: String) async -> String {
        let trimmed = id.trimmingCharacters(in: .whitespacesAndNewlines)
        if UUID(uuidString: trimmed) != nil {
            return await mutateAlarm(id: trimmed, actionName: "cancel") {
#if canImport(AlarmKit)
                if #available(iOS 26.0, *) {
                    try AlarmManager.shared.cancel(id: $0)
                }
#endif
            }
        }
        return "Invalid alarm id. Provide the alarm UUID from `alarm.list` in `id`."
    }

    static func pause(id: String) async -> String {
        await mutateAlarm(id: id, actionName: "pause") {
#if canImport(AlarmKit)
            if #available(iOS 26.0, *) {
                try AlarmManager.shared.pause(id: $0)
            }
#endif
        }
    }

    static func resume(id: String) async -> String {
        await mutateAlarm(id: id, actionName: "resume") {
#if canImport(AlarmKit)
            if #available(iOS 26.0, *) {
                try AlarmManager.shared.resume(id: $0)
            }
#endif
        }
    }

    static func stop(id: String) async -> String {
        await mutateAlarm(id: id, actionName: "stop") {
#if canImport(AlarmKit)
            if #available(iOS 26.0, *) {
                try AlarmManager.shared.stop(id: $0)
            }
#endif
        }
    }

    static func snooze(id: String) async -> String {
        await mutateAlarm(id: id, actionName: "snooze") {
#if canImport(AlarmKit)
            if #available(iOS 26.0, *) {

                try AlarmManager.shared.countdown(id: $0)
            }
#endif
        }
    }

    private static func mutateAlarm(id: String, actionName: String, _ operation: (UUID) throws -> Void) async -> String {
        guard let uuid = UUID(uuidString: id) else {
            return "Invalid alarm id. Provide a UUID string in `id`."
        }
#if canImport(AlarmKit)
        if #available(iOS 26.0, *) {
            do {
                try operation(uuid)
                return "Alarm \(actionName) completed for \(uuid.uuidString)."
            } catch {
                return "Alarm \(actionName) failed: \(error.localizedDescription)"
            }
        }
#endif
        return "AlarmKit requires iOS 26.0+ and an AlarmKit-capable runtime."
    }

    private static func scheduleAlarm(title: String, fireDate: Date, repeats: Bool, snoozeMinutes: Int) async -> String {
#if canImport(AlarmKit)
        if #available(iOS 26.0, *) {
            return "AlarmKit scheduling entry created for \"\(title)\" at \(fireDate.formatted(date: .abbreviated, time: .shortened)). Repeats: \(repeats ? "yes" : "no"), snooze: \(snoozeMinutes)m."
        }
#endif
        _ = repeats
        _ = snoozeMinutes
        return "AlarmKit requires iOS 26.0+ and an AlarmKit-capable runtime. Requested \"\(title)\" for \(fireDate.formatted(date: .abbreviated, time: .shortened))."
    }

}

import Foundation
import EventKit

@MainActor
enum CalendarTools {
    nonisolated static let maximumSafeStartsInMinutes = Int.max / 60

    private enum CalendarOperation {
        case read
        case write
    }

    struct CalendarEventRecord: Equatable, Sendable {
        let title: String
        let start: Date
        let end: Date
        let calendarTitle: String
        let location: String?
    }

    struct CalendarListQuery: Equatable, Sendable {
        let start: Date
        let end: Date
        let limit: Int
        let titleFilter: String?
    }

    struct CalendarToolResponse: Equatable, Sendable {
        let status: ToolResultStatus
        let displayText: String
        let modelText: String
        let structuredPayload: [String: String]?
        let metricsSummary: String
        let errorCode: String?
    }

    protocol EventProvider {
        func authorizationState() -> AssistantPermissionState
        func events(start: Date, end: Date, limit: Int, titleFilter: String?) async throws -> [CalendarEventRecord]
        func createEvent(title: String, startsInMinutes: Int, now: Date) async throws -> CalendarEventRecord
    }

    struct EventKitProvider: EventProvider {
        func authorizationState() -> AssistantPermissionState {
            guard Self.hasCalendarUsageDescription else { return .unavailable }
            switch EKEventStore.authorizationStatus(for: .event) {
            case .fullAccess: return .granted
            case .writeOnly: return .limited
            case .denied: return .denied
            case .restricted: return .restricted
            case .notDetermined: return .notDetermined
            @unknown default: return .unavailable
            }
        }

        func events(start: Date, end: Date, limit: Int, titleFilter: String?) async throws -> [CalendarEventRecord] {
            let store = EKEventStore()
            let predicate = store.predicateForEvents(withStart: start, end: end, calendars: nil)
            return store.events(matching: predicate)
                .filter { event in
                    guard let titleFilter, !titleFilter.isEmpty else { return true }
                    return event.calendar.title.localizedCaseInsensitiveContains(titleFilter)
                }
                .sorted { $0.startDate < $1.startDate }
                .prefix(limit)
                .map {

                CalendarEventRecord(
                    title: $0.title ?? "Untitled",
                    start: $0.startDate,
                    end: $0.endDate,
                    calendarTitle: $0.calendar.title,
                    location: $0.location
                )
            }
    }

    func createEvent(title: String, startsInMinutes: Int, now: Date) async throws -> CalendarEventRecord {
        let store = EKEventStore()
        guard let calendar = store.defaultCalendarForNewEvents else {
            throw CalendarProviderError.providerUnavailable
        }
        guard startsInMinutes >= 0, startsInMinutes <= CalendarTools.maximumSafeStartsInMinutes else {
            throw ToolExecutionError.invalidArguments("startsInMinutes")
        }
        let event = EKEvent(eventStore: store)
        event.title = title
        event.startDate = now.addingTimeInterval(TimeInterval(startsInMinutes * 60))
        event.endDate = event.startDate.addingTimeInterval(3600)
        event.calendar = calendar
        try store.save(event, span: .thisEvent)
        return CalendarEventRecord(
            title: event.title ?? title,
            start: event.startDate,
            end: event.endDate,
            calendarTitle: calendar.title,
            location: event.location
        )
    }

    nonisolated static func hasCalendarUsageDescription(infoDictionary: [String: Any]) -> Bool {
        infoDictionary["NSCalendarsFullAccessUsageDescription"] != nil
            || infoDictionary["NSCalendarsWriteOnlyAccessUsageDescription"] != nil
            || infoDictionary["NSCalendarsUsageDescription"] != nil
    }

    private static var hasCalendarUsageDescription: Bool {
        Self.hasCalendarUsageDescription(infoDictionary: Bundle.main.infoDictionary ?? [:])
    }
}

enum CalendarProviderError: Error {
    case providerUnavailable
}

static func createEvent(
    title: String,
    startsInMinutes: Int
) async -> String {
    await createEvent(title: title, startsInMinutes: startsInMinutes, provider: EventKitProvider())
}

static func createEvent(
    title: String,
    startsInMinutes: Int,
    provider: EventProvider,

    now: Date = Date()
) async -> String {
    await createEventResult(title: title, startsInMinutes: startsInMinutes, provider: provider, now: now).displayText
}

static func createEventResult(title: String, startsInMinutes: Int) async -> CalendarToolResponse {
    await createEventResult(title: title, startsInMinutes: startsInMinutes, provider: EventKitProvider())
}

static func createEventResult(
    title: String,
    startsInMinutes: Int,
    provider: EventProvider,
    now: Date = Date()
) async -> CalendarToolResponse {
    let trimmedTitle = title.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmedTitle.isEmpty, startsInMinutes >= 0, startsInMinutes <= maximumSafeStartsInMinutes else {
        return invalidArgumentsResponse(displayText: "The calendar create request is missing a non-empty title or valid startsInMinutes argument.")
    }
    let authorizationState = provider.authorizationState()
    guard let unavailable = unavailableResponse(for: authorizationState, operation: .write) else {
        do {
            let event = try await provider.createEvent(title: trimmedTitle, startsInMinutes: startsInMinutes, now: now)
            let text = "Created event \"\(event.title)\" starting \(event.start.formatted(date: .abbreviated, time: .shortened))."
            let availability = authorizationState == .limited ? "limited" : "granted"
            return CalendarToolResponse(status: .success, displayText: text, modelText: text, structuredPayload: ["availability": availability, "created": "true"], metricsSummary: "calendar_create_success_\(availability)", errorCode: nil)
        } catch {
            return providerFailureResponse(action: "create")
        }
    }
    return unavailable
}

static func listEvents() async -> String {
    await listEventsResult(provider: EventKitProvider()).displayText
}

static func listEventsResult(arguments: [String: String] = [:], now: Date = Date()) async -> CalendarToolResponse {
    await listEventsResult(arguments: arguments, provider: EventKitProvider(), now: now)
}

static func listEventsResult(
    arguments: [String: String] = [:],
    provider: EventProvider,
    now: Date = Date()
) async -> CalendarToolResponse {

    let query: CalendarListQuery
    do {
        query = try parseListArguments(arguments, now: now)
    } catch {
        return invalidArgumentsResponse(displayText: "The calendar list request is missing valid date or limit arguments.")
    }

    guard let unavailable = unavailableResponse(for: provider.authorizationState(), operation: .read) else {
        do {
            let events = try await provider.events(start: query.start, end: query.end, limit: query.limit, titleFilter: query.titleFilter)
            if events.isEmpty {
                return CalendarToolResponse(
                    status: .success,
                    displayText: "No calendar events found in that range.",
                    modelText: "No calendar events found in that range.",
                    structuredPayload: ["availability": "granted", "count": "0"],
                    metricsSummary: "calendar_list_success_empty_granted",
                    errorCode: nil
                )
            }
            let text = events.map {
                "- \($0.title) | \(isoFormatter.string(from: $0.start)) to \(isoFormatter.string(from: $0.end)) | \($0.calendarTitle)"
            }.joined(separator: "\n")
            return CalendarToolResponse(
                status: .success,
                displayText: text,
                modelText: text,
                structuredPayload: ["availability": "granted", "count": "\(events.count)"],
                metricsSummary: "calendar_list_success_granted",
                errorCode: nil
            )
        } catch {
            return providerFailureResponse(action: "list")
        }
    }
    return unavailable
}

nonisolated static func parseListArguments(_ arguments: [String: String], now: Date = Date()) throws -> CalendarListQuery {
    let argumentDateFormatter = ISO8601DateFormatter()
    let limit: Int
    if let rawLimit = arguments["limit"] {
        guard let parsedLimit = Int(rawLimit) else { throw ToolExecutionError.invalidArguments("limit") }
        limit = parsedLimit
    } else {
        limit = 10
    }
    guard (1...20).contains(limit) else { throw ToolExecutionError.invalidArguments("limit") }

    let start: Date

    if let rawStart = arguments["startDate"] {
        guard let parsed = argumentDateFormatter.date(from: rawStart) else { throw ToolExecutionError.invalidArguments("startDate") }
        start = parsed
    } else {
        start = now
    }

    let end: Date
    if let rawEnd = arguments["endDate"] {
        guard let parsed = argumentDateFormatter.date(from: rawEnd) else { throw ToolExecutionError.invalidArguments("endDate") }
        end = parsed
    } else {
        end = now.addingTimeInterval(7 * 24 * 3600)
    }

    guard end > start else { throw ToolExecutionError.invalidArguments("endDate") }
    guard end.timeIntervalSince(start) <= 31 * 24 * 3600 else { throw ToolExecutionError.invalidArguments("date range max 31d") }

    let titleFilter = arguments["calendarTitleFilter"]?.trimmingCharacters(in: .whitespacesAndNewlines)
    if let titleFilter, titleFilter.count > 120 {
        throw ToolExecutionError.invalidArguments("calendarTitleFilter")
    }
    return CalendarListQuery(start: start, end: end, limit: limit, titleFilter: titleFilter?.isEmpty == true ? nil : titleFilter)
}

private static let isoFormatter = ISO8601DateFormatter()

private static func unavailableResponse(for state: AssistantPermissionState, operation: CalendarOperation) -> CalendarToolResponse? {
    switch state {
    case .granted:
        return nil
    case .notDetermined:
        return CalendarToolResponse(
            status: .denied,
            displayText: "Calendar access has not been granted yet. Open Lumen permissions and allow calendar access, then try again.",
            modelText: "Calendar permission is not determined.",
            structuredPayload: ["availability": "notDetermined"],
            metricsSummary: "calendar_permission_not_determined",
            errorCode: "calendar_permission_not_determined"
        )
    case .denied:
        return CalendarToolResponse(
            status: .denied,
            displayText: "Calendar access is denied. Enable calendar access in iOS Settings to use this calendar tool.",
            modelText: "Calendar permission is denied.",
            structuredPayload: ["availability": "denied"],
            metricsSummary: "calendar_permission_denied",

            errorCode: "calendar_permission_denied"
        )
    case .restricted:
        return CalendarToolResponse(
            status: .denied,
            displayText: "Calendar access is restricted on this device, so I cannot read calendar events.",
            modelText: "Calendar permission is restricted.",
            structuredPayload: ["availability": "restricted"],
            metricsSummary: "calendar_permission_restricted",
            errorCode: "calendar_permission_restricted"
        )
    case .limited:
        if operation == .write {
            return nil
        }
        return CalendarToolResponse(
            status: .denied,
            displayText: "Calendar access is write-only, so I cannot read calendar events.",
            modelText: "Calendar permission is limited.",
            structuredPayload: ["availability": "limited"],
            metricsSummary: "calendar_permission_limited",
            errorCode: "calendar_permission_limited"
        )
    case .unavailable, .unknown:
        return CalendarToolResponse(
            status: .unavailable,
            displayText: "Calendar events are unavailable on this device or build.",
            modelText: "Calendar provider is unavailable.",
            structuredPayload: ["availability": state.rawValue],
            metricsSummary: "calendar_provider_unavailable",
            errorCode: "calendar_provider_unavailable"
        )
    }
}

nonisolated static func invalidArgumentsResponse(displayText: String) -> CalendarToolResponse {
    CalendarToolResponse(
        status: .failed,
        displayText: displayText,
        modelText: "Calendar arguments are invalid.",
        structuredPayload: ["availability": "unknown", "failure": "invalidArguments"],
        metricsSummary: "calendar_invalid_arguments",
        errorCode: "calendar_invalid_arguments"
    )
}

private static func providerFailureResponse(action: String) -> CalendarToolResponse {
    CalendarToolResponse(
        status: .failed,
        displayText: "I couldn't \(action) calendar events right now. Try again later.",
        modelText: "Calendar provider failure.",

            structuredPayload: ["availability": "granted", "failure": "providerFailure"],
            metricsSummary: "calendar_provider_failure",
            errorCode: "calendar_provider_failure"
        )
    }

    static func createReminder(title: String) async -> String {
        let store = EKEventStore()
        do {
            let granted = try await store.requestFullAccessToReminders()
            guard granted else { return "Reminders access was denied." }
            let reminder = EKReminder(eventStore: store)
            reminder.title = title
            reminder.calendar = store.defaultCalendarForNewReminders()
            try store.save(reminder, commit: true)
            return "Added reminder: \"\(title)\"."
        } catch {
            return "Couldn't add reminder: \(error.localizedDescription)"
        }
    }

    static func listReminders() async -> String {
        let store = EKEventStore()
        do {
            let granted = try await store.requestFullAccessToReminders()
            guard granted else { return "Reminders access was denied." }
            let predicate = store.predicateForIncompleteReminders(withDueDateStarting: nil, ending: nil, calendars: nil)
            return await withCheckedContinuation { cont in
                store.fetchReminders(matching: predicate) { reminders in
                    let items = (reminders ?? []).prefix(5)
                    if items.isEmpty { cont.resume(returning: "No pending reminders.") }
                    else { cont.resume(returning: items.map { "• \($0.title ?? "Untitled")" }.joined(separator: "\n")) }
                }
            }
        } catch {
            return "Couldn't load reminders: \(error.localizedDescription)"
        }
    }
}

import Foundation
import Contacts
import UIKit

@MainActor
enum ContactsTools {
    static func searchContacts(query: String) async -> String {
        let store = CNContactStore()
        do {
            let granted = try await store.requestAccess(for: .contacts)
            guard granted else { return "Contacts access was denied." }
            let predicate = CNContact.predicateForContacts(matchingName: query)
            let keys: [CNKeyDescriptor] = [
                CNContactGivenNameKey as CNKeyDescriptor,
                CNContactFamilyNameKey as CNKeyDescriptor,
                CNContactPhoneNumbersKey as CNKeyDescriptor,
            ]
            let results = try store.unifiedContacts(matching: predicate, keysToFetch: keys).prefix(5)
            if results.isEmpty { return "No contacts match \"\(query)\"." }
            return results.map { c in
                let name = [c.givenName, c.familyName].filter { !$0.isEmpty }.joined(separator: " ")
                let phone = c.phoneNumbers.first?.value.stringValue ?? "no phone"
                return "• \(name) — \(phone)"
            }.joined(separator: "\n")
        } catch {
            return "Couldn't search contacts: \(error.localizedDescription)"
        }
    }

    static func call(number: String) async -> String {
        let trimmed = number.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalized = trimmed.replacingOccurrences(of: "[^0-9+]", with: "", options: .regularExpression)
        guard !normalized.isEmpty, let url = URL(string: "tel://\(normalized)") else {
            return "No phone number provided."
        }
        let ok = await UIApplication.shared.open(url)
        return ok ? "Calling \(normalized)…" : "Couldn't start call to \(normalized)."
    }

    static func composeMessage(arguments: [String: String]) async -> String {
        let body = arguments["body"] ?? arguments["message"] ?? arguments["text"] ?? ""
        let toRaw = arguments["to"] ?? arguments["recipient"] ?? arguments["number"] ?? ""
        let recipients = toRaw.split(whereSeparator: { ",;".contains($0) }).map { $0.trimmingCharacters(in: .whitespaces) }
        return await ComposeController.shared.composeMessage(to: recipients, body: body)
    }

    static func composeMail(arguments: [String: String]) async -> String {

        let body = arguments["body"] ?? arguments["message"] ?? arguments["text"] ?? ""
        let subject = arguments["subject"] ?? arguments["title"] ?? ""
        let toRaw = arguments["to"] ?? arguments["recipient"] ?? arguments["email"] ?? ""
        let recipients = toRaw.split(whereSeparator: { ",;".contains($0) }).map { $0.trimmingCharacters(in: .whitespaces) }
        return await ComposeController.shared.composeMail(to: recipients, subject: subject, body: body)
    }
}

import Foundation
import PDFKit

nonisolated enum FilesTools {
    static func readImportedFile(name: String) async -> String {
        let dir = FileStore.importsDirectory
        let trimmed = name.trimmingCharacters(in: .whitespaces)
        let fm = FileManager.default
        let files = (try? fm.contentsOfDirectory(atPath: dir.path)) ?? []
        if trimmed.isEmpty {
            if files.isEmpty { return "No imported files. Tap the paperclip to add one." }
            return "Imported files:\n" + files.map { "• \($0)" }.joined(separator: "\n")
        }
        guard let match = files.first(where: { $0.localizedCaseInsensitiveContains(trimmed) }) else {
            return "File not found. Available: \(files.joined(separator: ", "))"
        }
        let url = dir.appendingPathComponent(match)
        if url.pathExtension.lowercased() == "pdf" {
            guard let pdf = PDFDocument(url: url) else { return "Couldn't open PDF." }
            var text = ""
            for i in 0..<min(pdf.pageCount, 20) {
                text += pdf.page(at: i)?.string ?? ""
                text += "\n"
            }
            return String(text.prefix(3000))
        }
        guard let data = try? Data(contentsOf: url),
              let s = String(data: data, encoding: .utf8) else {
            return "Couldn't read \(match)."
        }
        return String(s.prefix(3000))
    }
}

import Foundation
import HealthKit

@MainActor
enum HealthTools {
    private static let healthStore = HKHealthStore()

    static func healthSummary() async -> String {
        guard HKHealthStore.isHealthDataAvailable() else {
            return "Health data isn't available on this device."
        }
        let stepType = HKQuantityType(.stepCount)
        let hrType = HKQuantityType(.heartRate)
        let sleepType = HKCategoryType(.sleepAnalysis)
        let energyType = HKQuantityType(.activeEnergyBurned)
        let distanceType = HKQuantityType(.distanceWalkingRunning)

        let readTypes: Set<HKObjectType> = [stepType, hrType, sleepType, energyType, distanceType]

        do {
            try await healthStore.requestAuthorization(toShare: [], read: readTypes)
        } catch {
            return "Couldn't request Health access: \(error.localizedDescription)"
        }

        let cal = Calendar.current
        let start = cal.startOfDay(for: Date())
        let end = Date()

        async let steps = sumQuantity(type: stepType, unit: .count(), start: start, end: end)
        async let distance = sumQuantity(type: distanceType, unit: .meter(), start: start, end: end)
        async let energy = sumQuantity(type: energyType, unit: .kilocalorie(), start: start, end: end)
        async let hr = averageQuantity(type: hrType, unit: HKUnit.count().unitDivided(by: .minute()), start: cal.date(byAdding: .hour, value: -24, to: end)!, end: end)
        async let sleep = sleepHours(start: cal.date(byAdding: .hour, value: -36, to: end)!, end: end)

        let (s, d, e, h, sl) = await (steps, distance, energy, hr, sleep)

        var parts: [String] = []
        if let s { parts.append("\(Int(s).formatted()) steps") }
        if let d { parts.append(String(format: "%.2f km", d / 1000)) }
        if let e { parts.append("\(Int(e)) kcal") }
        if let h { parts.append(String(format: "%.0f bpm avg HR", h)) }
        if let sl { parts.append(String(format: "%.1fh sleep", sl)) }

        if parts.isEmpty {
            return "No Health data available yet today (or access denied). Open the Health app and grant permission."
        }
        return "Today's Health: " + parts.joined(separator: " · ")
    }

    private static func sumQuantity(type: HKQuantityType, unit: HKUnit, start: Date, end: Date) async -> Double? {

        await withCheckedContinuation { cont in
            let predicate = HKQuery.predicateForSamples(withStart: start, end: end, options: .strictStartDate)
            let q = HKStatisticsQuery(quantityType: type, quantitySamplePredicate: predicate, options: .cumulativeSum) { _, stats, _ in
                cont.resume(returning: stats?.sumQuantity()?.doubleValue(for: unit))
            }
            healthStore.execute(q)
        }
    }

    private static func averageQuantity(type: HKQuantityType, unit: HKUnit, start: Date, end: Date) async -> Double? {
        await withCheckedContinuation { cont in
            let predicate = HKQuery.predicateForSamples(withStart: start, end: end, options: .strictStartDate)
            let q = HKStatisticsQuery(quantityType: type, quantitySamplePredicate: predicate, options: .discreteAverage) { _, stats, _ in
                cont.resume(returning: stats?.averageQuantity()?.doubleValue(for: unit))
            }
            healthStore.execute(q)
        }
    }

    private static func sleepHours(start: Date, end: Date) async -> Double? {
        await withCheckedContinuation { cont in
            let predicate = HKQuery.predicateForSamples(withStart: start, end: end, options: .strictEndDate)
            let q = HKSampleQuery(sampleType: HKCategoryType(.sleepAnalysis), predicate: predicate, limit: HKObjectQueryNoLimit, sortDescriptors: nil) { _, samples, _ in
                guard let samples = samples as? [HKCategorySample] else {
                    cont.resume(returning: nil); return
                }
                let asleepValues: Set<Int> = [
                    HKCategoryValueSleepAnalysis.asleepUnspecified.rawValue,
                    HKCategoryValueSleepAnalysis.asleepCore.rawValue,
                    HKCategoryValueSleepAnalysis.asleepDeep.rawValue,
                    HKCategoryValueSleepAnalysis.asleepREM.rawValue,
                ]
                let total = samples
                    .filter { asleepValues.contains($0.value) }
                    .reduce(0.0) { $0 + $1.endDate.timeIntervalSince($1.startDate) }
                cont.resume(returning: total > 0 ? total / 3600 : nil)
            }
            healthStore.execute(q)
        }
    }
}

import Foundation
import CoreLocation

/// One-shot location fetch with a per-call delegate — no shared singleton state.
@MainActor
enum LocationProbe {
    @MainActor private static var activeDelegates: [UUID: AnyObject] = [:]

    static func currentCoordinate(timeout: TimeInterval = 8) async -> CLLocationCoordinate2D? {
        guard case .success(let coordinate) = await currentCoordinateResult(timeout: timeout) else {
            return nil
        }
        return coordinate
    }

    static func currentCoordinateResult(timeout: TimeInterval = 8) async -> LocationCoordinateProbeResult {
        let manager = CLLocationManager()
        manager.desiredAccuracy = kCLLocationAccuracyHundredMeters
        let status = manager.authorizationStatus
        switch locationAuthorizationAction(for: status) {
        case .deniedOrRestricted:
            return .failure(LocationCoordinateFailure.authorizationFailure(for: status))
        case .unknown:
            logUnknownAuthorizationStatus(status, source: "LocationProbe.currentCoordinateResult")
            return .failure(.unknownAuthorizationStatus(rawValue: status.rawValue))
        case .requestLocation, .requestWhenInUseAuthorization, .waitForChoice:
            break
        }

        return await withCheckedContinuation { (cont: CheckedContinuation<LocationCoordinateProbeResult, Never>) in
            let token = UUID()
            let delegate = SingleShotLocationDelegate(manager: manager) { result in
                activeDelegates[token] = nil
                cont.resume(returning: result)
            }
            activeDelegates[token] = delegate
            manager.delegate = delegate

            Task { @MainActor in
                try? await Task.sleep(for: .seconds(timeout))
                delegate.finishTimedOut()
            }

            delegate.begin()
        }
    }

    static func currentDescription(timeout: TimeInterval = 8) async -> String {
        let manager = CLLocationManager()
        manager.desiredAccuracy = kCLLocationAccuracyHundredMeters
        let status = manager.authorizationStatus
        if status == .denied || status == .restricted {
            return "Location access was denied."
        }

        return await withCheckedContinuation { (cont: CheckedContinuation<String, Never>) in
            let token = UUID()

            let delegate = SingleShotDescriptionDelegate(manager: manager) { text in
                activeDelegates[token] = nil
                cont.resume(returning: text)
            }
            activeDelegates[token] = delegate
            manager.delegate = delegate

            Task { @MainActor in
                try? await Task.sleep(for: .seconds(timeout))
                delegate.finish(with: "Couldn't get location (timed out).")
            }

            delegate.begin()
        }
    }
}

enum LocationCoordinateFailure: Equatable {
    case permissionDenied
    case permissionRestricted
    case permissionNotDetermined
    case timedOut
    case unavailable(String)
    case unknownAuthorizationStatus(rawValue: Int32)

    static func authorizationFailure(for status: CLAuthorizationStatus) -> LocationCoordinateFailure {
        switch status {
        case .authorizedAlways, .authorizedWhenInUse:
            return .unavailable("Location permission is authorized, but no location was available.")
        case .denied: return .permissionDenied
        case .restricted: return .permissionRestricted
        case .notDetermined: return .permissionNotDetermined
        @unknown default: return .unknownAuthorizationStatus(rawValue: status.rawValue)
        }
    }
}

enum LocationCoordinateProbeResult {
    case success(CLLocationCoordinate2D)
    case failure(LocationCoordinateFailure)
}

private enum LocationAuthorizationAction {
    case requestLocation
    case requestWhenInUseAuthorization
    case deniedOrRestricted
    case waitForChoice
    case unknown
}

private func locationAuthorizationAction(for status: CLAuthorizationStatus) -> LocationAuthorizationAction {
    switch status {
    case .authorizedAlways, .authorizedWhenInUse:
        return .requestLocation
    case .notDetermined:
        return .requestWhenInUseAuthorization
    case .denied, .restricted:
        return .deniedOrRestricted
    @unknown default:
        return .unknown
    }
}

private func locationAuthorizationUpdateAction(for status: CLAuthorizationStatus) -> LocationAuthorizationAction {
    switch status {
    case .authorizedAlways, .authorizedWhenInUse:
        return .requestLocation
    case .notDetermined:
        return .waitForChoice
    case .denied, .restricted:
        return .deniedOrRestricted
    @unknown default:
        return .unknown
    }
}

private func logUnknownAuthorizationStatus(_ status: CLAuthorizationStatus, source: String) {
    NSLog("[LocationProbe] Unknown authorization status at %@: rawValue=%d", source, status.rawValue)
}

@MainActor
final class SingleShotLocationDelegate: NSObject, CLLocationManagerDelegate {
    /// Concurrency contract: callbacks are normalized onto MainActor before reading or mutating state.
    private let manager: CLLocationManager
    private let handler: (LocationCoordinateProbeResult) -> Void
    private var done = false

    init(manager: CLLocationManager, handler: @escaping (LocationCoordinateProbeResult) -> Void) {
        self.manager = manager
        self.handler = handler
    }

    func begin() {
        MainActor.preconditionIsolated()
        switch locationAuthorizationAction(for: manager.authorizationStatus) {
        case .requestLocation:
            manager.requestLocation()
        case .requestWhenInUseAuthorization:
            manager.requestWhenInUseAuthorization()
        case .deniedOrRestricted:
            finish(with: .failure(LocationCoordinateFailure.authorizationFailure(for: manager.authorizationStatus)))
        case .waitForChoice:
            break
        case .unknown:
            logUnknownAuthorizationStatus(manager.authorizationStatus, source: "SingleShotLocationDelegate.begin")
            finish(with: .failure(.unknownAuthorizationStatus(rawValue: manager.authorizationStatus.rawValue)))
        }
    }

    func finish(with result: LocationCoordinateProbeResult) {
        MainActor.preconditionIsolated()
        if done { return }
        done = true
        handler(result)
    }

    func finishTimedOut() {
        MainActor.preconditionIsolated()
        guard !done else { return }
        if manager.authorizationStatus == .notDetermined {
            finish(with: .failure(.permissionNotDetermined))
        } else {
            finish(with: .failure(.timedOut))
        }
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        let result: LocationCoordinateProbeResult
        if let coord = locations.last?.coordinate {
            result = .success(coord)
        } else {
            result = .failure(.unavailable("Location services returned no coordinates."))
        }
        Task { @MainActor in
            self.finish(with: result)
        }

    }

    nonisolated func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        let nsError = error as NSError
        let failure: LocationCoordinateFailure
        if nsError.domain == kCLErrorDomain,
           let code = CLError.Code(rawValue: nsError.code) {
            switch code {
            case .denied:
                failure = .permissionDenied
            case .locationUnknown, .network, .deferredFailed, .deferredNotUpdatingLocation, .promptDeclined:
                failure = .unavailable(error.localizedDescription)
            default:
                failure = .unavailable(error.localizedDescription)
            }
        } else {
            failure = .unavailable(error.localizedDescription)
        }
        Task { @MainActor in
            self.finish(with: .failure(failure))
        }
    }

    nonisolated func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
        Task { @MainActor in
            guard !self.done else { return }
            switch locationAuthorizationUpdateAction(for: manager.authorizationStatus) {
            case .requestLocation:
                manager.requestLocation()
            case .deniedOrRestricted:
                self.finish(with: .failure(LocationCoordinateFailure.authorizationFailure(for: manager.authorizationStatus)))
            case .waitForChoice, .requestWhenInUseAuthorization:
                break
            case .unknown:
                logUnknownAuthorizationStatus(manager.authorizationStatus, source: "SingleShotLocationDelegate.locationManagerDidChangeAuthorization")
                self.finish(with: .failure(.unknownAuthorizationStatus(rawValue: manager.authorizationStatus.rawValue)))
            }
        }
    }
}

@MainActor
final class SingleShotDescriptionDelegate: NSObject, CLLocationManagerDelegate {
    /// Concurrency contract: callbacks are normalized onto MainActor before reading or mutating state.
    private let manager: CLLocationManager
    private let handler: (String) -> Void
    private var done = false

    init(manager: CLLocationManager, handler: @escaping (String) -> Void) {
        self.manager = manager
        self.handler = handler
    }

    func begin() {
        MainActor.preconditionIsolated()
        switch locationAuthorizationAction(for: manager.authorizationStatus) {
        case .requestLocation:

            manager.requestLocation()
        case .requestWhenInUseAuthorization:
            manager.requestWhenInUseAuthorization()
        case .deniedOrRestricted:
            finish(with: "Location access was denied.")
        case .waitForChoice:
            break
        case .unknown:
            logUnknownAuthorizationStatus(manager.authorizationStatus, source: "SingleShotDescriptionDelegate.begin")
            finish(with: "Couldn't determine location authorization state.")
        }
    }

    func finish(with text: String) {
        MainActor.preconditionIsolated()
        if done { return }
        done = true
        handler(text)
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        let message: String
        if let loc = locations.last {
            let c = loc.coordinate
            message = String(format: "Current location: %.4f, %.4f (±%.0fm)", c.latitude, c.longitude, loc.horizontalAccuracy)
        } else {
            message = "Couldn't get location."
        }

        Task { @MainActor in
            self.finish(with: message)
        }
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        Task { @MainActor in
            self.finish(with: "Couldn't get location: \(error.localizedDescription)")
        }
    }

    nonisolated func locationManagerDidChangeAuthorization(_ manager: CLLocationManager) {
        Task { @MainActor in
            guard !self.done else { return }
            switch locationAuthorizationUpdateAction(for: manager.authorizationStatus) {
            case .requestLocation:
                manager.requestLocation()
            case .deniedOrRestricted:
                self.finish(with: "Location access was denied.")
            case .waitForChoice, .requestWhenInUseAuthorization:
                break
            case .unknown:
                logUnknownAuthorizationStatus(manager.authorizationStatus, source: "SingleShotDescriptionDelegate.locationManagerDidChangeAuthorization")
                self.finish(with: "Couldn't determine location authorization state.")
            }
        }
    }
}

import Foundation
import MapKit
import UIKit

@MainActor
enum LocationTools {
    /// Retrieves a textual description of the current location.
    /// - Returns: A string describing the current location.
    static func currentLocation() async -> String {
        await LocationProbe.currentDescription()
    }

    /// Opens the Maps app with directions to the specified destination.
    /// - Parameters:
    ///   - destination: The location or address to route to.
    /// - Returns: A message indicating success or the reason the operation could not be completed.
    static func openDirections(destination: String) -> String {
        guard let trimmed = ToolRouteGuard.sanitizedMapsDestination(destination) else {
            return "No valid Maps destination provided."
        }
        guard let url = directionsURL(destination: trimmed) else {
            return "Couldn't build maps URL."
        }
        Task { await UIApplication.shared.open(url) }
        return "Opening Maps with directions to \(trimmed)."
    }



    /// Constructs an Apple Maps URL for directions to a destination.
    /// - Returns: A URL for Apple Maps directions, or `nil` if the destination is invalid.
    static func directionsURL(destination: String) -> URL? {
        guard let destination = ToolRouteGuard.sanitizedMapsDestination(destination) else {
            return nil
        }
        // Policy: maps.apple.com deep links must use HTTPS. Plain HTTP links are
        // prohibited to avoid mixed-content/security regressions and are covered
        // by tests in LocationToolsTests.
        var components = URLComponents()
        components.scheme = "https"
        components.host = "maps.apple.com"
        components.path = "/"
        components.queryItems = [
            URLQueryItem(name: "daddr", value: destination),
        ]
        return components.url
    }
    static func searchNearby(query: String) async -> String {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "Need a nearby-place search query, for example `coffee near me`." }

        // Defense in depth: if the agent accidentally routes a generic research
        // or how-to query here, do not send it to MapKit. MapKit is for local
        // points of interest, not general web/search-engine lookups.

    if ToolRouteGuard.shouldUseWebSearchInsteadOfNearbySearch(query: trimmed) {
        return await WebTools.webSearch(query: trimmed)
    }

    let coord = await LocationProbe.currentCoordinate()
    let request = MKLocalSearch.Request()
    request.naturalLanguageQuery = trimmed
    if let coord {
        request.region = MKCoordinateRegion(center: coord, latitudinalMeters: 3000, longitudinalMeters: 3000)
    }

    do {
        let response = try await MKLocalSearch(request: request).start()
        let items = response.mapItems.prefix(5)
        if items.isEmpty { return "No nearby places found for \"\(trimmed)\"." }
        return items.map { item in
            let name = item.name ?? "Place"
            let addr = [item.placemark.thoroughfare, item.placemark.locality].compactMap { $0 }.joined(separator: ", ")
            return "• \(name) — \(addr.isEmpty ? "nearby" : addr)"
        }.joined(separator: "\n")
    } catch {
        return localSearchFailureMessage(error: error, query: trimmed)
    }
}

private static func localSearchFailureMessage(error: Error, query: String) -> String {
    let nsError = error as NSError
    if nsError.domain == MKErrorDomain {
        switch nsError.code {
        case Int(MKError.Code.placemarkNotFound.rawValue):
            return "No nearby places found for \"\(query)\". This tool only searches local map places; use web.search for general web research."
        case Int(MKError.Code.directionsNotFound.rawValue):
            return "Maps could not find directions for \"\(query)\". Try a more specific address or place name."
        case Int(MKError.Code.serverFailure.rawValue):
            return "Apple Maps search is temporarily unavailable. Try again later or use web.search for non-local information."
        case Int(MKError.Code.loadingThrottled.rawValue):
            return "Apple Maps search is rate-limited right now. Wait briefly and retry."
        default:
            return "Apple Maps could not complete the nearby search for \"\(query)\". Use this tool only for local places such as coffee shops, pharmacies, stores, or addresses."
        }
    }

        return "Apple Maps could not complete the nearby search for \"\(query)\": \(error.localizedDescription)"
    }
}

import Foundation
import SwiftData

@MainActor
enum MemoryTools {
    static func save(content: String, kind: String) async -> String {
        let trimmed = content.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "Need content." }
        let k = MemoryKind(rawValue: kind) ?? .fact
        guard let container = SharedContainer.shared else { return "Memory unavailable." }
        let ctx = ModelContext(container)
        do {
            try await MemoryStore.remember(trimmed, kind: k, source: "agent", context: ctx)
            return "Saved: \(trimmed)"
        } catch {
            return "Failed to save memory: \(error.localizedDescription)"
        }
    }

    static func recall(query: String) async -> String {
        guard let container = SharedContainer.shared else { return "Memory unavailable." }
        let ctx = ModelContext(container)
        let items = await MemoryStore.recall(query: query, context: ctx, limit: 5)
        if items.isEmpty { return "No matching memories." }
        return items.map { "• \($0.content)" }.joined(separator: "\n")
    }

    static func ragSearch(query: String, limit: Int) async -> String {
        let trimmed = query.trimmingCharacters(in: .whitespaces)
        guard !trimmed.isEmpty else { return "Need a search query." }
        guard let container = SharedContainer.shared else { return "RAG store unavailable." }
        let ctx = ModelContext(container)
        let expandedQuery = expandRAGQueryIfNeeded(trimmed)
        let results = await RAGEngine().retrieve(query: expandedQuery, limit: limit, context: ctx)
        if results.isEmpty {
            let counts = RAGStore.counts(context: ctx)
            let totalIndexed = counts.values.reduce(0, +)
            if totalIndexed == 0 {
                return "No matching files found for '\(trimmed)'. Your local index appears empty. Import or create local files/notes, then run reindex files."
            }
            return "No matching files found for '\(trimmed)'. Try a narrower query (file name, module name, or service/component keywords), or add more project notes before searching again."
        }
        return results.enumerated().map { idx, r in
            let kind = RAGSourceType(rawValue: r.source.type)?.label ?? r.source.type
            let src = "\(kind) · \(r.source.title)"

            return "[\(idx + 1)] \(src) · score \(String(format: "%.2f", r.score))\n\(r.excerpt)"
        }.joined(separator: "\n\n")
    }


    private static func expandRAGQueryIfNeeded(_ query: String) -> String {
        let lower = query.lowercased()
        let shouldExpand = ["architecture notes", "architecture", "module", "service", "component", "package"].contains { lower.contains($0) }
        guard shouldExpand else { return query }
        let expansionTerms = ["architecture", "module", "service", "component", "package"]
        return query + " " + expansionTerms.joined(separator: " ")
    }

    static func ragIndexFiles() async -> String {
        guard let container = SharedContainer.shared else { return "Store unavailable." }
        let ctx = ModelContext(container)
        let embeddingReady = await RAGStore.embeddingRuntimeAvailable()
        guard embeddingReady else {
            return "RAG indexing failed: embedding model is unavailable. Load a local embedding model, then run reindex files."
        }
        let n = await RAGStore.indexImportedFiles(context: ctx)
        if n == 0 {
            return "RAG indexing failed: no chunks were indexed. Check embedding model readiness and imported file contents."
        }
        return "Indexed \(n) chunks from imported files."
    }

    static func ragIndexPhotos(months: Int) async -> String {
        guard let container = SharedContainer.shared else { return "Store unavailable." }
        let ctx = ModelContext(container)
        let embeddingReady = await RAGStore.embeddingRuntimeAvailable()
        guard embeddingReady else {
            return "RAG photo indexing failed: embedding model is unavailable. Load a local embedding model, then try again."
        }
        let n = await RAGStore.indexPhotos(monthsBack: max(1, months), context: ctx)
        if n == 0 { return "Couldn't index photos (permission denied, empty library, or embedding failure)." }
        return "Indexed \(n) monthly photo summaries."
    }
}

import Foundation
import CoreMotion

@MainActor
final class MotionTools {
    static let shared = MotionTools()

    private let pedometer = CMPedometer()
    private let activityManager = CMMotionActivityManager()

    func motionActivity() async -> String {
        guard CMMotionActivityManager.isActivityAvailable() else {
            return "Motion activity isn't available on this device."
        }

        let end = Date()
        let start = Calendar.current.startOfDay(for: end)

        async let ped = pedometerData(start: start, end: end)
        async let activities = activitySegments(start: start, end: end)

        let (p, acts) = await (ped, activities)

        var parts: [String] = []
        if let p {
            parts.append("\(p.steps) steps")
            if let dist = p.distance { parts.append(String(format: "%.2f km", dist / 1000)) }
            if let floors = p.floors { parts.append("\(floors) floors") }
        }
        if !acts.isEmpty {
            let summary = acts.map { "\($0.minutes)m \($0.label)" }.joined(separator: ", ")
            parts.append("activity: \(summary)")
        }

        if parts.isEmpty {
            return "No motion data today. Grant Motion permission and carry the device."
        }
        return "Today's motion — " + parts.joined(separator: " · ")
    }

    private func pedometerData(start: Date, end: Date) async -> (steps: Int, distance: Double?, floors: Int?)? {
        guard CMPedometer.isStepCountingAvailable() else { return nil }
        return await withCheckedContinuation { cont in
            pedometer.queryPedometerData(from: start, to: end) { data, _ in
                guard let data else { cont.resume(returning: nil); return }
                cont.resume(returning: (data.numberOfSteps.intValue, data.distance?.doubleValue, data.floorsAscended?.intValue))
            }
        }
    }

    private func activitySegments(start: Date, end: Date) async -> [(label: String, minutes: Int)] {
        let status = CMMotionActivityManager.authorizationStatus()
        if status == .denied || status == .restricted { return [] }
        return await withCheckedContinuation { cont in
            activityManager.queryActivityStarting(from: start, to: end, to: .main) { activities, _ in
                guard let activities else { cont.resume(returning: []); return }

                var totals: [String: TimeInterval] = [:]
                for i in 0..<activities.count {
                    let a = activities[i]
                    let next = i + 1 < activities.count ? activities[i + 1].startDate : end
                    let duration = next.timeIntervalSince(a.startDate)
                    guard duration > 0 else { continue }
                    let label: String
                    if a.walking { label = "walking" }
                    else if a.running { label = "running" }
                    else if a.cycling { label = "cycling" }
                    else if a.automotive { label = "driving" }
                    else if a.stationary { label = "stationary" }
                    else { continue }
                    totals[label, default: 0] += duration
                }
                let sorted = totals
                    .map { (label: $0.key, minutes: Int($0.value / 60)) }
                    .filter { $0.minutes > 0 }
                    .sorted { $0.minutes > $1.minutes }
                cont.resume(returning: sorted)
            }
        }
    }
}

import Foundation
import Photos
import AVFoundation
import OSLog

@MainActor
enum PhotosTools {
    private static let logger = Logger(subsystem: "ai.lumen.app", category: "PhotosTools")

    static func searchPhotos(query: String) async -> String {
        let status = await withCheckedContinuation { (cont: CheckedContinuation<PHAuthorizationStatus, Never>) in
            PHPhotoLibrary.requestAuthorization(for: .readWrite) { cont.resume(returning: $0) }
        }
        guard status == .authorized || status == .limited else {
            return "Photo library access was denied."
        }

        let options = PHFetchOptions()
        options.sortDescriptors = [NSSortDescriptor(key: "creationDate", ascending: false)]
        options.fetchLimit = 500
        let assets = PHAsset.fetchAssets(with: .image, options: options)

        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let now = Date()
        let cal = Calendar.current

        var dateRange: (Date, Date)? = nil
        if trimmed.contains("today") {
            let start = cal.startOfDay(for: now)
            dateRange = (start, now)
        } else if trimmed.contains("yesterday") {
            dateRange = previousDayRange(now: now, calendar: cal)
        } else if trimmed.contains("week") {
            if let weekStart = cal.date(byAdding: .day, value: -7, to: now) {
                dateRange = (weekStart, now)
            }
        } else if trimmed.contains("month") {
            if let monthStart = cal.date(byAdding: .month, value: -1, to: now) {
                dateRange = (monthStart, now)
            }
        } else if trimmed.contains("year") {
            if let yearStart = cal.date(byAdding: .year, value: -1, to: now) {
                dateRange = (yearStart, now)
            }
        }

        let wantFavorites = trimmed.contains("favorite") || trimmed.contains("favourite")
        let wantSelfies = trimmed.contains("selfie")
        let wantVideos = trimmed.contains("video")
        let wantScreenshots = trimmed.contains("screenshot")
        let wantLivePhotos = trimmed.contains("live photo") || trimmed.contains("live")
        let wantPortraits = trimmed.contains("portrait")

        var selfieIDs: Set<String> = []
        if wantSelfies {

        let collections = PHAssetCollection.fetchAssetCollections(with: .smartAlbum, subtype: .smartAlbumSelfPortraits, options: nil)
        collections.enumerateObjects { coll, _, _ in
            let assetsInAlbum = PHAsset.fetchAssets(in: coll, options: nil)
            assetsInAlbum.enumerateObjects { a, _, _ in selfieIDs.insert(a.localIdentifier) }
        }
    }

    var matches: [PHAsset] = []
    assets.enumerateObjects { asset, _, _ in
        if let range = dateRange, let created = asset.creationDate {
            if created < range.0 || created > range.1 { return }
        }
        if wantFavorites && !asset.isFavorite { return }
        if wantScreenshots && !asset.mediaSubtypes.contains(.photoScreenshot) { return }
        if wantLivePhotos && !asset.mediaSubtypes.contains(.photoLive) { return }
        if wantPortraits && !asset.mediaSubtypes.contains(.photoDepthEffect) { return }
        if wantVideos && asset.mediaType != .video { return }
        if wantSelfies && !selfieIDs.contains(asset.localIdentifier) { return }
        matches.append(asset)
    }

    let total = matches.count
    let totalInLibrary = assets.count
    if trimmed.isEmpty {
        return "Photo library has \(totalInLibrary) images. Most recent: \(formatAssetDate(assets.firstObject?.creationDate))."
    }
    if total == 0 {
        return "No photos match \"\(query)\"."
    }
    let sample = matches.prefix(5).map { formatAssetDate($0.creationDate) }.joined(separator: ", ")
    return "Found \(total) photos matching \"\(query)\". Recent dates: \(sample)."
}

static func captureImage() async -> String {
    #if targetEnvironment(simulator)
    return "Camera is unavailable in the simulator. Install on a real device to capture images."
    #else
    let status = AVCaptureDevice.authorizationStatus(for: .video)
    let granted: Bool
    switch status {
    case .authorized:
        granted = true
    case .notDetermined:
        granted = await AVCaptureDevice.requestAccess(for: .video)
    default:
        granted = false
    }
    guard granted else { return "Camera access was denied." }
    guard AVCaptureDevice.default(for: .video) != nil else {

            return "No camera device available."
        }
        return await CameraCaptureController.shared.capture()
        #endif
    }

    private static func formatAssetDate(_ date: Date?) -> String {
        guard let date else { return "unknown date" }
        return date.formatted(date: .abbreviated, time: .shortened)
    }

    static func previousDayRange(
        now: Date,
        calendar: Calendar,
        previousDayProvider: (Calendar, Date) -> Date? = { cal, reference in
            cal.date(byAdding: .day, value: -1, to: reference)
        }
    ) -> (Date, Date) {
        if let previousDay = previousDayProvider(calendar, now) {
            return (calendar.startOfDay(for: previousDay), calendar.startOfDay(for: now))
        }

        let fallbackStart = now.addingTimeInterval(-86_400)
        logger.warning(
            "date_math_fallback tool=photos reason=previous_day_addition_failed now=\(now.formatted(date: .numeric, time: .standard), privacy: .public) fallback_start=\(fallbackStart.formatted(date: .numeric, time: .standard), privacy: .public)"
        )
        return (fallbackStart, now)
    }
}

import Foundation
import OSLog

nonisolated enum ToolNetworkErrorClass: String, Sendable {
    case timeout
    case dns
    case client4xx
    case server5xx
    case rateLimit
    case transport
    case cancelled
    case parsing
    case circuitOpen
    case unknown
}

struct ToolRetryPolicy: Sendable {
    let maxAttempts: Int
    let baseDelay: TimeInterval
    let maxDelay: TimeInterval
    let jitterRatio: Double
}

struct ToolRequestMetrics: Sendable {
    let endpoint: String
    let latencyMs: Double
    let success: Bool
    let errorClass: ToolNetworkErrorClass?
    let retryCount: Int
    let statusCode: Int?
}

actor ToolCircuitBreaker {
    private var failures: [String: [Date]] = [:]
    private var blockedUntil: [String: Date] = [:]

    func allowRequest(endpoint: String, now: Date = .init()) -> Bool {
        guard let until = blockedUntil[endpoint] else { return true }
        if until <= now {
            blockedUntil[endpoint] = nil
            return true
        }
        return false
    }

    func record(endpoint: String, success: Bool, now: Date = .init(), threshold: Int = 3, window: TimeInterval = 120, cooldown: TimeInterval = 60) {
        if success {
            failures[endpoint] = []
            blockedUntil[endpoint] = nil
            return
        }
        var endpointFailures = failures[endpoint] ?? []
        endpointFailures.append(now)
        endpointFailures = endpointFailures.filter { now.timeIntervalSince($0) <= window }
        failures[endpoint] = endpointFailures
        if endpointFailures.count >= threshold {
            blockedUntil[endpoint] = now.addingTimeInterval(cooldown)
        }
    }
}

nonisolated enum ToolNetworkTelemetry {
    private static let logger = Logger(subsystem: "ai.lumen.app", category: "tool-network")

    static func emit(_ metrics: ToolRequestMetrics) {
        logger.log("endpoint=\(metrics.endpoint, privacy: .public) success=\(metrics.success) latency_ms=\(metrics.latencyMs, format: .fixed(precision: 1)) retries=\(metrics.retryCount) status=\(metrics.statusCode ?? -1) err=\(metrics.errorClass?.rawValue ?? "none", privacy: .public)")
        NotificationCenter.default.post(name: .toolNetworkMetrics, object: metrics)
    }
}

nonisolated extension Notification.Name {
    static let toolNetworkMetrics = Notification.Name("toolNetworkMetrics")
}

nonisolated enum ToolNetworkResilience {
    static let circuitBreaker = ToolCircuitBreaker()

    static func classify(error: Error?, response: HTTPURLResponse?) -> ToolNetworkErrorClass {
        if let status = response?.statusCode {
            if status == 429 { return .rateLimit }
            if (500..<600).contains(status) { return .server5xx }
            if (400..<500).contains(status) { return .client4xx }
        }
        if let urlError = error as? URLError {
            switch urlError.code {
            case .timedOut: return .timeout
            case .cannotFindHost, .cannotConnectToHost, .dnsLookupFailed: return .dns
            case .cancelled: return .cancelled
            default: return .transport
            }
        }
        return error == nil ? .unknown : .transport
    }

    static func fallbackMessage(for errorClass: ToolNetworkErrorClass, context: String) -> String {
        RuntimeFallbackLogger.record(
            source: "tool-network-resilience",
            primaryBehavior: "return live network tool result",
            fallbackBehavior: "return bounded network failure message",
            reason: errorClass.rawValue,
            consequence: "tool result unavailable for the primary user request",
            values: ["context": context]
        )
        switch errorClass {
        case .timeout: return "\(context) timed out. Please try again in a moment."
        case .dns: return "\(context) is currently unreachable due to a network lookup issue."
        case .rateLimit: return "\(context) is rate-limited right now. Please retry shortly."
        case .client4xx: return "\(context) request was rejected. Check inputs and try again."
        case .server5xx: return "\(context) is having server issues. Please try again later."
        case .circuitOpen: return "\(context) is temporarily unavailable after repeated failures. Try again in about a minute."
        case .parsing: return "\(context) returned an unexpected response format."
        case .cancelled: return "\(context) request was cancelled."
        case .transport, .unknown: return "\(context) is temporarily unavailable. Please retry."
        }
    }

    static func shouldRetry(errorClass: ToolNetworkErrorClass) -> Bool {
        errorClass == .timeout || errorClass == .dns || errorClass == .rateLimit || errorClass == .server5xx || errorClass == .transport

    }

    static func backoffDelay(attempt: Int, policy: ToolRetryPolicy) -> UInt64 {
        let exponential = min(policy.baseDelay * pow(2.0, Double(attempt - 1)), policy.maxDelay)
        let jitter = exponential * policy.jitterRatio * Double.random(in: 0...1)
        return UInt64((exponential + jitter) * 1_000_000_000)
    }
}

import Foundation
import SwiftData

@MainActor
enum TriggerTools {
    static func create(args: [String: String]) async -> String {
        guard let container = SharedContainer.shared else { return "Store unavailable." }
        let ctx = ModelContext(container)
        let title = args["title"] ?? "Scheduled run"
        let prompt = args["prompt"] ?? title
        let schedule = TriggerScheduleType(rawValue: args["schedule"] ?? "once") ?? .once
        let trigger: Trigger
        switch schedule {
        case .once:
            let minutes = Int(args["inMinutes"] ?? "60") ?? 60
            let fire = Date().addingTimeInterval(TimeInterval(minutes * 60))
            trigger = Trigger(title: title, prompt: prompt, scheduleType: .once, fireDate: fire)
        case .daily:
            let hhmm = args["atTime"] ?? "09:00"
            let parts = hhmm.split(separator: ":").compactMap { Int($0) }
            let mins = (parts.first ?? 9) * 60 + (parts.count > 1 ? parts[1] : 0)
            trigger = Trigger(title: title, prompt: prompt, scheduleType: .daily, timeOfDayMinutes: mins)
        case .interval:
            let seconds = TimeInterval(Int(args["intervalSeconds"] ?? "3600") ?? 3600)
            trigger = Trigger(title: title, prompt: prompt, scheduleType: .interval, intervalSeconds: seconds)
        case .beforeNextEvent:
            let before = Int(args["beforeMinutes"] ?? "15") ?? 15
            trigger = Trigger(title: title, prompt: prompt, scheduleType: .beforeNextEvent, beforeNextEventMinutes: before)
        }
        trigger.nextFireAt = trigger.computeNextFire()
        ctx.insert(trigger)
        try? ctx.save()
        await TriggerScheduler.shared.requestPermission()
        TriggerScheduler.shared.scheduleBackgroundRefresh()
        let when = trigger.nextFireAt?.formatted(date: .abbreviated, time: .shortened) ?? "background"
        return "Scheduled \"\(title)\" (\(schedule.label)) — next run: \(when)."
    }

    static func list() async -> String {
        guard let container = SharedContainer.shared else { return "Store unavailable." }
        let ctx = ModelContext(container)
        let all = (try? ctx.fetch(FetchDescriptor<Trigger>())) ?? []
        if all.isEmpty { return "No scheduled runs." }
        return all.map { t in

            let next = t.nextFireAt?.formatted(date: .abbreviated, time: .shortened) ?? (t.isPaused ? "paused" : "—")
            return "• \(t.title) — \(t.kind.label) — next: \(next) — UUID: \(t.id.uuidString)"
        }.joined(separator: "\n")
    }

    static func cancel(title: String) async -> String {
        let token = title.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !token.isEmpty else {
            return "Missing trigger id or exact title."
        }
        guard let container = SharedContainer.shared else { return "Store unavailable." }
        let ctx = ModelContext(container)
        let all = (try? ctx.fetch(FetchDescriptor<Trigger>())) ?? []
        let matches: [Trigger]
        if UUID(uuidString: token) != nil {
            matches = all.filter { $0.id.uuidString.caseInsensitiveCompare(token) == .orderedSame }
        } else {
            matches = all.filter { $0.title.caseInsensitiveCompare(token) == .orderedSame }
        }
        guard matches.count == 1, let m = matches.first else {
            if matches.count > 1 {
                return "Multiple triggers match \"\(token)\". Use the UUID from the list to disambiguate."
            }
            return "No trigger matching \"\(token)\"."
        }
        ctx.delete(m)
        try? ctx.save()
        return "Cancelled \"\(m.title)\"."
    }
}

import Foundation
import CoreLocation

@MainActor
enum WeatherTools {
    private static let retryPolicy = ToolRetryPolicy(maxAttempts: 3, baseDelay: 0.4, maxDelay: 2.0, jitterRatio: 0.2)

    static func currentWeather(location: String? = nil) async -> String {
        let coordinateResult: WeatherCoordinateResolution
        let requestedLocation = (location ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let usesDeviceLocation = isCurrentLocationRequest(requestedLocation)

        if usesDeviceLocation {
            switch await LocationProbe.currentCoordinateResult() {
            case .success(let coordinate):
                coordinateResult = .success(coordinate)
            case .failure(let failure):
                coordinateResult = .failure(weatherLocationFailureMessage(for: failure))
            }
        } else {
            if let coordinate = await geocode(requestedLocation) {
                coordinateResult = .success(coordinate)
            } else {
                coordinateResult = .failure(weatherGeocodingFailureMessage(for: requestedLocation))
            }
        }

        let coordinate: CLLocationCoordinate2D
        switch coordinateResult {
        case .success(let resolvedCoordinate):
            coordinate = resolvedCoordinate
        case .failure(let message):
            return message
        }

        var components = URLComponents(string: "https://api.open-meteo.com/v1/forecast")
        components?.queryItems = [
            URLQueryItem(name: "latitude", value: String(format: "%.5f", coordinate.latitude)),
            URLQueryItem(name: "longitude", value: String(format: "%.5f", coordinate.longitude)),
            URLQueryItem(name: "current", value: "temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,cloud_cover,wind_speed_10m,wind_gusts_10m"),
            URLQueryItem(name: "timezone", value: "auto")
        ]

        guard let url = components?.url else {
            return "Couldn't build the weather request."
        }

        var request = URLRequest(url: url)
        request.setValue("Lumen iOS", forHTTPHeaderField: "User-Agent")

        let result = await executeRequest(endpoint: "openmeteo.current", request: request, timeout: 10, retryPolicy: retryPolicy, context: "Weather service")
        switch result {
        case .failure(let error):

        return error.localizedDescription
    case .success(let (data, _)):
        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let current = json["current"] as? [String: Any] else {
            return ToolNetworkResilience.fallbackMessage(for: .parsing, context: "Weather service")
        }

        let temp = currentDouble(current, "temperature_2m")
        let apparent = currentDouble(current, "apparent_temperature")
        let humidity = currentDouble(current, "relative_humidity_2m")
        let wind = currentDouble(current, "wind_speed_10m")
        let gusts = currentDouble(current, "wind_gusts_10m")
        let precipitation = currentDouble(current, "precipitation")
        let cloud = currentDouble(current, "cloud_cover")
        let code = Int(currentDouble(current, "weather_code") ?? -1)
        let time = current["time"] as? String ?? "now"

        var parts: [String] = []
        parts.append("Weather \(usesDeviceLocation ? "at your location" : "for \(requestedLocation)"):")
        if code >= 0 { parts.append(weatherDescription(code)) }
        if let temp { parts.append(String(format: "%.0f°C", temp)) }
        if let apparent { parts.append(String(format: "feels like %.0f°C", apparent)) }
        if let humidity { parts.append(String(format: "humidity %.0f%%", humidity)) }
        if let wind { parts.append(String(format: "wind %.0f km/h", wind)) }
        if let gusts, gusts > (wind ?? 0) + 5 { parts.append(String(format: "gusts %.0f km/h", gusts)) }
        if let precipitation, precipitation > 0 { parts.append(String(format: "precipitation %.1f mm", precipitation)) }
        if let cloud { parts.append(String(format: "cloud cover %.0f%%", cloud)) }
        parts.append("updated \(time)")

        return parts.joined(separator: " · ")
    }
}

nonisolated static func isCurrentLocationRequest(_ text: String) -> Bool {
    let normalized = text
        .trimmingCharacters(in: .whitespacesAndNewlines)
        .lowercased()
        .replacingOccurrences(of: #"[\s_\-]+"#, with: " ", options: .regularExpression)
    return normalized.isEmpty
        || normalized == "current"
        || normalized == "here"

        || normalized == "current location"
        || normalized == "my location"
        || normalized == "this location"
        || normalized == "device location"
        || normalized == "near me"
}

nonisolated static func weatherLocationFailureMessage(for failure: LocationCoordinateFailure) -> String {
    switch failure {
    case .permissionDenied:
        return "Location access is denied. Enable Location permission for Lumen or ask with a city, for example `weather in Montreal`."
    case .permissionRestricted:
        return "Location access is restricted on this device. Ask with a city, for example `weather in Montreal`."
    case .permissionNotDetermined:
        return "Location permission has not been granted yet. Open Lumen to approve Location access, or ask with a city, for example `weather in Montreal`."
    case .timedOut:
        return "Couldn't get your current location before the GPS timeout. Try again, move somewhere with a clearer signal, or ask with a city."
    case .unavailable(let detail):
        let trimmed = detail.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty {
            return "Couldn't get your current location from Location Services. Try again or ask with a city."
        }
        return "Couldn't get your current location from Location Services: \(trimmed)"
    case .unknownAuthorizationStatus:
        return "Couldn't determine the current Location permission state. Open Lumen to review Location permission, or ask with a city."
    }
}

nonisolated static func weatherGeocodingFailureMessage(for requestedLocation: String) -> String {
    let trimmed = requestedLocation.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
        return "I need location access, or a city name, to check the weather. Try asking `weather in Montreal` or enable Location permission."
    }
    return "Couldn't find weather coordinates for \"\(trimmed)\". Try a more specific city, region, or address."
}

private static func executeRequest(endpoint: String, request: URLRequest, timeout: TimeInterval, retryPolicy: ToolRetryPolicy, context: String) async -> Result<(Data, HTTPURLResponse?), any Error> {

if !(await ToolNetworkResilience.circuitBreaker.allowRequest(endpoint: endpoint)) {
    return .failure(NSError(domain: "WeatherTools", code: 1, userInfo: [NSLocalizedDescriptionKey: ToolNetworkResilience.fallbackMessage(for: .circuitOpen, context: context)]))
}

var req = request
req.timeoutInterval = timeout
var retries = 0
let started = Date()

for attempt in 1...retryPolicy.maxAttempts {
    do {
        let (data, response) = try await URLSession.shared.data(for: req)
        let http = response as? HTTPURLResponse
        let errorClass = ToolNetworkResilience.classify(error: nil, response: http)
        if let status = http?.statusCode, !(200..<300).contains(status) {
            if ToolNetworkResilience.shouldRetry(errorClass: errorClass), attempt < retryPolicy.maxAttempts {
                retries += 1
                try? await Task.sleep(nanoseconds: ToolNetworkResilience.backoffDelay(attempt: attempt, policy: retryPolicy))
                continue
            }
            await ToolNetworkResilience.circuitBreaker.record(endpoint: endpoint, success: false)
            ToolNetworkTelemetry.emit(.init(endpoint: endpoint, latencyMs: Date().timeIntervalSince(started) * 1000, success: false, errorClass: errorClass, retryCount: retries, statusCode: status))
            return .failure(NSError(domain: "WeatherTools", code: 2, userInfo: [NSLocalizedDescriptionKey: ToolNetworkResilience.fallbackMessage(for: errorClass, context: context)]))
        }
        await ToolNetworkResilience.circuitBreaker.record(endpoint: endpoint, success: true)
        ToolNetworkTelemetry.emit(.init(endpoint: endpoint, latencyMs: Date().timeIntervalSince(started) * 1000, success: true, errorClass: nil, retryCount: retries, statusCode: http?.statusCode))
        return .success((data, http))
    } catch {
        let errorClass = ToolNetworkResilience.classify(error: error, response: nil)
        if ToolNetworkResilience.shouldRetry(errorClass: errorClass), attempt < retryPolicy.maxAttempts {
            retries += 1
            try? await Task.sleep(nanoseconds: ToolNetworkResilience.backoffDelay(attempt: attempt, policy: retryPolicy))

                    continue
                }
                await ToolNetworkResilience.circuitBreaker.record(endpoint: endpoint, success: false)
                ToolNetworkTelemetry.emit(.init(endpoint: endpoint, latencyMs: Date().timeIntervalSince(started) * 1000, success: false, errorClass: errorClass, retryCount: retries, statusCode: nil))
                return .failure(NSError(domain: "WeatherTools", code: 2, userInfo: [NSLocalizedDescriptionKey: ToolNetworkResilience.fallbackMessage(for: errorClass, context: context), NSUnderlyingErrorKey: error]))
            }
        }
        return .failure(NSError(domain: "WeatherTools", code: 3, userInfo: [NSLocalizedDescriptionKey: ToolNetworkResilience.fallbackMessage(for: .unknown, context: context)]))
    }

    private static func geocode(_ text: String) async -> CLLocationCoordinate2D? {
        await withCheckedContinuation { continuation in
            CLGeocoder().geocodeAddressString(text) { placemarks, _ in
                continuation.resume(returning: placemarks?.first?.location?.coordinate)
            }
        }
    }

    private static func currentDouble(_ dict: [String: Any], _ key: String) -> Double? {
        if let value = dict[key] as? Double { return value }
        if let value = dict[key] as? Int { return Double(value) }
        if let value = dict[key] as? String { return Double(value) }
        return nil
    }

    private static func weatherDescription(_ code: Int) -> String {
        switch code {
        case 0: return "clear sky"
        case 1: return "mainly clear"
        case 2: return "partly cloudy"
        case 3: return "overcast"
        case 45, 48: return "fog"
        case 51, 53, 55: return "drizzle"
        case 56, 57: return "freezing drizzle"
        case 61, 63, 65: return "rain"
        case 66, 67: return "freezing rain"
        case 71, 73, 75: return "snow"
        case 77: return "snow grains"
        case 80, 81, 82: return "rain showers"
        case 85, 86: return "snow showers"
        case 95: return "thunderstorm"
        case 96, 99: return "thunderstorm with hail"
        default: return "weather code \(code)"
        }
    }
}

private enum WeatherCoordinateResolution {
    case success(CLLocationCoordinate2D)
    case failure(String)
}

import Foundation

nonisolated enum WebTools {
    private static let searchPolicy = ToolRetryPolicy(maxAttempts: 3, baseDelay: 0.35, maxDelay: 1.5, jitterRatio: 0.25)
    private static let fetchPolicy = ToolRetryPolicy(maxAttempts: 2, baseDelay: 0.4, maxDelay: 1.2, jitterRatio: 0.2)

    static func webSearch(query: String) async -> String {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "Need a query." }

        if let instant = await duckDuckGoInstantAnswer(query: trimmed), !instant.text.isEmpty {
            return instant.text + instant.payload.encodedMarker()
        }

        if let html = await duckDuckGoHTMLSearch(query: trimmed), !html.text.isEmpty {
            return html.text + html.payload.encodedMarker()
        }

        return "No search results found. Try a more specific query or provide a URL for web.fetch."
    }

    @MainActor
    static func webFetch(url: String) async -> String {
        let normalized = normalizeURL(url)
        guard let u = URL(string: normalized) else { return "Invalid URL." }
        guard let scheme = u.scheme?.lowercased(), scheme == "http" || scheme == "https" else {
            return "Invalid or unsupported URL scheme."
        }

        var req = URLRequest(url: u)
        req.setValue("Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1", forHTTPHeaderField: "User-Agent")
        req.setValue("text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8", forHTTPHeaderField: "Accept")
        req.setValue("en-US,en;q=0.9", forHTTPHeaderField: "Accept-Language")

        let direct = await executeTextRequest(endpoint: "web.fetch.urlsession", request: req, timeout: 14, retryPolicy: fetchPolicy, context: "Web page fetch")
        switch direct {
        case .failure(let error):
            return error.localizedDescription
        case .success(let (html, _)):
            return pageOutput(htmlOrText: html, url: u)
                ?? "Page was empty or unreadable. Lumen avoids hidden WebKit rendering for tool fetches to keep XPC services stable; open the page preview if you need an interactive browser view."
        }
    }

    private static func pageOutput(htmlOrText: String, url: URL) -> String? {

    let title = firstHTMLCapture(htmlOrText, pattern: #"(?is)<title[^>]*>(.*?)</title>"#).map { decodeHTMLEntities(stripHTML($0)) }
    let description = metaContent(htmlOrText, names: ["description", "og:description", "twitter:description"])
    let siteName = metaContent(htmlOrText, names: ["og:site_name", "application-name"])
    let excerpt = summarizedText(fromHTMLOrText: htmlOrText, maxCharacters: 4000)
    guard !excerpt.isEmpty else { return nil }

    let media = extractMedia(fromHTML: htmlOrText, baseURL: url)
    let page = WebFetchedPagePayload(
        title: title?.isEmpty == false ? title : nil,
        url: url.absoluteString,
        excerpt: excerpt,
        siteName: siteName,
        description: description
    )
    let payload = WebRichContentPayload(kind: .fetchedPage, page: page, media: media)

    var lines: [String] = []
    if let title, !title.isEmpty { lines.append(title) }
    if let description, !description.isEmpty { lines.append(description) }
    lines.append(url.absoluteString)
    lines.append("")
    lines.append(excerpt)
    return uniqueNonEmptyLinesKeepingBreaks(lines).joined(separator: "\n") + payload.encodedMarker()
}

private struct SearchOutput {
    let text: String
    let payload: WebRichContentPayload
}

private static func duckDuckGoInstantAnswer(query: String) async -> SearchOutput? {
    let q = query.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? query
    guard let url = URL(string: "https://api.duckduckgo.com/?q=\(q)&format=json&no_redirect=1&no_html=1&skip_disambig=1") else {
        return nil
    }

    var request = URLRequest(url: url)
    request.setValue("Mozilla/5.0 (iPhone; Lumen/2.0)", forHTTPHeaderField: "User-Agent")
    request.setValue("application/json", forHTTPHeaderField: "Accept")

    let result = await executeAPIRequest(endpoint: "duckduckgo.instant", request: request, timeout: 8, retryPolicy: searchPolicy, context: "Web search")
    switch result {
    case .failure:
        return nil
    case .success(let (data, _)):
        guard let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return nil
        }
        var lines: [String] = []

        var results: [WebSearchResultPayload] = []

        let heading = (obj["Heading"] as? String)?.nilIfEmpty
        let abstract = (obj["AbstractText"] as? String)?.nilIfEmpty
        let abstractURL = (obj["AbstractURL"] as? String)?.nilIfEmpty
        let answer = (obj["Answer"] as? String)?.nilIfEmpty

        if let heading { lines.append(heading) }
        if let abstract { lines.append(abstract) }
        if let abstractURL { lines.append(abstractURL) }
        if let answer { lines.append(answer) }

        if heading != nil || abstract != nil || abstractURL != nil {
            results.append(WebSearchResultPayload(
                title: heading ?? query,
                url: abstractURL,
                snippet: abstract ?? answer,
                source: abstractURL.flatMap { URL(string: $0)?.host },
                mediaKind: abstractURL.flatMap { mediaKind(for: $0) }
            ))
        }

        if let related = obj["RelatedTopics"] as? [[String: Any]] {
            for item in related.prefix(5) {
                collectRelatedTopic(item, lines: &lines, results: &results)
            }
        }

        let unique = uniqueNonEmptyLines(lines)
        guard !unique.isEmpty || !results.isEmpty else { return nil }
        let payload = WebRichContentPayload(kind: .searchResults, query: query, results: results, media: uniqueMedia(results.compactMap(mediaPayload(from:))))
        return SearchOutput(text: unique.joined(separator: "\n"), payload: payload)
    }
}

private static func duckDuckGoHTMLSearch(query: String) async -> SearchOutput? {
    let q = query.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? query
    guard let url = URL(string: "https://duckduckgo.com/html/?q=\(q)") else { return nil }

    var request = URLRequest(url: url)
    request.setValue("Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1", forHTTPHeaderField: "User-Agent")
    request.setValue("text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8", forHTTPHeaderField: "Accept")
    request.setValue("en-US,en;q=0.9", forHTTPHeaderField: "Accept-Language")

    let result = await executeTextRequest(endpoint: "duckduckgo.html", request: request, timeout: 12, retryPolicy: searchPolicy, context: "Web search")
    switch result {
    case .failure:
        return nil
    case .success(let (html, _)):
        let results = parseDuckDuckGoHTMLResults(html).prefix(8).map { result in
            WebSearchResultPayload(
                title: result.title,
                url: result.url,
                snippet: result.snippet,
                source: result.url.flatMap { URL(string: $0)?.host },
                mediaKind: result.url.flatMap { mediaKind(for: $0) }
            )
        }
        guard !results.isEmpty else { return nil }
        var lines = ["Search results for: \(query)"]
        for (index, result) in results.prefix(6).enumerated() {
            lines.append("\n\(index + 1). \(result.title)")
            if let snippet = result.snippet, !snippet.isEmpty { lines.append(snippet) }
            if let url = result.url, !url.isEmpty { lines.append(url) }
        }
        let payload = WebRichContentPayload(kind: .searchResults, query: query, results: Array(results), media: uniqueMedia(results.compactMap(mediaPayload(from:))))
        return SearchOutput(text: lines.joined(separator: "\n"), payload: payload)
    }
}

private static func collectRelatedTopic(_ item: [String: Any], lines: inout [String], results: inout [WebSearchResultPayload]) {
    if let text = item["Text"] as? String, !text.isEmpty {
        let url = (item["FirstURL"] as? String)?.nilIfEmpty
        lines.append("• \(text)")
        if let url { lines.append(url) }
        results.append(WebSearchResultPayload(
            title: text,
            url: url,
            snippet: text,
            source: url.flatMap { URL(string: $0)?.host },
            mediaKind: url.flatMap { mediaKind(for: $0) }
        ))
    }
    if let nested = item["Topics"] as? [[String: Any]] {
        for topic in nested.prefix(2) {
            collectRelatedTopic(topic, lines: &lines, results: &results)
        }
    }
}

private struct SearchResult: Hashable {
    let title: String
    let url: String?
    let snippet: String?
}

private static func parseDuckDuckGoHTMLResults(_ html: String) -> [SearchResult] {
    var results: [SearchResult] = []
    let resultBlockPattern = #"(?is)<div[^>]+class=\"[^\"]*result[^\"]*\"[^>]*>(.*?)</div>\s*</div>"#
    for blockMatch in html.matches(pattern: resultBlockPattern).prefix(12) {
        let block = blockMatch[1]
        guard let titleHTML = block.firstMatch(pattern: #"(?is)<a[^>]+class=\"[^\"]*result__a[^\"]*\"[^>]*>(.*?)</a>"#)?[1] else { continue }
        let title = decodeHTMLEntities(stripHTML(titleHTML))
        guard !title.isEmpty else { continue }
        let href = block.firstMatch(pattern: #"(?is)<a[^>]+class=\"[^\"]*result__a[^\"]*\"[^>]+href=\"([^\"]+)\""#)?[1]
        let snippetHTML = block.firstMatch(pattern: #"(?is)<a[^>]+class=\"[^\"]*result__snippet[^\"]*\"[^>]*>(.*?)</a>"#)?[1]
            ?? block.firstMatch(pattern: #"(?is)<div[^>]+class=\"[^\"]*result__snippet[^\"]*\"[^>]*>(.*?)</div>"#)?[1]
        let snippet = snippetHTML.map { decodeHTMLEntities(stripHTML($0)) }.flatMap { $0.isEmpty ? nil : $0 }
        let cleanedURL = href.flatMap(cleanDuckDuckGoRedirectURL)
        let result = SearchResult(title: title, url: cleanedURL, snippet: snippet)
        if !results.contains(result) { results.append(result) }
    }

    if results.isEmpty {
        let anchorPattern = #"(?is)<a[^>]+class=\"[^\"]*result__a[^\"]*\"[^>]+href=\"([^\"]+)\"[^>]*>(.*?)</a>"#
        for match in html.matches(pattern: anchorPattern).prefix(8) {
            let url = cleanDuckDuckGoRedirectURL(match[1])
            let title = decodeHTMLEntities(stripHTML(match[2]))
            guard !title.isEmpty else { continue }
            let result = SearchResult(title: title, url: url, snippet: nil)
            if !results.contains(result) { results.append(result) }
        }
    }
    return results
}

private static func cleanDuckDuckGoRedirectURL(_ raw: String) -> String? {
    let decoded = decodeHTMLEntities(raw)
    if decoded.hasPrefix("//") { return "https:\(decoded)" }
    guard let components = URLComponents(string: decoded) else { return decoded.isEmpty ? nil : decoded }
    if let uddg = components.queryItems?.first(where: { $0.name == "uddg" })?.value, !uddg.isEmpty {

        return uddg.removingPercentEncoding ?? uddg
    }
    return decoded
}

private static func normalizeURL(_ value: String) -> String {
    let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
    if trimmed.lowercased().hasPrefix("http://") || trimmed.lowercased().hasPrefix("https://") { return trimmed }
    if URL(string: trimmed)?.scheme != nil { return trimmed }
    return "https://\(trimmed)"
}

private static func executeAPIRequest(endpoint: String, request: URLRequest, timeout: TimeInterval, retryPolicy: ToolRetryPolicy, context: String) async -> Result<(Data, HTTPURLResponse?), any Error> {
    if !(await ToolNetworkResilience.circuitBreaker.allowRequest(endpoint: endpoint)) {
        return .failure(NSError(domain: "WebTools", code: 1, userInfo: [NSLocalizedDescriptionKey: ToolNetworkResilience.fallbackMessage(for: .circuitOpen, context: context)]))
    }
    var req = request
    req.timeoutInterval = timeout
    var retries = 0
    let started = Date()
    for attempt in 1...retryPolicy.maxAttempts {
        do {
            let (data, response) = try await URLSession.shared.data(for: req)
            let http = response as? HTTPURLResponse
            let errorClass = ToolNetworkResilience.classify(error: nil, response: http)
            if let status = http?.statusCode, !(200..<300).contains(status) {
                if ToolNetworkResilience.shouldRetry(errorClass: errorClass), attempt < retryPolicy.maxAttempts {
                    retries += 1
                    try? await Task.sleep(nanoseconds: ToolNetworkResilience.backoffDelay(attempt: attempt, policy: retryPolicy))
                    continue
                }
                await ToolNetworkResilience.circuitBreaker.record(endpoint: endpoint, success: false)
                ToolNetworkTelemetry.emit(.init(endpoint: endpoint, latencyMs: Date().timeIntervalSince(started) * 1000, success: false, errorClass: errorClass, retryCount: retries, statusCode: status))
                return .failure(NSError(domain: "WebTools", code: 2, userInfo: [NSLocalizedDescriptionKey: ToolNetworkResilience.fallbackMessage(for: errorClass, context: context)]))
            }

            await ToolNetworkResilience.circuitBreaker.record(endpoint: endpoint, success: true)
            ToolNetworkTelemetry.emit(.init(endpoint: endpoint, latencyMs: Date().timeIntervalSince(started) * 1000, success: true, errorClass: nil, retryCount: retries, statusCode: http?.statusCode))
            return .success((data, http))
        } catch {
            let errorClass = ToolNetworkResilience.classify(error: error, response: nil)
            if ToolNetworkResilience.shouldRetry(errorClass: errorClass), attempt < retryPolicy.maxAttempts {
                retries += 1
                try? await Task.sleep(nanoseconds: ToolNetworkResilience.backoffDelay(attempt: attempt, policy: retryPolicy))
                continue
            }
            await ToolNetworkResilience.circuitBreaker.record(endpoint: endpoint, success: false)
            ToolNetworkTelemetry.emit(.init(endpoint: endpoint, latencyMs: Date().timeIntervalSince(started) * 1000, success: false, errorClass: errorClass, retryCount: retries, statusCode: nil))
            return .failure(NSError(domain: "WebTools", code: 2, userInfo: [NSLocalizedDescriptionKey: ToolNetworkResilience.fallbackMessage(for: errorClass, context: context)]))
        }
    }
    return .failure(NSError(domain: "WebTools", code: 3, userInfo: [NSLocalizedDescriptionKey: ToolNetworkResilience.fallbackMessage(for: .unknown, context: context)]))
}

private static func executeTextRequest(endpoint: String, request: URLRequest, timeout: TimeInterval, retryPolicy: ToolRetryPolicy, context: String) async -> Result<(String, HTTPURLResponse?), any Error> {
    let dataResult = await executeAPIRequest(endpoint: endpoint, request: request, timeout: timeout, retryPolicy: retryPolicy, context: context)
    switch dataResult {
    case .failure(let error): return .failure(error)
    case .success(let (data, response)):
        if let text = String(data: data, encoding: .utf8) ?? String(data: data, encoding: .isoLatin1) ?? String(data: data, encoding: .ascii) {
            return .success((text, response))
        }
        return .failure(NSError(domain: "WebTools", code: 4, userInfo: [NSLocalizedDescriptionKey: ToolNetworkResilience.fallbackMessage(for: .parsing, context: context)]))
    }
}

private static func summarizedText(fromHTMLOrText value: String, maxCharacters: Int) -> String {
    let stripped = decodeHTMLEntities(stripHTML(value))
    let normalized = stripped.replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression).trimmingCharacters(in: .whitespacesAndNewlines)
    return String(normalized.prefix(maxCharacters))
}

private static func stripHTML(_ html: String) -> String {
    var s = html
    if let range = s.range(of: "<body", options: .caseInsensitive) { s = String(s[range.lowerBound...]) }
    let patterns = ["<script[\\s\\S]*?</script>", "<style[\\s\\S]*?</style>", "<noscript[\\s\\S]*?</noscript>", "<[^>]+>"]
    for p in patterns { s = s.replacingOccurrences(of: p, with: " ", options: .regularExpression) }
    return s
}

private static func decodeHTMLEntities(_ value: String) -> String {
    var s = value
    let entities: [(String, String)] = [("&nbsp;", " "), ("&lt;", "<"), ("&gt;", ">"), ("&quot;", "\""), ("&#39;", "'"), ("&apos;", "'"), ("&amp;", "&")]
    for (entity, replacement) in entities { s = s.replacingOccurrences(of: entity, with: replacement) }
    s = s.regexReplace(#"&#(\d+);"#) { match in
        guard let scalarValue = UInt32(match.dropFirst(2).dropLast()), let scalar = UnicodeScalar(scalarValue) else { return String(match) }
        return String(Character(scalar))
    }
    return s
}

private static func metaContent(_ html: String, names: [String]) -> String? {
    for name in names {
        let escaped = NSRegularExpression.escapedPattern(for: name)
        let patterns = [
            #"(?is)<meta[^>]+(?:name|property)=['\"]"# + escaped + #"['\"][^>]+content=['\"]([^'\"]+)['\"][^>]*>"#,
            #"(?is)<meta[^>]+content=['\"]([^'\"]+)['\"][^>]+(?:name|property)=['\"]"# + escaped + #"['\"][^>]*>"#
        ]
        for pattern in patterns {
            if let value = firstHTMLCapture(html, pattern: pattern), !value.isEmpty { return decodeHTMLEntities(value) }
        }
    }
    return nil
}

private static func firstHTMLCapture(_ html: String, pattern: String) -> String? {
    html.firstMatch(pattern: pattern)?.dropFirst().first
}

private static func extractMedia(fromHTML html: String, baseURL: URL) -> [WebMediaPayload] {

    var media: [WebMediaPayload] = []
    let imageCandidates = [
        metaContent(html, names: ["og:image", "twitter:image"]),
        firstHTMLCapture(html, pattern: #"(?is)<img[^>]+src=['\"]([^'\"]+)['\"]"#)
    ].compactMap { $0 }
    for raw in imageCandidates.prefix(4) {
        if let url = absoluteURL(raw, baseURL: baseURL) {
            media.append(WebMediaPayload(kind: .image, url: url.absoluteString, title: nil, thumbnailURL: url.absoluteString, sourcePageURL: baseURL.absoluteString))
        }
    }
    let videoCandidates = [
        metaContent(html, names: ["og:video", "og:video:url", "twitter:player"]),
        firstHTMLCapture(html, pattern: #"(?is)<video[^>]+src=['\"]([^'\"]+)['\"]"#),
        firstHTMLCapture(html, pattern: #"(?is)<source[^>]+src=['\"]([^'\"]+)['\"][^>]+type=['\"]video/[^'\"]+['\"]"#)
    ].compactMap { $0 }
    for raw in videoCandidates.prefix(3) {
        if let url = absoluteURL(raw, baseURL: baseURL) {
            media.append(WebMediaPayload(kind: .video, url: url.absoluteString, title: nil, thumbnailURL: nil, sourcePageURL: baseURL.absoluteString))
        }
    }
    let pdfPattern = #"(?is)<a[^>]+href=['\"]([^'\"]+\.pdf(?:\?[^'\"]*)?)['\"]"#
    for match in html.matches(pattern: pdfPattern).prefix(3) {
        if let url = absoluteURL(match[1], baseURL: baseURL) {
            media.append(WebMediaPayload(kind: .pdf, url: url.absoluteString, title: nil, thumbnailURL: nil, sourcePageURL: baseURL.absoluteString))
        }
    }
    return uniqueMedia(media)
}

private static func mediaPayload(from result: WebSearchResultPayload) -> WebMediaPayload? {
    guard let kind = result.mediaKind, let url = result.url else { return nil }
    return WebMediaPayload(kind: kind, url: url, title: result.title, thumbnailURL: kind == .image ? url : nil, sourcePageURL: result.url)
}

private static func mediaKind(for urlString: String) -> WebMediaPayload.Kind? {
    guard let url = URL(string: urlString) else { return nil }
    let ext = url.pathExtension.lowercased()
    if ["jpg", "jpeg", "png", "gif", "webp", "heic", "bmp"].contains(ext) { return .image }
    if ["mp4", "mov", "m4v", "webm"].contains(ext) { return .video }
    if ext == "pdf" { return .pdf }

        let host = url.host?.lowercased() ?? ""
        if host.contains("youtube.com") || host.contains("youtu.be") || host.contains("vimeo.com") { return .video }
        return .page
    }

    private static func absoluteURL(_ raw: String, baseURL: URL) -> URL? {
        let decoded = decodeHTMLEntities(raw.trimmingCharacters(in: .whitespacesAndNewlines))
        if decoded.hasPrefix("//") { return URL(string: "https:\(decoded)") }
        if let url = URL(string: decoded), url.scheme != nil { return url }
        return URL(string: decoded, relativeTo: baseURL)?.absoluteURL
    }

    private static func uniqueMedia(_ media: [WebMediaPayload]) -> [WebMediaPayload] {
        var seen: Set<String> = []
        var output: [WebMediaPayload] = []
        for item in media {
            let key = item.url.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            guard !key.isEmpty, !seen.contains(key) else { continue }
            seen.insert(key)
            output.append(item)
        }
        return output
    }

    private static func uniqueNonEmptyLines(_ lines: [String]) -> [String] {
        var seen: Set<String> = []
        var output: [String] = []
        for line in lines {
            let cleaned = line.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !cleaned.isEmpty, !seen.contains(cleaned) else { continue }
            seen.insert(cleaned)
            output.append(cleaned)
        }
        return output
    }

    private static func uniqueNonEmptyLinesKeepingBreaks(_ lines: [String]) -> [String] {
        var output: [String] = []
        for line in lines {
            if line.isEmpty { output.append(line); continue }
            let cleaned = line.trimmingCharacters(in: .whitespacesAndNewlines)
            if !cleaned.isEmpty { output.append(cleaned) }
        }
        return output
    }
}

nonisolated private extension String {
    var nilIfEmpty: String? {
        let trimmed = trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    func matches(pattern: String) -> [[String]] {
        guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else { return [] }
        let nsRange = NSRange(startIndex..<endIndex, in: self)
        return regex.matches(in: self, options: [], range: nsRange).map { result in

            (0..<result.numberOfRanges).map { index in
                let range = result.range(at: index)
                guard range.location != NSNotFound, let swiftRange = Range(range, in: self) else { return "" }
                return String(self[swiftRange])
            }
        }
    }

    func firstMatch(pattern: String) -> [String]? {
        matches(pattern: pattern).first
    }

    func regexReplace(_ pattern: String, replacement: (Substring) -> String) -> String {
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return self }
        let nsRange = NSRange(startIndex..<endIndex, in: self)
        var result = ""
        var lastIndex = startIndex
        for match in regex.matches(in: self, range: nsRange) {
            guard let range = Range(match.range, in: self) else { continue }
            result += self[lastIndex..<range.lowerBound]
            result += replacement(self[range])
            lastIndex = range.upperBound
        }
        result += self[lastIndex..<endIndex]
        return result
    }
}

import Foundation
import SwiftData
import BackgroundTasks
import UserNotifications
import EventKit
import UIKit
import OSLog

@MainActor
final class TriggerScheduler {
    static let shared = TriggerScheduler()

    nonisolated static let refreshIdentifier = "com.27pm.lumenclone.agent.refresh"
    nonisolated static let processIdentifier = "com.27pm.lumenclone.agent.process"
    nonisolated static let continuedProcessingIdentifierPrefix = "com.27pm.lumenclone.agent.continued-processing."
    nonisolated static let continuedProcessingIdentifierPattern = "\(continuedProcessingIdentifierPrefix)*"
    nonisolated static let continuedProcessingRegistrationIdentifier = continuedProcessingIdentifierPattern
    nonisolated static let notificationCategory = "LumenAgent"

    nonisolated static func continuedProcessingIdentifier(for submissionToken: String) -> String {
        "\(continuedProcessingIdentifierPrefix)\(submissionToken)"
    }

    private var registered = false
    private var isRunning = false
    var lastPermissionGranted: Bool?

    /// Optional hook so UI can observe permission changes when `requestPermission`
    /// is called from background entry points.
    var onPermissionResult: (@MainActor (Bool) -> Void)?

    private let logger = Logger(subsystem: "ai.lumen.app", category: "persistence")

    private func persist(_ context: ModelContext, operation: String, scope: String) throws {
        do { try context.save() } catch {
            logger.error("persist_failed op=\(operation, privacy: .public) scope=\(scope, privacy: .public) error=\(String(describing: error), privacy: .public)")
            throw error
        }
    }

    func auditPersistence(operation: String, scope: String, save: () throws -> Void) -> Bool {
        do {
            try save()
            return true
        } catch {
            logger.error("persist_failed op=\(operation, privacy: .public) scope=\(scope, privacy: .public) error=\(String(describing: error), privacy: .public)")
            return false
        }
    }

    func registerTasks() {
        guard !registered else { return }
        registered = true
        BGTaskScheduler.shared.register(forTaskWithIdentifier: Self.refreshIdentifier, using: nil) { task in
            guard let refresh = task as? BGAppRefreshTask else { task.setTaskCompleted(success: false); return }

        Task { @MainActor in await BackgroundOrchestrator.shared.handleAppRefresh(task: refresh) }
    }
    BGTaskScheduler.shared.register(forTaskWithIdentifier: Self.processIdentifier, using: nil) { task in
        guard let proc = task as? BGProcessingTask else { task.setTaskCompleted(success: false); return }
        Task { @MainActor in await BackgroundOrchestrator.shared.handleProcessing(task: proc) }
    }
    let center = UNUserNotificationCenter.current()
    let category = UNNotificationCategory(identifier: Self.notificationCategory, actions: [], intentIdentifiers: [], options: [])
    center.setNotificationCategories([category])
}

@discardableResult
func requestPermission() async -> Bool {
    let granted = (try? await UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .sound, .badge])) ?? false
    lastPermissionGranted = granted
    onPermissionResult?(granted)
    return granted
}

func scheduleBackgroundRefresh() {
    let req = BGAppRefreshTaskRequest(identifier: Self.refreshIdentifier)
    req.earliestBeginDate = Date().addingTimeInterval(15 * 60)
    try? BGTaskScheduler.shared.submit(req)

    let proc = BGProcessingTaskRequest(identifier: Self.processIdentifier)
    proc.earliestBeginDate = Date().addingTimeInterval(30 * 60)
    proc.requiresNetworkConnectivity = true
    proc.requiresExternalPower = false
    try? BGTaskScheduler.shared.submit(proc)
}

// MARK: - Firing

func fireDueTriggers(context: ModelContext, appState: AppState) async {
    await fireDueTriggers(context: context, settings: appState.snapshot)
}

func fireDueTriggers(context: ModelContext, settings: SettingsSnapshot) async {
    guard !isRunning else { return }
    let deadline = Date().addingTimeInterval(4.5)
    isRunning = true
    defer { isRunning = false }

    let now = Date()
    guard let all = try? context.fetch(FetchDescriptor<Trigger>()) else { return }
    for t in all where !t.isPaused {
        guard Date() < deadline else { break }
        if let next = t.nextFireAt ?? t.computeNextFire(from: now), next <= now.addingTimeInterval(30) {
            _ = await runTrigger(t, context: context, settings: settings, notify: true)

        } else if t.nextFireAt == nil {
            t.nextFireAt = t.computeNextFire(from: now)
        }
    }
    do { try persist(context, operation: "fireDueTriggers", scope: "Trigger") } catch { return }
}

@discardableResult
func runTrigger(_ trigger: Trigger, context: ModelContext, appState: AppState, notify: Bool) async -> String? {
    await runTrigger(trigger, context: context, settings: appState.snapshot, notify: notify)
}

@discardableResult
func runTrigger(_ trigger: Trigger, context: ModelContext, settings: SettingsSnapshot, notify: Bool) async -> String? {
    let result = await HeadlessAgentKernelRunner.run(prompt: trigger.prompt, settings: settings, context: context, maxSteps: min(settings.maxAgentSteps, 3), source: .trigger)
    trigger.lastRunAt = Date()
    trigger.lastResult = result.text
    updateNextFireAfterRun(for: trigger)
    do { try persist(context, operation: "runTrigger", scope: "Trigger") } catch { return nil }

    if notify {
        await postNotification(trigger: trigger, body: result.text)
    }
    return result.text
}

private func updateNextFireAfterRun(for trigger: Trigger) {
    switch trigger.kind {
    case .once:
        trigger.isPaused = true
        trigger.nextFireAt = nil
    default:
        trigger.nextFireAt = trigger.computeNextFire(from: Date())
    }
}

private func postNotification(trigger: Trigger, body: String) async {
    let content = UNMutableNotificationContent()
    content.title = trigger.title.isEmpty ? "Lumen" : trigger.title
    content.body = String(body.prefix(240))
    content.sound = .default
    content.categoryIdentifier = Self.notificationCategory
    content.userInfo = ["triggerID": trigger.id.uuidString]
    let req = UNNotificationRequest(identifier: trigger.id.uuidString, content: content, trigger: nil)
    try? await UNUserNotificationCenter.current().add(req)
}

// MARK: - Local scheduling (user-facing, best-effort while app is alive or via background refresh)

func refreshNextFireTimes(context: ModelContext) {
    guard let all = try? context.fetch(FetchDescriptor<Trigger>()) else { return }
    let now = Date()
    for t in all {

            t.nextFireAt = t.isPaused ? nil : t.computeNextFire(from: now)
        }
do { try persist(context, operation: "refreshNextFireTimes", scope: "Trigger") } catch { return }
    }

    // MARK: - Calendar helpers

    func minutesUntilNextEvent() async -> Int? {
        let store = EKEventStore()
        let granted = (try? await store.requestFullAccessToEvents()) ?? false
        guard granted else { return nil }
        let now = Date()
        let end = now.addingTimeInterval(24 * 3600)
        let pred = store.predicateForEvents(withStart: now, end: end, calendars: nil)
        let events = store.events(matching: pred).filter { $0.startDate > now }.sorted { $0.startDate < $1.startDate }
        guard let next = events.first else { return nil }
        return Int(next.startDate.timeIntervalSince(now) / 60)
    }
}

import Foundation
import SwiftData
import Accelerate

/// In-memory, pre-normalized Float32 vector index with Accelerate-accelerated search.
///
/// Design:
/// - Embeddings are stored on disk as `[Double]` on the SwiftData models (unchanged for
///   backwards compatibility). At first search we load them into a contiguous Float32
///   matrix laid out row-major so a single `vDSP_mmul` computes every cosine score
///   in one BLAS call.
/// - Embeddings from `AppLlamaService` are already L2-normalized, so `dot == cosine`.
///   We defensively re-normalize on load so stale data can't poison the index.
/// - Bucket metadata (e.g. `RAGSourceType.rawValue`) is kept parallel to the matrix
///   so source-aware filtering happens before ranking with no extra allocation.
/// - The index is incrementally appended on new inserts and invalidated on wipes to
///   avoid re-reading SwiftData on every query.
@MainActor
final class RAGVectorIndex {
    static let shared = RAGVectorIndex()

    private var ids: [PersistentIdentifier] = []
    private var buckets: [String] = []
    private var matrix: [Float] = []
    private var dim: Int = 0
    private var loaded: Bool = false

    private init() {}

    var count: Int { ids.count }
    var dimension: Int { dim }

    func invalidate() {
        ids.removeAll(keepingCapacity: false)
        buckets.removeAll(keepingCapacity: false)
        matrix.removeAll(keepingCapacity: false)
        dim = 0
        loaded = false
    }

    func ensureLoaded(context: ModelContext) {
        guard !loaded else { return }
        loaded = true
        let fetched = (try? context.fetch(FetchDescriptor<RAGChunk>())) ?? []
        ids.reserveCapacity(fetched.count)
        buckets.reserveCapacity(fetched.count)
        var d = 0
        for c in fetched where !c.embedding.isEmpty {
            if d == 0 { d = c.embedding.count }
            guard c.embedding.count == d else { continue }
            appendRow(id: c.persistentModelID, bucket: c.sourceType, vector: c.embedding, expectedDim: d)
        }
        dim = d
    }

    func append(id: PersistentIdentifier, bucket: String, vector: [Double]) {
        guard loaded, !vector.isEmpty else { return }
        if dim == 0 { dim = vector.count }
        guard vector.count == dim else { return }
        appendRow(id: id, bucket: bucket, vector: vector, expectedDim: dim)
    }

func removeBucket(_ bucket: String) {
    guard loaded, !ids.isEmpty else { return }
    var keep = [Bool](repeating: true, count: ids.count)
    var removed = 0
    for i in 0..<ids.count where buckets[i] == bucket {
        keep[i] = false
        removed += 1
    }
    if removed == 0 { return }
    if removed == ids.count {
        ids.removeAll(keepingCapacity: true)
        buckets.removeAll(keepingCapacity: true)
        matrix.removeAll(keepingCapacity: true)
        return
    }
    compact(keep: keep)
}

func removeAll() {
    ids.removeAll(keepingCapacity: true)
    buckets.removeAll(keepingCapacity: true)
    matrix.removeAll(keepingCapacity: true)
}

func search(
    query: [Double],
    topK: Int,
    allowedBuckets: Set<String>? = nil,
    minScore: Float = 0.0
) -> [(id: PersistentIdentifier, score: Float)] {
    guard loaded, !ids.isEmpty, dim > 0, query.count == dim, topK > 0 else { return [] }
    let q = VectorMath.toFloat32Normalized(query)
    let rows = ids.count
    var scores = [Float](repeating: 0, count: rows)
    matrix.withUnsafeBufferPointer { m in
        q.withUnsafeBufferPointer { qp in
            scores.withUnsafeMutableBufferPointer { sp in
                vDSP_mmul(
                    m.baseAddress!, 1,
                    qp.baseAddress!, 1,
                    sp.baseAddress!, 1,
                    vDSP_Length(rows),
                    1,
                    vDSP_Length(dim)
                )
            }
        }
    }
    return VectorMath.topK(
        scores: scores,
        k: topK,
        minScore: minScore,
        includeIndex: { idx in
            guard let allowed = allowedBuckets else { return true }
            return allowed.contains(buckets[idx])
        }
    ).map { (ids[$0.0], $0.1) }
}

private func appendRow(id: PersistentIdentifier, bucket: String, vector: [Double], expectedDim: Int) {
    ids.append(id)
    buckets.append(bucket)
    matrix.reserveCapacity(matrix.count + expectedDim)
    let normalized = VectorMath.toFloat32Normalized(vector)
    matrix.append(contentsOf: normalized)
}

private func compact(keep: [Bool]) {

        var newIds: [PersistentIdentifier] = []
        var newBuckets: [String] = []
        var newMatrix: [Float] = []
        newIds.reserveCapacity(ids.count)
        newBuckets.reserveCapacity(ids.count)
        newMatrix.reserveCapacity(matrix.count)
        for i in 0..<ids.count where keep[i] {
            newIds.append(ids[i])
            newBuckets.append(buckets[i])
            let start = i * dim
            newMatrix.append(contentsOf: matrix[start..<(start + dim)])
        }
        ids = newIds
        buckets = newBuckets
        matrix = newMatrix
    }
}

@MainActor
final class MemoryVectorIndex {
    static let shared = MemoryVectorIndex()

    private var ids: [PersistentIdentifier] = []
    private var pinned: [Bool] = []
    private var matrix: [Float] = []
    private var dim: Int = 0
    private var loaded: Bool = false

    private init() {}

    func invalidate() {
        ids.removeAll(keepingCapacity: false)
        pinned.removeAll(keepingCapacity: false)
        matrix.removeAll(keepingCapacity: false)
        dim = 0
        loaded = false
    }

    func ensureLoaded(context: ModelContext) {
        guard !loaded else { return }
        loaded = true
        let fetched = (try? context.fetch(FetchDescriptor<MemoryItem>())) ?? []
        var d = 0
        for m in fetched where !m.embedding.isEmpty {
            if d == 0 { d = m.embedding.count }
            guard m.embedding.count == d else { continue }
            append(id: m.persistentModelID, isPinned: m.isPinned, vector: m.embedding, expectedDim: d)
        }
        dim = d
    }

    func append(id: PersistentIdentifier, isPinned: Bool, vector: [Double]) {
        guard loaded, !vector.isEmpty else { return }
        if dim == 0 { dim = vector.count }
        guard vector.count == dim else { return }
        append(id: id, isPinned: isPinned, vector: vector, expectedDim: dim)
    }

    func removeAll(keepPinned: Bool) {
        guard loaded else { return }
        if !keepPinned {
            ids.removeAll(keepingCapacity: true)
            pinned.removeAll(keepingCapacity: true)
            matrix.removeAll(keepingCapacity: true)
            return
        }
        var keep = [Bool](repeating: true, count: ids.count)
        var removed = 0
        for i in 0..<ids.count where !pinned[i] {
            keep[i] = false
            removed += 1
        }

        if removed == 0 { return }
        var newIds: [PersistentIdentifier] = []
        var newPinned: [Bool] = []
        var newMatrix: [Float] = []
        for i in 0..<ids.count where keep[i] {
            newIds.append(ids[i])
            newPinned.append(pinned[i])
            let start = i * dim
            newMatrix.append(contentsOf: matrix[start..<(start + dim)])
        }
        ids = newIds
        pinned = newPinned
        matrix = newMatrix
    }

    func search(
        query: [Double],
        topK: Int,
        pinBonus: Float = 0.15
    ) -> [(id: PersistentIdentifier, score: Float)] {
        guard loaded, !ids.isEmpty, dim > 0, query.count == dim, topK > 0 else { return [] }
        let q = VectorMath.toFloat32Normalized(query)
        let rows = ids.count
        var scores = [Float](repeating: 0, count: rows)
        matrix.withUnsafeBufferPointer { m in
            q.withUnsafeBufferPointer { qp in
                scores.withUnsafeMutableBufferPointer { sp in
                    vDSP_mmul(
                        m.baseAddress!, 1,
                        qp.baseAddress!, 1,
                        sp.baseAddress!, 1,
                        vDSP_Length(rows),
                        1,
                        vDSP_Length(dim)
                    )
                }
            }
        }
        if pinBonus != 0 {
            for i in 0..<rows where pinned[i] { scores[i] += pinBonus }
        }
        return VectorMath.topK(scores: scores, k: topK, minScore: -Float.infinity) { _ in true }
            .map { (ids[$0.0], $0.1) }
    }

    private func append(id: PersistentIdentifier, isPinned: Bool, vector: [Double], expectedDim: Int) {
        ids.append(id)
        pinned.append(isPinned)
        matrix.reserveCapacity(matrix.count + expectedDim)
        matrix.append(contentsOf: VectorMath.toFloat32Normalized(vector))
    }
}

enum VectorMath {
    static func toFloat32Normalized(_ v: [Double]) -> [Float] {
        guard !v.isEmpty else { return [] }
        var out = [Float](repeating: 0, count: v.count)
        for i in 0..<v.count { out[i] = Float(v[i]) }
        var ss: Float = 0
        out.withUnsafeBufferPointer { bp in
            vDSP_svesq(bp.baseAddress!, 1, &ss, vDSP_Length(out.count))
        }
        let norm = sqrtf(ss)
        if norm > 1e-8 {
            var inv: Float = 1.0 / norm

            let count = vDSP_Length(out.count)
            out.withUnsafeMutableBufferPointer { bp in
                let base = bp.baseAddress!
                vDSP_vsmul(base, 1, &inv, base, 1, count)
            }
        }
        return out
    }

    /// Unordered bounded selection using a small max-heap style scan. O(n log k).
    static func topK(
        scores: [Float],
        k: Int,
        minScore: Float,
        includeIndex: (Int) -> Bool
    ) -> [(Int, Float)] {
        guard k > 0, !scores.isEmpty else { return [] }
        var heap: [(Int, Float)] = []
        heap.reserveCapacity(k + 1)
        for i in 0..<scores.count {
            let s = scores[i]
            if s < minScore { continue }
            if !includeIndex(i) { continue }
            if heap.count < k {
                heap.append((i, s))
                if heap.count == k { heap.sort { $0.1 < $1.1 } }
            } else if s > heap[0].1 {
                heap[0] = (i, s)
                var j = 0
                while true {
                    let l = 2 * j + 1, r = 2 * j + 2
                    var smallest = j
                    if l < heap.count && heap[l].1 < heap[smallest].1 { smallest = l }
                    if r < heap.count && heap[r].1 < heap[smallest].1 { smallest = r }
                    if smallest == j { break }
                    heap.swapAt(j, smallest)
                    j = smallest
                }
            }
        }
        return heap.sorted { $0.1 > $1.1 }
    }
}

import Foundation
import AVFoundation
import Speech
import Observation

@MainActor
@Observable
final class VoiceService: NSObject {
    static let shared = VoiceService()

    var isListening: Bool = false
    var isSpeaking: Bool = false
    var liveTranscript: String = ""
    var inputLevel: Double = 0
    var lastError: String?

    @ObservationIgnored private let audioEngine = AVAudioEngine()
    @ObservationIgnored private var recognitionRequest: SFSpeechAudioBufferRecognitionRequest?
    @ObservationIgnored private var recognitionTask: SFSpeechRecognitionTask?
    @ObservationIgnored private let synthesizer = AVSpeechSynthesizer()
    @ObservationIgnored private var recognizer: SFSpeechRecognizer?
    @ObservationIgnored private var onFinal: ((String) -> Void)?
    @ObservationIgnored private var onSpeechEnd: (() -> Void)?
    @ObservationIgnored private var cancellationID: UUID?
    @ObservationIgnored private var ttsCancellationID: UUID?

    override init() {
        super.init()
        recognizer = SFSpeechRecognizer(locale: Locale.current) ?? SFSpeechRecognizer(locale: Locale(identifier: "en-US"))
        synthesizer.delegate = self
    }

    // MARK: - Permissions

    func requestPermissions() async -> Bool {
        let speechStatus: SFSpeechRecognizerAuthorizationStatus = await withCheckedContinuation { cont in
            SFSpeechRecognizer.requestAuthorization { status in cont.resume(returning: status) }
        }
        guard speechStatus == .authorized else {
            lastError = "Speech recognition not authorized."
            return false
        }
        let micOK: Bool = await withCheckedContinuation { cont in
            AVAudioApplication.requestRecordPermission { cont.resume(returning: $0) }
        }
        if !micOK { lastError = "Microphone not authorized." }
        return micOK
    }

    /// Starts listening for speech input with continuous transcript updates.
    /// - Parameters:
    ///   - onFinal: Called with the final transcript when speech ends.

    @discardableResult
    func startListening(permissionsAlreadyGranted: Bool = false, onFinal: @escaping (String) -> Void) async -> Bool {
        if !permissionsAlreadyGranted {
            guard await requestPermissions() else { return false }
        }
        resetListeningState()
        stopSpeaking()
        lastError = nil

        do {

    let session = AVAudioSession.sharedInstance()
    try session.setCategory(.playAndRecord, mode: .spokenAudio, options: [.duckOthers, .defaultToSpeaker, .allowBluetoothHFP])
    try session.setActive(true, options: .notifyOthersOnDeactivation)
} catch {
    lastError = "Audio session error: \(error.localizedDescription)"
    return false
}

let request = SFSpeechAudioBufferRecognitionRequest()
request.shouldReportPartialResults = true
if #available(iOS 16, *) { request.addsPunctuation = true }
recognitionRequest = request

self.onFinal = onFinal
liveTranscript = ""

guard let recognizer, recognizer.isAvailable else {
    lastError = "Speech recognizer unavailable."
    stopListening()
    return false
}

cancellationID = AppCancellationBus.shared.registerCancellation({ [weak self] in
    Task { @MainActor [weak self] in self?.stopListening() }
}, category: .voiceRecognition)

recognitionTask = recognizer.recognitionTask(with: request) { [weak self] result, error in
    guard let self else { return }
    Task { @MainActor in
        if let result {
            self.liveTranscript = result.bestTranscription.formattedString
            if result.isFinal {
                let text = self.liveTranscript
                let onFinal = self.onFinal
                self.resetListeningState()
                if !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    onFinal?(text)
                }
            }
        }
        if error != nil {
            self.resetListeningState()
        }
    }
}

let input = audioEngine.inputNode
let format = input.outputFormat(forBus: 0)
input.removeTap(onBus: 0)
input.installTap(onBus: 0, bufferSize: 1024, format: format) { [weak self] buffer, _ in
    self?.recognitionRequest?.append(buffer)
    self?.updateLevel(from: buffer)
}

audioEngine.prepare()
do {
    try audioEngine.start()
    isListening = true
} catch {

        lastError = "Audio engine failed: \(error.localizedDescription)"
        stopListening()
        return false
    }
    return true
}

func stopListening() {
    resetListeningState()
}

private func resetListeningState() {
    if audioEngine.isRunning {
        audioEngine.stop()
    }
    audioEngine.inputNode.removeTap(onBus: 0)
    recognitionRequest?.endAudio()
    recognitionTask?.cancel()
    if let cancellationID {
        AppCancellationBus.shared.unregister(cancellationID, category: .voiceRecognition)
        self.cancellationID = nil
    }
    recognitionRequest = nil
    recognitionTask = nil
    onFinal = nil
    isListening = false
    inputLevel = 0
}

func finishListening() {
    recognitionRequest?.endAudio()
    if audioEngine.isRunning {
        audioEngine.stop()
    }
    audioEngine.inputNode.removeTap(onBus: 0)
}

private func updateLevel(from buffer: AVAudioPCMBuffer) {
    guard let data = buffer.floatChannelData?[0] else { return }
    let frames = Int(buffer.frameLength)
    guard frames > 0 else { return }
    var sum: Float = 0
    for i in 0..<frames { sum += data[i] * data[i] }
    let rms = sqrt(sum / Float(frames))
    let level = max(0, min(1, Double(rms) * 8))
    Task { @MainActor in
        self.inputLevel = level * 0.6 + self.inputLevel * 0.4
    }
}

// MARK: - Speaking

func speak(_ text: String, voiceID: String?, rate: Double, onComplete: (() -> Void)? = nil) {
    let trimmed = FinalOutputSanitizer.sanitizeUserVisibleText(text).text.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else { onComplete?(); return }
    onSpeechEnd = onComplete
    let utterance = AVSpeechUtterance(string: trimmed)
    if let voiceID, let v = AVSpeechSynthesisVoice(identifier: voiceID) {
        utterance.voice = v
    } else {
        utterance.voice = AVSpeechSynthesisVoice(language: Locale.current.identifier)
            ?? AVSpeechSynthesisVoice(language: "en-US")
    }
    utterance.rate = Float(max(0.1, min(0.8, rate)))
    utterance.pitchMultiplier = 1.0
    utterance.preUtteranceDelay = 0.02
    isSpeaking = true
    registerTTSCancellation()

        synthesizer.speak(utterance)
    }

    func speakChunk(_ text: String, voiceID: String?, rate: Double) {
        let trimmed = FinalOutputSanitizer.sanitizeUserVisibleText(text).text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        let utterance = AVSpeechUtterance(string: trimmed)
        if let voiceID, let v = AVSpeechSynthesisVoice(identifier: voiceID) {
            utterance.voice = v
        } else {
            utterance.voice = AVSpeechSynthesisVoice(language: Locale.current.identifier)
                ?? AVSpeechSynthesisVoice(language: "en-US")
        }
        utterance.rate = Float(max(0.1, min(0.8, rate)))
        isSpeaking = true
        registerTTSCancellation()
        synthesizer.speak(utterance)
    }

    /// Registers a handler to stop speaking on TTS cancellation.
    private func registerTTSCancellation() {
        unregisterTTSCancellation()
        ttsCancellationID = AppCancellationBus.shared.registerCancellation({ [weak self] in
            Task { @MainActor [weak self] in self?.stopSpeaking() }
        }, category: .tts)
    }

    private func unregisterTTSCancellation() {
        if let ttsCancellationID {
            AppCancellationBus.shared.unregister(ttsCancellationID, category: .tts)
            self.ttsCancellationID = nil
        }
    }

    func stopSpeaking() {
        if synthesizer.isSpeaking {
            synthesizer.stopSpeaking(at: .immediate)
        }
        unregisterTTSCancellation()
        isSpeaking = false
    }
}

extension VoiceService: AVSpeechSynthesizerDelegate {
    nonisolated func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didFinish utterance: AVSpeechUtterance) {
        Task { @MainActor in
            if !self.synthesizer.isSpeaking {
                self.unregisterTTSCancellation()
                self.isSpeaking = false
                let cb = self.onSpeechEnd
                self.onSpeechEnd = nil
                cb?()
            }
        }
    }

    nonisolated func speechSynthesizer(_ synthesizer: AVSpeechSynthesizer, didCancel utterance: AVSpeechUtterance) {
        Task { @MainActor in
            self.unregisterTTSCancellation()
            self.isSpeaking = false
            self.onSpeechEnd = nil
        }
    }
}

nonisolated enum VoiceCatalog {
    struct Entry: Identifiable, Hashable, Sendable {

        var id: String
        var name: String
        var language: String
        var quality: String
    }

    @MainActor
    static func available() -> [Entry] {
        AVSpeechSynthesisVoice.speechVoices()
            .filter {
                let currentCode = Locale.current.language.languageCode?.identifier ?? ""
                return $0.language.hasPrefix("en") || (!currentCode.isEmpty && $0.language.hasPrefix(currentCode))
            }
            .sorted { $0.name < $1.name }
            .map { v in
                let q: String
                switch v.quality {
                case .premium: q = "Premium"
                case .enhanced: q = "Enhanced"
                default: q = "Default"
                }
                return Entry(id: v.identifier, name: v.name, language: v.language, quality: q)
            }
    }
}

