enum RuntimeMetricErrorSanitizer {
    static func code(for error: Error) -> String {
        switch error {
        case let error as AssistantKernel.KernelError:
            switch error {
            case .unsupportedTaskForTextTurn: return "unsupported_task_for_text_turn"
            case .unsupportedRuntimeForTextTurn: return "unsupported_runtime_for_text_turn"
            }
        case let error as LocalRuntimeError:
            switch error {
            case .unavailable: return "runtime_unavailable"
            case .generationNotImplemented(let runtime): return "generation_not_implemented_\(runtime.rawValue)"
            }
        case let error as CoreMLRuntimeError:
            switch error {
            case .unsupportedOnPlatform: return "coreml_unsupported"
            case .modelNotConfigured: return "coreml_model_not_configured"
            case .modelNotFound: return "coreml_model_not_found"
            case .incompatibleModel: return "coreml_incompatible_model"
            case .shapeMismatch: return "coreml_shape_mismatch"
            case .embeddingExtractionNotImplemented: return "coreml_embedding_extraction_not_implemented"
            case .computeFailure: return "coreml_compute_failure"
            }
        case is CancellationError:
            return "cancelled"
        default:
            return String(describing: type(of: error))
        }
    }
}

import Foundation

actor RuntimeMetricsStore {
    static let shared = RuntimeMetricsStore()

    private let fileURL: URL
    private let encoder = JSONEncoder()
    private let decoder = JSONDecoder()

    init(fileURL: URL? = nil) {
        if let fileURL {
            self.fileURL = fileURL
        } else {
            let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first ?? URL(fileURLWithPath: NSTemporaryDirectory())
            let dir = base.appendingPathComponent("Lumen", isDirectory: true)
            try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
            self.fileURL = dir.appendingPathComponent("runtime-metrics.jsonl")
        }
        encoder.dateEncodingStrategy = .iso8601
        decoder.dateDecodingStrategy = .iso8601
    }

    func appendMetric(_ metric: RuntimeMetric) async throws {
        let line = try encoder.encode(metric) + Data([0x0A])
        guard DiskWriteBudget.shared.canWrite(bytes: line.count, category: .logs) else { return }
        if !FileManager.default.fileExists(atPath: fileURL.path) {
            let created = FileManager.default.createFile(atPath: fileURL.path, contents: line)
            if !created {
                try line.write(to: fileURL, options: .atomic)
            }
            DiskWriteBudget.shared.recordWrite(bytes: line.count, category: .logs)
            return
        }
        let handle = try FileHandle(forWritingTo: fileURL)
        defer { try? handle.close() }
        try handle.seekToEnd()
        try handle.write(contentsOf: line)
        DiskWriteBudget.shared.recordWrite(bytes: line.count, category: .logs)
    }

    func recentMetrics(limit: Int) async throws -> [RuntimeMetric] {
        guard FileManager.default.fileExists(atPath: fileURL.path) else { return [RuntimeMetric]() }
        let data = try Data(contentsOf: fileURL)
        let lines = data.split(separator: 0x0A)
        let decoded: [RuntimeMetric] = lines.compactMap { try? decoder.decode(RuntimeMetric.self, from: Data($0)) }
        return Array(decoded.suffix(max(0, limit)))
    }

    func compact(maxEntries: Int) async throws {
        let recent = try await recentMetrics(limit: maxEntries)
        let newData = try recent.map { try encoder.encode($0) + Data([0x0A]) }.reduce(Data(), +)

        guard DiskWriteBudget.shared.canWrite(bytes: newData.count, category: .logs) else { return }
        try newData.write(to: fileURL, options: .atomic)
        DiskWriteBudget.shared.recordWrite(bytes: newData.count, category: .logs)
    }
}

import Foundation
