    let mutation = VoiceKernelEventReducer.reduce(.error("Model failed."), state: &state, lastUserMessage: "Prompt", routing: Self.chatRouting)

    XCTAssertTrue(mutation.textChanged)
    XCTAssertTrue(mutation.shouldSpeakPending)
