#!/usr/bin/env python3
"""Patch generated Info.plist build settings for MSAL iOS broker callback support.

Lumen uses GENERATE_INFOPLIST_FILE=YES, so there is no checked-in Info.plist to edit.
The app target stores generated plist entries as INFOPLIST_KEY_* build settings in
`ios/Lumen.xcodeproj/project.pbxproj`.

This script inserts the required MSAL URL scheme and broker query schemes into the
Lumen target Debug/Release build settings idempotently.
"""
from __future__ import annotations

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PROJECT = ROOT / "ios" / "Lumen.xcodeproj" / "project.pbxproj"

URL_TYPES_TEMPLATE = '''\t\t\t\tINFOPLIST_KEY_CFBundleURLTypes = (
\t\t\t\t\t{
\t\t\t\t\t\tCFBundleURLName = "{bundle_id}";
\t\t\t\t\t\tCFBundleURLSchemes = (
\t\t\t\t\t\t\t"msauth.{bundle_id}",
\t\t\t\t\t\t);
\t\t\t\t\t},
\t\t\t\t);
'''

QUERY_SCHEMES = '''\t\t\t\tINFOPLIST_KEY_LSApplicationQueriesSchemes = (
\t\t\t\t\tmsauth,
\t\t\t\t\tmsauthv2,
\t\t\t\t\tmsauthv3,
\t\t\t\t);
'''

def find_matching_brace(text: str, open_index: int) -> int:
    depth = 0
    in_string = False
    escaped = False
    for index in range(open_index, len(text)):
        char = text[index]
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            continue
        if char == '"':
            in_string = True
        elif char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return index
    raise RuntimeError("Could not find matching brace")


def replace_or_insert_setting(block: str, key: str, value: str) -> str:
    needle = f"\t\t\t\t{key} = "
    existing = block.find(needle)
    if existing >= 0:
        value_start = existing
        cursor = existing + len(needle)
        depth = 0
        in_string = False
        escaped = False
        while cursor < len(block):
            char = block[cursor]
            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
            else:
                if char == '"':

                    in_string = True
                elif char in "({":
                    depth += 1
                elif char in ")}":
                    depth -= 1
                elif char == ";" and depth == 0:
                    remainder_start = cursor + 1
                    while remainder_start < len(block) and block[remainder_start] in "\r\n":
                        remainder_start += 1
                    return block[:value_start] + value + block[remainder_start:]
            cursor += 1
        raise RuntimeError(f"Could not replace existing {key}")

    build_settings_open = block.find("buildSettings = {")
    if build_settings_open < 0:
        raise RuntimeError(f"Missing buildSettings block for {key}")
    insertion_point = block.find("\n", build_settings_open)
    if insertion_point < 0:
        raise RuntimeError(f"Could not find insertion point for {key}")
    return block[: insertion_point + 1] + value + block[insertion_point + 1 :]


def extract_setting(block: str, key: str) -> str | None:
    match = re.search(rf"^\s*{re.escape(key)}\s*=\s*([^;]+);", block, re.MULTILINE)
    if not match:
        return None
    return match.group(1).strip().strip('"')


def discover_target_config_ids(text: str, target_name: str) -> list[tuple[str, str]]:
    config_list_pattern = re.compile(
        rf'(?P<config_list>[A-Fa-f0-9]{{24}})\s+/\*\s+Build configuration list for PBXNativeTarget "{re.escape(target_name)}"\s+\*/\s*=\s*\{{',
        re.IGNORECASE,
    )
    config_list_match = config_list_pattern.search(text)
    if not config_list_match:
        raise RuntimeError(f"Missing configuration list for target {target_name}")

    config_list_id = config_list_match.group("config_list")
    list_open = config_list_match.end() - 1
    list_close = find_matching_brace(text, list_open)
    list_block = text[list_open : list_close + 1]

    build_configs_match = re.search(r"buildConfigurations = \((?P<body>.*?)\);", list_block, re.DOTALL)
    if not build_configs_match:
        raise RuntimeError(f"Missing buildConfigurations for target {target_name}")
    configs = re.findall(
        r"\b([A-Fa-f0-9]{24})\b\s*/\*\s*([^*]+)\s*\*/",
        build_configs_match.group("body"),
        re.MULTILINE,
    )
    if not configs:
        raise RuntimeError(f"No build configurations found for target {target_name}")

  done
  [[ -d /sys/firmware/efi ]] && echo "ok: UEFI firmware detected" || warn "UEFI firmware directory not found; target systems should boot UEFI/GPT"
  if command -v mokutil >/dev/null 2>&1; then mokutil --sb-state || true; else warn "mokutil unavailable; Secure Boot state not detected"; fi
  return "$status"
}

cmd_init_workspace() {
  local workdir="$DEFAULT_WORKDIR"
  while [[ $# -gt 0 ]]; do
    case "$1" in --workdir) need_value "$1" "${2:-}"; workdir="$2"; shift 2;; -h|--help) usage; return 0;; *) fail "unknown option for init-workspace: $1";; esac
  done
  mkdirs "$workdir"
  write_manifest "$workdir"
  cat >"$workdir/staging/TripleBoot/README.txt" <<'EOF_README'
TripleBoot USB

Boot this USB in UEFI mode. Ubuntu and Windows ISO files are staged for Ventoy.
macOS content, when present, is a lawful user-supplied rescue/OpenCore scaffold only;
this kit does not redistribute Apple installers or bypass Apple licensing.
EOF_README
  info "workspace ready: $workdir"
}

cmd_register_iso() {
  local workdir="$DEFAULT_WORKDIR" kind="" source="" dry_run=0
  while [[ $# -gt 0 ]]; do
    case "$1" in
      --workdir) need_value "$1" "${2:-}"; workdir="$2"; shift 2;;
      --kind) need_value "$1" "${2:-}"; kind="$2"; shift 2;;
      --source) need_value "$1" "${2:-}"; source="$2"; shift 2;;
      --dry-run) dry_run=1; shift;;
      *) fail "unknown option for register-iso: $1";;
    esac
  done
  [[ -n "$kind" && -n "$source" ]] || fail "register-iso requires --kind and --source"
  mkdirs "$workdir"
  case "$kind" in
    ubuntu) copy_payload "$source" "$workdir/isos/ubuntu" "$dry_run";;
    windows) copy_payload "$source" "$workdir/isos/windows" "$dry_run";;
    macos|osx-kvm) copy_payload "$source" "$workdir/macos" "$dry_run";;
    *) fail "kind must be ubuntu, windows, or macos";;
  esac
}

fetch() {
  local url="$1" dest="$2" dry_run="$3"
  mkdir -p "$(dirname "$dest")"
  if [[ "$dry_run" == "1" ]]; then
    info "dry-run: would download $url -> $dest"
  else
    curl -fL --retry 3 --connect-timeout 20 -o "$dest" "$url"
  fi
}

cmd_download_ubuntu() {
  local workdir="$DEFAULT_WORKDIR" version="26.04" edition="desktop" arch="amd64" dry_run=0 url="" checksum_url=""
  while [[ $# -gt 0 ]]; do
    case "$1" in
      --workdir) need_value "$1" "${2:-}"; workdir="$2"; shift 2;;
      --version) need_value "$1" "${2:-}"; version="$2"; shift 2;;

      --edition) need_value "$1" "${2:-}"; edition="$2"; shift 2;;
      --arch) need_value "$1" "${2:-}"; arch="$2"; shift 2;;
      --url) need_value "$1" "${2:-}"; url="$2"; shift 2;;
      --checksum-url) need_value "$1" "${2:-}"; checksum_url="$2"; shift 2;;
      --dry-run) dry_run=1; shift;;
      *) fail "unknown option for download-ubuntu: $1";;
    esac
  done
  local name="ubuntu-${version}-${edition}-${arch}.iso"
  [[ -n "$url" ]] || url="https://releases.ubuntu.com/${version}/${name}"
  [[ -n "$checksum_url" ]] || checksum_url="https://releases.ubuntu.com/${version}/SHA256SUMS"
  mkdirs "$workdir"
  fetch "$url" "$workdir/isos/ubuntu/$name" "$dry_run"
  fetch "$checksum_url" "$workdir/isos/ubuntu/SHA256SUMS" "$dry_run"
  if [[ "$dry_run" != "1" ]]; then
    verify_sha256sums_entry "$workdir/isos/ubuntu/SHA256SUMS" "$workdir/isos/ubuntu/$name"
  fi
}

cmd_download_ventoy() {
  local workdir="$DEFAULT_WORKDIR" version="" url="" sha256="" dry_run=0
  while [[ $# -gt 0 ]]; do
    case "$1" in
      --workdir) need_value "$1" "${2:-}"; workdir="$2"; shift 2;;
      --version) need_value "$1" "${2:-}"; version="$2"; shift 2;;
      --url) need_value "$1" "${2:-}"; url="$2"; shift 2;;
      --sha256) need_value "$1" "${2:-}"; sha256="$2"; shift 2;;
      --dry-run) dry_run=1; shift;;
      *) fail "unknown option for download-ventoy: $1";;
    esac
  done
  [[ -n "$version" || -n "$url" ]] || fail "download-ventoy requires --version or --url so the release is explicit"
  [[ -n "$url" ]] || url="https://github.com/ventoy/Ventoy/releases/download/v${version}/ventoy-${version}-linux.tar.gz"
  local archive="$workdir/downloads/$(basename "$url")"
  mkdirs "$workdir"
  fetch "$url" "$archive" "$dry_run"
  if [[ "$dry_run" != "1" ]]; then
    if [[ -n "$sha256" ]]; then
      local actual
      actual="$(sha256_file "$archive")"
      [[ "$actual" == "$sha256" ]] || fail "Ventoy checksum mismatch: expected $sha256 got $actual"
    else
      warn "no --sha256 provided; archive downloaded but not extracted"
      return 0
    fi
    tar -xzf "$archive" -C "$workdir/ventoy" --strip-components=1
    [[ -x "$workdir/ventoy/Ventoy2Disk.sh" ]] || fail "Ventoy2Disk.sh not found after extraction"
  fi
}

