    suffix = 1
    while True:
        regenerated = f"{candidate}Invalid{suffix}"

        if regenerated not in existing_tool_ids:
            return regenerated
        suffix += 1


def _invalid_variant(tool_id: str) -> str:
    parts = tool_id.split(".")
    if len(parts) < 2:
