def _extract_contract_catalog(self, text: str, source: str) -> dict[str, list[ToolArgumentManifest]]:
    match = re.search(
        r"enum\s+ToolArgumentContractCatalog\b.*?static\s+func\s+arguments\b.*?switch\b.*?\{(?P<body>.*?)\n\s*}\s*\n\s*}",
        text,
        flags=re.S,
    )
    if not match:
        return {}

    contracts: dict[str, list[ToolArgumentManifest]] = {}
    body = match.group("body")
    case_pattern = re.compile(r"(?P<label>case\s+.*?|default)\s*:\s*(?P<body>.*?)(?=\n\s*(?:case\s+|default\s*:)|\Z)", flags=re.S)
    for case_match in case_pattern.finditer(body):
        label = case_match.group("label")
        if label.strip().startswith("default"):
            continue
        tool_ids = [tool_id for tool_id in string_literals(label) if self._looks_like_tool_id(tool_id)]
        if not tool_ids:
            continue
        arguments = self._extract_contract_return_arguments(case_match.group("body"), source)
        for tool_id in tool_ids:
            contracts[tool_id] = arguments
    return contracts

def _extract_contract_return_arguments(self, body: str, source: str) -> list[ToolArgumentManifest]:
    return_match = re.search(r"\breturn\s+(?P<value>.*)", body, flags=re.S)
    if not return_match:
        return []
    value = return_match.group("value").strip()
    if value.startswith("[]"):
        return []

    args: list[ToolArgumentManifest] = []
    for arg_block in balanced_call_blocks(value, ".init"):
        name = self._first_string(arg_block)
        if not name:

    if not body or body.lower() in {"none", "no args", "n/a"}:
        return []

    specs: list[tuple[str, bool]] = []
    optional_group = False
    for raw in re.split(r"[,;]", body):
        token = raw.strip()
        if not token:
            continue
        token = re.sub(r"\(.*?\)", "", token).strip()
        token_lower = token.lower()
        token_optional = optional_group or token_lower.startswith("optional ")
        token = OPTIONAL_PREFIX_PATTERN.sub("", token).strip()
        if token.lower().startswith("plus "):
            token = token[5:].strip()
        token = re.sub(r"\s+depending on (?:the )?schedule\b.*$", "", token, flags=re.I).strip()
        token = re.sub(r"\s+true\s*/\s*false\b.*$", "", token, flags=re.I).strip()
        token = re.sub(r"\s+true\s+or\s+false\b.*$", "", token, flags=re.I).strip()
        if not token:
            optional_group = True
            continue
        for alias in re.split(r"\s+or\s+|/", token):
            alias = alias.strip()
            if not alias:
                continue
            parts = alias.split()
            name = parts[0].strip("`'\".:") if parts else alias.strip("`'\".:")
            if name.lower() in {"none", "args", "arg"}:
                continue
            if name.lower() in ARG_TYPE_HINT_WORDS and len(parts) > 1:
                continue
            if not ARG_NAME_PATTERN.fullmatch(name):
                continue
            if not any(existing == name for existing, _ in specs):
                specs.append((name, token_optional))
        optional_group = token_optional

    return [
        ToolArgumentManifest(
            name=name,
            type=ToolDefinitionExtractor._infer_arg_type_from_name(name),
            required=not optional,
            description=f"Inferred from ToolDefinition description Args contract: {body}",
            source=source,
        )
        for name, optional in specs
    ]

@staticmethod
def _infer_arg_type_from_name(name: str) -> str:
    lowered = name.lower()
    if any(marker in lowered for marker in ("minutes", "seconds", "count", "limit", "months", "duration", "interval")):
        return "number"

    if lowered in {"repeats"} or lowered.startswith("is") or lowered.startswith("has") or lowered.startswith("should"):
        return "bool"
    if lowered in {"query", "title", "subject", "body", "message", "text", "recipient", "number", "destination", "location", "city", "url", "name", "kind", "content", "schedule", "timestamp", "attime", "id", "email", "to", "prompt"}:
        return "string"
    return "string"

@staticmethod
def _fallback_tool_literals(text: str) -> list[str]:
    values: list[str] = []
    for match in TOOL_ID_LABEL_PATTERN.finditer(text):
        value = match.group(1)
        if ToolDefinitionExtractor._looks_like_tool_id(value):
            values.append(value)
    for match in TOOL_ID_COLLECTION_PATTERN.finditer(text):
        for literal in string_literals(match.group("body")):
            if ToolDefinitionExtractor._looks_like_tool_id(literal):
                values.append(literal)
    return list(dict.fromkeys(values))

@staticmethod
def _first_string(block: str) -> str | None:
    vals = string_literals(block)
    return vals[0] if vals else None

@staticmethod
def _infer_type_from_block(block: str) -> str:
    lowered = block.lower()
    if "double" in lowered or "float" in lowered or "number" in lowered:
        return "number"
    if "int" in lowered:
        return "number"
    if "bool" in lowered:
        return "bool"
    if "array" in lowered or "list" in lowered:
        return "array"
    if "object" in lowered or "dictionary" in lowered:
        return "object"
    return "string"

@staticmethod
def _normalize_type(raw: str) -> str:
    value = raw.strip().lower().replace(".", "")
    mapping = {
        "str": "string",
        "string": "string",
        "text": "string",
        "double": "number",
        "float": "number",
        "number": "number",
        "int": "number",
        "integer": "number",
        "bool": "bool",
        "boolean": "bool",
        "array": "array",
        "list": "array",
        "object": "object",
        "dictionary": "object",
        "dict": "object",
        "nil": "null",
        "none": "null",
        "null": "null",
    }

    return mapping.get(value, value or "string")

@staticmethod
def _looks_like_tool_id(value: str) -> bool:
    return bool(TOOL_ID_PATTERN.fullmatch(value))

